NAME = 'SloKJV: Slovenian translation of Holy Bible King James Version (1769)'
BOOK = 'Ezekiel'

CHAPTERS = {
    1: {
        1: 'Pripetilo se je torej v tridesetem letu, v četrtem mesecu, na peti dan meseca, ko sem bil med ujetniki pri reki Kebár, da so se odprla nebesa in zagledal sem Božja videnja.',
        2: 'Na peti dan meseca, kar je bilo peto leto ujetništva kralja Jojahína,',
        3: 'je prišla Gospodova beseda izrecno k duhovniku Ezekielu, Buzijevemu sinu, v deželi Kaldejcev, pri reki Kebár in tam je bila nad njim Gospodova roka.',
        4: 'Pogledal sem in glej, vrtinčast veter je prišel iz severa, velik oblak in ogenj ga je obsegal in okoli njega je bil sijaj in iz njegove srede kakor jantarjeva barva ven iz srede ognja.',
        5: 'Prav tako je iz njegove srede prišla podobnost štirih živih ustvarjenih bitij. In to je bil njihov videz; imela so podobnost človeka.',
        6: 'Vsako je imelo štiri obraze in vsako je imelo štiri peruti.',
        7: 'Njihova stopala so bila ravna stopala in podplat njihovih stopal je bil podoben telečjemu kopitu, in lesketala so se podobno barvi zloščenega brona.',
        8: 'Pod svojimi perutmi, na svojih štirih straneh, so imela človeške roke in ta štiri so imela svoje obraze in svoje peruti.',
        9: 'Njihove peruti so bile pridružene druga k drugi; niso se obračala, ko so hodila; šla so vsaka naravnost naprej.',
        10: 'Kar zadeva podobnost njihovih obrazov, ta štiri so imela človeški obraz in obraz leva na desni strani in ta štiri so imela obraz vola na levi strani; ta štiri so imela tudi obraz orla.',
        11: 'Takšni so bili njihovi obrazi. Njihove peruti so bile iztegnjene navzgor; dve peruti vsakega sta bili pridruženi druga k drugi, dve pa sta pokrivali njihova telesa.',
        12: 'Hodila so vsako naravnost naprej. Kamor naj bi šel duh, [tja] so šla, in niso se obračala, ko so hodila.',
        13: 'Kar se tiče podobnosti živih ustvarjenih bitij, je bil njihov videz podoben gorečemu ognjenemu oglju in podoben videzu svetilk. Ta je šel gor in dol med živimi ustvarjenimi bitji in ogenj je bil svetel in iz ognja se je dvigovalo bliskanje.',
        14: 'Živa ustvarjena bitja so tekala in se vračala kakor videz bliska strele.',
        15: 'Medtem ko sem gledal živa ustvarjena bitja, sem na zemlji zagledal eno kolo poleg živih ustvarjenih bitij, z njegovimi štirimi obrazi.',
        16: '§ Videz koles in njihovo delo je bilo podobno barvi berila. Ta štiri so imela eno podobnost, in njihov videz in njihovo delo je bilo, kakor bi bilo kolo v sredi kolesa.',
        17: 'Ko so hodila, so hodila na svoje štiri strani, in ko so hodila, se niso obračala.',
        18: 'Kar se tiče njihovih platišč, so bila tako visoka, da so bila grozna, in njihova platišča so bila polna oči naokoli teh štirih.',
        19: 'Ko so živa ustvarjena bitja hodila, so poleg njih šla kolesa. In ko so bila živa ustvarjena bitja dvignjena z zemlje, so bila dvignjena kolesa.',
        20: 'Kamor naj bi šel duh, so šla, tja naj bi šel njihov duh, in kolesa so bila dvignjena nasproti njih, kajti v kolesih je bil duh živega ustvarjenega bitja.',
        21: 'Ko so tista šla, so šla ta; in ko so tista stala, so stala ta; in ko so bila tista dvignjena z zemlje, so bila kolesa dvignjena nasproti njih, kajti v kolesih je bil duh živega ustvarjenega bitja.',
        22: 'Podobnost nebesnega svoda nad glavami živega ustvarjenega bitja je bila kakor barva strašnega kristala, razprostrtega zgoraj, nad njihovimi glavami.',
        23: '§ Pod nebesnim svodom so bile njihove peruti ravne druga proti drugi. Vsako je imelo dve, ki sta pokrili na tej strani in vsako je imelo dve, ki sta pokrili na oni strani njihovih teles.',
        24: 'In ko so hodila, sem slišal šum njihovih peruti, podoben hrumenju velikih vodá, kakor glas Vsemogočnega, glas govora kakor hrup vojske. Ko so stala, so svoje peruti povesila.',
        25: '§ Bil je glas izpod nebesnega svoda, ki je bil nad njihovimi glavami, ko so stala in spustila svoje peruti.',
        26: 'Nad nebesnim svodom, ki je bil nad njihovimi glavami, je bila podobnost prestola, kakor videz kamna safira. Na podobnosti prestola je bila podobnost kakor videz človeka nad njim.',
        27: 'Videl sem kakor barvo jantarja, kakor videz ognja okrog in okrog znotraj njega, od videza njegovih ledij navzgor in celo od videza njegovih ledij navzdol sem videl, kakor bi bil videz ognja in ta je imel sijaj vsenaokrog.',
        28: 'Kakor videz mavrice, ki je na oblaku na deževen dan, takšen je bil videz sijaja naokoli. To je bil videz podobnosti Gospodove slave. Ko sem to zagledal, sem padel na svoj obraz in slišal glas nekoga, ki je spregovoril.',
    },
    2: {
        1: 'Rekel mi je: »Človeški sin, vstani na svoja stopala in spregovoril ti bom.«',
        2: 'Ko mi je spregovoril, je vame vstopil duh in me postavil na moja stopala, da sem slišal tistega, ki mi je spregovoril.',
        3: 'Rekel mi je: »Človeški sin, pošiljam te k Izraelovim otrokom, k upornemu narodu, ki se je uprl zoper mene. Oni in njihovi očetje so se pregrešili zoper mene, celó do točno tega dne.',
        4: 'Kajti predrzni otroci so in trdega srca in jaz te pošljem k njim, ti pa jim boš rekel: ›Tako govori Gospod Bog.‹',
        5: 'In oni, bodisi bodo slišali, bodisi se bodo zadržali (kajti uporna hiša so), bodo vendar vedeli, da je bil med njimi prerok.',
        6: 'Ti pa, človeški sin, se jih ne boj niti se ne boj njihovih besed, čeprav bodo s teboj osat in trnje in prebivaš med škorpijoni. Ne boj se njihovih besed niti ne bodi zaprepaden ob njihovih pogledih, čeprav so uporna hiša.',
        7: 'Govoril jim boš moje besede, bodisi bodo slišali, bodisi se bodo zadržali, kajti najbolj uporni so.',
        8: 'Toda ti, človeški sin, poslušaj, kaj ti povem: ›Ne bodi uporen kakor ta uporna hiša. Odpri svoja usta in pojej, kar ti dajem.‹«',
        9: 'Ko sem pogledal, glej, je bila k meni poslana roka, in glej, zvitek knjige je bil v njej',
        10: 'in razprostrl ga je pred menoj. Popisan je bil znotraj in zunaj in na njem so bile zapisane žalostinke, žalovanja in gorje.',
    },
    3: {
        1: 'Poleg tega mi je rekel: »Človeški sin, jej, kar najdeš. Pojej ta zvitek in pojdi, govori Izraelovi hiši.«',
        2: 'Tako sem odprl svoja usta in dal mi je, da sem pojedel ta zvitek.',
        3: 'Rekel mi je: »Človeški sin, stôri svojemu trebuhu, da jé in svojo notranjost napolni s tem zvitkom, ki ti ga dajem.« Potem sem to pojedel in v mojih ustih je bil zaradi sladkosti kakor med.',
        4: 'Rekel mi je: »Človeški sin, pojdi, stopi k Izraelovi hiši in jim govori z mojimi besedami.',
        5: 'Kajti nisi poslan k ljudstvu tujega govora in trdega jezika, temveč k Izraelovi hiši,',
        6: 'ne k mnogim ljudstvom tujega govora in trdega jezika, katerih besed ne moreš razumeti. Zagotovo, če bi te poslal k njim, bi ti prisluhnili.',
        7: 'Toda Izraelova hiša ti ne bo hotela prisluhniti, kajti nočejo mi prisluhniti, kajti vsa Izraelova hiša je predrzna in trdosrčna.',
        8: 'Glej, tvoj obraz sem otrdil zoper njihove obraze in tvoje čelo zoper njihova čela.',
        9: 'Kakor je diamant trši kakor kremen, [tako] sem naredil tvoje čelo. Ne boj se jih niti ne bodi zaprepaden ob njihovih pogledih, kajti uporna hiša so.«',
        10: 'Poleg tega mi je rekel: »Človeški sin, vse moje besede, ki ti jih bom govoril, sprejmi v svoje srce in poslušaj s svojimi ušesi.',
        11: 'Pojdi, stopi k tistim iz ujetništva, k otrokom svojega ljudstva in jim govori ter jim povej: ›Tako govori Gospod Bog, bodisi bodo poslušali ali bodisi se bodo zadržali.‹«',
        12: 'Potem me je duh vzel gor in za seboj sem zaslišal glas velikega hitenja, rekoč: »Blagoslovljena bodi Gospodova slava iz njegovega kraja.«',
        13: 'Slišal sem tudi šum peruti živih ustvarjenih bitij, ki so se dotikala druga druge in hrup koles nasproti njih in šum velikega hitenja.',
        14: 'Tako me je duh dvignil in me odnesel in šel sem v grenkobi, v vročici svojega duha, toda Gospodova roka je bila močna nad menoj.',
        15: 'Potem sem prišel k tistim iz ujetništva pri Tel Abíbu, ki prebivajo pri reki Kebár in se usedel, kjer so sedeli in osupel ostal tam med njimi sedem dni.',
        16: 'Pripetilo se je ob koncu sedmih dni, da je k meni prišla Gospodova beseda, rekoč:',
        17: '»Človeški sin, naredil sem te stražarja Izraelovi hiši, zato poslušaj besedo pri mojih ustih in jim daj svarilo od mene.',
        18: 'Ko rečem zlobnemu: ›Gotovo boš umrl,‹ pa mu ne daješ svarila niti ne govoriš, da zlobnega posvariš pred njegovo zlobno potjo, da bi rešil njegovo življenje, bo ta isti zlobni človek umrl v svoji krivičnosti, toda njegovo kri bom zahteval iz tvoje roke.',
        19: '§ Vendar če posvariš zlobnega, pa se ta ne odvrne od svoje zlobnosti niti od svoje zlobne poti, bo umrl v svoji krivičnosti, toda ti si osvobodil svojo dušo.«',
        20: 'Ponovno: »Kadar se pravičen človek odvrne od svoje pravičnosti in zagreši krivičnost in predenj položim kamen spotike, bo umrl; ker mu nisi dal svarila, bo umrl v svojem grehu in njegove pravičnosti, ki jo je storil, se ne bo spominjalo, temveč bom njegovo kri zahteval iz tvoje roke.',
        21: 'Vendar če posvariš pravičnega človeka, da pravični ne greši in ta ne greši, bo zagotovo živel, ker je posvarjen; tudi ti si osvobodil svojo dušo.«',
        22: 'Tam je bila nad menoj Gospodova roka in rekel mi je: »Vstani, pojdi naprej na ravnino in tam bom govoril s teboj.«',
        23: 'Potem sem vstal in odšel naprej na ravnino. Glej, tam je stala Gospodova slava kakor slava, ki sem jo videl pri reki Kebár, in padel sem na svoj obraz.',
        24: 'Potem je vame vstopil duh in me postavil na moja stopala in spregovoril z menoj ter mi rekel: »Pojdi, zapri se znotraj svoje hiše.',
        25: 'Toda ti, oh človeški sin, glej, nate bodo dali vezi in te zvezali z njimi in ne boš šel ven mednje,',
        26: 'jaz pa bom tvoj jezik prilepil k nebu tvojih ust, da boš nem in jim ne boš grajavec, kajti uporna hiša so.',
        27: 'Toda ko jaz spregovorim s teboj, bom odprl tvoja usta in ti jim boš rekel: ›Tako govori Gospod Bog: ›Kdor posluša, naj sliši, in kdor se zadrži, naj se zadržuje, kajti uporna hiša so.‹«',
    },
    4: {
        1: '»Tudi ti, človeški sin, si vzemi opeko in jo položi pred seboj in na njej upodobi mesto, celó [prestolnico] Jeruzalem,',
        2: 'in postavi obleganje zoper njo in zgradi utrdbo zoper njo in nasuj nasip zoper njo. Postavi tudi tabor zoper njo in naokoli zoper njo razpostavi oblegovalne ovne.',
        3: 'Poleg tega si vzemi železno ponev in jo postavi za železen zid med seboj in mestom, in naravnaj svoj obraz zoper njo in ta bo oblegana, ti pa boš postavil oblegovanje zoper njo. To bo znamenje Izraelovi hiši.',
        4: 'Lezi tudi na svojo levo stran in nanjo položi krivičnost Izraelove hiše. Glede na število dni, ko boš ležal na tej, boš nosil njihovo krivičnost.',
        5: 'Kajti nate sem položil leta njihove krivičnosti, glede na število dni, tristo devetdeset dni. Tako boš nosil krivičnost Izraelove hiše.',
        6: 'Ko jih dopolniš, ponovno lezi na svojo desno stran in štirideset dni boš nosil krivičnost Judove hiše. Določil sem ti vsak dan za leto.',
        7: 'Zato boš svoj obraz naravnal proti obleganju [prestolnice] Jeruzalem in tvoj laket bo odkrit in prerokoval boš zoper njo.',
        8: 'Glej, nate bom položil vezi in ne boš se obrnil iz ene strani na drugo, dokler ne dokončaš dni svojega obleganja.',
        9: 'K sebi vzemi tudi pšenico, ječmen, fižol, lečo, proso in piro ter jih stresi v eno posodo in iz tega zamesi kruh; glede na število dni, ki jih boš preležal na svoji strani, tristo devetdeset dni boš jedel od tega.',
        10: 'Tvoja hrana, ki jo boš jedel, bo po teži, dvajset šeklov na dan. Od časa do časa jo boš jedel.',
        11: 'Tudi vodo boš pil po meri, šesti del vrča. Od časa do časa [jo] boš pil.',
        12: '§ To boš jedel kakor ječmenove kolače in to boš spekel z iztrebkom, ki prihaja iz človeka, v njihovem pogledu.«',
        13: 'Gospod je rekel: »Celo tako bodo Izraelovi otroci jedli svoj omadeževani kruh med pogani, kamor jih bom pognal.«',
        14: 'Potem sem rekel: »Ah, Gospod Bog! Glej, moja duša ni bila oskrunjena, kajti od svoje mladosti, celo do sedaj, nisem jedel od tega, kar samo umre ali je raztrgano na koščke; niti v moja usta ni prišlo gnusno meso.«',
        15: 'Potem mi je rekel: »Glej! Dajem ti kravji iztrebek za človeški iztrebek in svoj kruh boš pripravil s tem.«',
        16: 'Poleg tega mi je rekel: »Človeški sin, glej, zlomil bom oporo kruha v [prestolnici] Jeruzalem. Kruh bodo jedli po teži in s skrbnostjo in vodo bodo pili po meri in z osuplostjo,',
        17: 'da jim bo lahko primanjkovalo kruha in vode in bodo osupli eden z drugim in shirali zaradi svoje krivičnosti.«',
    },
    5: {
        1: '»Ti pa, človeški sin, si vzemi oster nož, vzemi si brivčevo britev in ji povzroči, da gre čez tvojo glavo in po tvoji bradi. Potem si vzemi tehtnico, da stehtaš in razdeliš lase.',
        2: 'Z ognjem boš sežgal tretjino v sredi mesta, ko se dopolnijo dnevi obleganja. Vzel boš tretjino in okoli nje udarjal z nožem. Tretjino boš raztrosil v vetru, jaz pa bom za njimi izvlekel meč.',
        3: 'Od teh boš vzel malo po številu in jih povezal v krajce svojega oblačila.',
        4: 'Potem ponovno vzemi od teh in jih vrzi v sredo ognja in jih sežgi v ognju, kajti od teh bo prišel ogenj v vso Izraelovo hišo.«',
        5: 'Tako govori Gospod Bog: »To je [prestolnica] Jeruzalem. Postavil sem jo v sredo narodov in dežel, ki so naokoli nje.',
        6: 'Moje sodbe je spremenila v zlobnost bolj kakor narodi in moje zakone bolj kakor dežele, ki so okoli nje, kajti zavrnili so moje sodbe in moje zakone; niso hodili v njih.«',
        7: '§ Zato tako govori Gospod Bog: »Ker ste se pomnožili bolj kakor narodi, ki so okoli vas in niste hodili po mojih zakonih niti se niste držali mojih sodb niti niste delali glede na sodbe narodov, ki so naokoli vas,«',
        8: 'zato tako govori Gospod Bog: »Glej jaz, celo jaz, sem zoper tebe in v tvoji sredi bom izvršil sodbe pred očmi narodov.',
        9: 'V tebi bom storil to, česar nisem storil in ne bom več storil temu podobnega, zaradi vseh tvojih ogabnosti.',
        10: 'Zato bodo v tvoji sredi očetje jedli sinove in sinovi bodo jedli svoje očete. Izvršil bom sodbe v tebi in tvoj celotni preostanek bom razkropil na vse vetrove.',
        11: 'Zato, kakor jaz živim,« govori Gospod Bog, »zagotovo, ker si moje svetišče omadeževala z vsemi svojimi ostudnimi stvarmi in z vsemi svojimi ogabnostmi, zato bom tudi jaz tebe zmanjšal; niti moje oko ne bo prizaneslo, niti ne bom imel nobenega usmiljenja.',
        12: 'Tvoja tretjina bo umrla s kužno boleznijo in z lakoto bodo použiti v tvoji sredi. Tretjina bo padla pod mečem naokoli tebe, tretjino pa bom razkropil na vse vetrove in za njimi bom izvlekel meč.',
        13: 'Tako bo moja jeza dovršena in svoji razjarjenosti bom povzročil, da počiva nad njimi, jaz pa bom potolažen. Oni pa bodo vedeli, da sem jaz, Gospod, to govoril v svoji gorečnosti, ko sem svojo razjarjenost dovršil v njih.',
        14: 'Poleg tega te bom naredil opustošenje in grajo med narodi, ki so naokoli tebe, pred očmi vseh, ki hodijo mimo.',
        15: 'Tako bo to graja in zbadljivka, poučevanje in osuplost narodom, ki so naokoli tebe, ko bom v tebi izvršil sodbe v jezi, v razjarjenosti in v besnih ukorih. Jaz, Gospod, sem to govoril.',
        16: 'Ko bom nanje poslal zle puščice lakote, ki bodo za njihovo uničenje in ki jih bom poslal, da vas uničijo; in jaz bom razširil lakoto nad vami in zlomil vašo oporo kruha.',
        17: '§ Tako bom nad vas poslal lakoto in zle živali in te te bodo oropale in kužna bolezen in kri bosta šla skozte in nadte bom privedel meč. Jaz, Gospod, sem to govoril.«',
    },
    6: {
        1: 'K meni je prišla Gospodova beseda, rekoč:',
        2: '»Človeški sin, naravnaj svoj obraz proti Izraelovim goram in prerokuj zoper njih',
        3: 'in reci: ›Ve Izraelove gore, poslušajte besedo Gospoda Boga: ›Tako govori Gospod Bog goram in hribom, rekam in dolinam: ›Glejte jaz, celó jaz, bom nad vas privedel meč in uničil bom vaše visoke kraje.',
        4: 'Vaši oltarji bodo zapuščeni in vaši kipi bodo razbiti, in jaz bom vrgel dol vaše umorjene ljudi pred vaše malike.',
        5: 'Mrtva trupla Izraelovih otrok bom položil pred njihove malike in vaše kosti bom raztrosil okoli vaših oltarjev.',
        6: 'V vseh vaših bivališčih bodo mesta opustošena in visoki kraji bodo zapuščeni, da bodo vaši oltarji lahko opustošeni in zapuščeni in bodo vaši maliki lahko razbiti in prenehali [obstajati] in bodo vaše podobe lahko posekane in bodo vaša dela lahko odpravljena.',
        7: 'Umorjeni bodo padli v vaši sredi in spoznali boste, da jaz sem Gospod.',
        8: 'Vendar bom pustil ostanek, da boste lahko imeli nekatere, ki bodo pobegnili meču med narodi, ko boste razkropljeni po deželah.',
        9: '§ Tisti izmed vas, ki pobegnejo, se me bodo spomnili med narodi, kamor bodo odvedeni ujetniki, kajti zlomljen sem z njihovim vlačugarskim srcem, ki je odšlo od mene in z njihovimi očmi, ki se gredo vlačugat za njihovimi maliki in gnusili se bodo samim sebi zaradi zla, ki so ga zagrešili pri vseh svojih ogabnostih.',
        10: 'In spoznali bodo, da jaz sem Gospod in da nisem zaman rekel, da jim bom storil to zlo.‹«',
        11: 'Tako govori Gospod Bog: »Udari s svojo roko in zatopotaj s svojim stopalom ob tla ter reci: ›Ojoj za vse zle ogabnosti Izraelove hiše! Kajti padli bodo pod mečem, od lakote in kužne bolezni.',
        12: '§ Kdor je daleč, bo umrl od kužne bolezni, in kdor je blizu, bo padel pod mečem, in kdor preostaja in je oblegan, bo umrl od lakote. Tako bom nad njimi dovršil svojo razjarjenost.',
        13: 'Potem boste vedeli, da jaz sem Gospod, ko bodo njihovi pobiti ljudje [ležali] med njihovimi maliki, naokoli njihovih oltarjev, na vsakem visokem hribu, po vseh vrhovih gora in pod vsakim zelenim drevesom in pod vsakim debelim hrastom, [na] kraju, kjer so vsem svojim malikom darovali prijetno dišavo.',
        14: '§ Tako bom svojo roko iztegnil nadnje in njihovo deželo naredil zapuščeno, da, bolj zapuščeno kakor divjino proti Dibli, v vseh njihovih prebivališčih, in spoznali bodo, da jaz sem Gospod.‹«',
    },
    7: {
        1: 'Poleg tega je prišla k meni Gospodova beseda, rekoč:',
        2: '§ »Tudi ti, človeški sin, tako govori Gospod Bog Izraelovi deželi: ›Konec, konec je prišel nad štiri vogale dežele.',
        3: 'Sedaj je nadte prišel konec in nadte bom poslal svojo jezo in sodil te bom glede na tvoje poti in na tebi bom poplačal vse tvoje ogabnosti.',
        4: 'Moje oko ti ne bo prizaneslo niti ne bom imel usmiljenja, temveč bom na tebi poplačal tvoje poti in tvoje ogabnosti bodo v tvoji sredi in spoznali boste, da jaz sem Gospod.‹',
        5: '§ Tako govori Gospod Bog: ›Zlo, samo zlo, glej, je prišlo.',
        6: '§ Konec je prišel, prišel je konec. Ta opreza za teboj, glej, ta je prišel.',
        7: '§ Jutro je prišlo k tebi, oh ti, ki prebivaš v deželi. Čas je prišel, dan stiske je blizu, ne pa ponovno oglašanje gora.',
        8: 'Nate bom sedaj v kratkem izlil svojo razjarjenost in dovršil svojo jezo nad teboj. Sodil te bom glede na tvoje poti in poplačal ti bom za vse tvoje ogabnosti.',
        9: '§ Moje oko ne bo prizaneslo niti ne bom imel usmiljenja. Poplačal ti bom glede na tvoje poti in tvoje ogabnosti, ki so sredi tebe in spoznali boste, da jaz sem Gospod, ki udarja.',
        10: '§ Glej dan, glej, prišel je. Jutro je prešlo, palica je zacvetela, ponos je vzbrstel.',
        11: 'Nasilje se vzdiguje v palico zlobnosti. Nihče izmed njih ne bo preostal, niti od njihove množice, niti od ničesar, kar je njihovega; niti za njimi ne bo tarnanja.',
        12: 'Čas je prišel, dan se približuje. Naj se kupec ne veseli niti naj prodajalec ne žaluje, kajti bes je nad vso njegovo množico.',
        13: '§ Kajti prodajalec se ne bo vrnil k temu, kar je prodano, čeprav bi bili še živi, kajti videnje je glede vse njegove množice, ki se ne bo vrnila; niti se ne bo kdorkoli okrepil v krivičnosti svojega življenja.',
        14: 'Zatrobili so na trobento, celo da bi se vsi pripravili, toda nihče ne gre v bitko, kajti moj bes je nad vso njihovo množico.',
        15: 'Meč je zunaj, znotraj pa kužna bolezen in lakota. Kdor je na polju, bo umrl z mečem, kdor pa je v mestu, ga bosta požrla lakota in kužna bolezen.',
        16: 'Toda tisti izmed njih, ki pobegnejo, bodo pobegnili in bodo na gorah kakor dolinske golobice, vsi izmed njih žalujoči, vsakdo zaradi svoje krivičnosti.',
        17: 'Vse roke bodo slabotne in vsa kolena bodo šibka kakor voda.',
        18: 'Prav tako se bodo opasali z vrečevino in groza jih bo pokrila. Sramota bo na vseh obrazih in plešavost na vseh njihovih glavah.',
        19: '§ Svoje srebro bodo vrgli na ulice in njihovo zlato bo odstranjeno. Njihovo srebro in njihovo zlato jih ne bo moglo rešiti na dan Gospodovega besa. Ne bodo zadovoljili svojih duš niti napolnili svojih notranjosti, ker je le-to kamen spotike njihovi krivičnosti.',
        20: '§ Kar se tiče lepote njegovega ornamenta, ga je postavil v veličanstvu, toda v njem so oni naredili podobe svojih ogabnosti in svojih ostudnih stvari, zatorej sem ga postavil daleč od njih.',
        21: 'In dal sem ga v roke tujcem za plen in zlobnežem zemlje za ukradeno blago in oni ga bodo oskrunili.',
        22: 'Tudi svoj obraz bom obrnil proč od njih in oskrunili bodo moj skrivni kraj, kajti roparji bodo vstopili vanj in ga omadeževali.',
        23: '§ Naredi verigo, kajti dežela je polna krvoločnih zločinov in mesto je polno nasilja.',
        24: 'Zatorej bom privedel najslabše izmed poganov in njihove hiše bodo vzeli v last. Prav tako bom storil, da bo pomp močnega prenehal in njihovi sveti kraji bodo omadeževani.',
        25: 'Prihaja uničenje in iskali bodo miru, pa ga ne bo.',
        26: '§ Vragolija bo prišla na vragolijo in govorica na govorico, potem bodo iskali videnje od preroka, toda postava bo izginila od duhovnika in nasvet od starcev.',
        27: 'Kralj bo žaloval in princ bo oblečen z opustošenjem in roke ljudstva dežele bodo trepetale. Jaz jim bom storil po njihovi poti in glede na njihove zasluge jih bom sodil, in spoznali bodo, da jaz sem Gospod.‹«',
    },
    8: {
        1: 'Pripetilo se je v šestem letu, v šestem mesecu, na peti dan meseca, ko sem sedèl v svoji hiši in so starešine Juda sedeli pred menoj, da je tam name padla roka Gospoda Boga.',
        2: '§ Potem sem pogledal in glej, podoba kakor videz ognja. Od videza njenih ledij, celó navzdol, ogenj; in od njenih ledij, celó navzgor, kakor videz sijaja, kot barva jantarja.',
        3: 'Iztegnil je obliko roke in me prijel za koder moje glave, in duh me je dvignil med zemljo in nebo in me v Božjih videnjih privedel k Jeruzalemu, k durim notranjih velikih vrat, ki gledajo proti severu, kjer je bil sedež podobe ljubosumnosti, ki izziva k ljubosumnosti.',
        4: 'Glej, tam je bila slava Izraelovega Boga, glede na videnje, ki sem ga videl na ravnini.',
        5: 'Potem mi je rekel: »Človeški sin, povzdigni sedaj svoje oči proti severu.« Tako sem povzdignil svoje oči proti severu in glej proti severu, pri velikih vratih oltarja, ta podoba ljubosumnosti na vhodu.',
        6: '§ Nadalje mi je rekel: »Človeški sin, ali vidiš, kaj počno? Celó velike ogabnosti, ki jih Izraelova hiša grešno počenja tukaj, da bi jaz moral oditi daleč proč od svojega svetišča? Toda ponovno se obrni in videl boš večje ogabnosti.«',
        7: 'Privedel me je k dvornim vratom in ko sem pogledal, glej, luknja v zidu.',
        8: 'Potem mi je rekel: »Človeški sin, koplji sedaj v steno.« In ko sem kopál v steno, sem zagledal vrata.',
        9: 'In rekel mi je: »Vstopi in poglej zlobne ogabnosti, ki jih tukaj počno.«',
        10: 'Tako sem vstopil in videl; in glej, vsakršne oblike plazečih stvari in gnusnih zveri in vseh malikov Izraelove hiše, upodobljenih po steni naokoli.',
        11: 'In tam je pred njimi stalo sedemdeset mož, izmed starcev Izraelove hiše in v njihovi sredi je stal Jaazanjá, sin Šafána. Z vsakim moškim je bila v njegovi roki njegova kadilnica; in gost oblak kadila se je dvigal.',
        12: 'Potem mi je rekel: »Človeški sin, ali si videl kaj starci Izraelove hiše počno v temi, vsak mož v sobah svojih podob? Kajti pravijo: › Gospod nas ne vidi; Gospod je zapustil zemljo.‹«',
        13: '§ Prav tako mi je rekel: »Ponovno se obrni in videl boš večje ogabnosti, ki jih počno.«',
        14: 'Potem me je privedel k durim velikih vrat Gospodove hiše, ki so bila proti severu; in glej, tam so sedele ženske, jokajoče za Tamúzom.',
        15: '§ Potem mi je rekel: »Ali si videl to, oh človeški sin? Ponovno se obrni in videl boš večje ogabnosti, kot so te.«',
        16: 'In privedel me je na notranji dvor Gospodove hiše in glej, pri vratih Gospodovega templja, med preddverjem in oltarjem, je bilo okoli petindvajset mož, s svojimi hrbti proti Gospodovemu templju in svojimi obrazi proti vzhodu; in oboževali so sonce proti vzhodu.',
        17: '§ Potem mi je rekel: »Si videl to, oh človeški sin? Ali je lahka stvar za Judovo hišo, da zagrešijo ogabnosti, ki jih tukaj zagrešujejo? Kajti deželo so napolnili z nasiljem in vrnili so se, da me izzivajo k jezi. In glej, vejico dajejo pod svoj nos.',
        18: 'Zatorej bom tudi jaz postopal v razjarjenosti. Moje oko ne bo prizanašalo niti ne bom imel usmiljenja, in četudi jokajo z močnim glasom v moja ušesa, jih vendar ne bom slišal.«',
    },
    9: {
        1: 'Zaklical je tudi z močnim glasom v moja ušesa, rekoč: »Povzročite tistim, ki imajo zadolžitev nad mestom, da se približajo, celo vsak človek s svojim uničevalnim orožjem v svoji roki.«',
        2: 'In glej, šest mož je prišlo po poti višjih velikih vrat, ki ležijo proti severu in vsak mož s pokončevalnim orožjem v svoji roki; in en mož izmed njih je bil oblečen z lanenim platnom, s pisarskim rogom, s črnilom ob njegovi strani in vstopili so in obstali poleg bronastega oltarja.',
        3: 'In slava Izraelovega Boga je odšla gor od keruba, nad katerim je bila, k hišnemu pragu. In zaklical je k možu, oblečenim z lanenim platnom, ki je imel pisarski rog s črnilom ob njegovi strani;',
        4: '§ in Gospod mu je rekel: »Pojdi skozi sredino mesta, skozi sredo [prestolnice] Jeruzalem in postavi znamenje na čela ljudi, ki vzdihujejo in ki jokajo zaradi vseh ogabnosti, ki se počno v njeni sredi.«',
        5: 'Drugim pa je rekel v mojem slišanju: »Pojdite za njim skozi mesto in udarite. Naj vaše oko ne prizanaša niti ne imejte usmiljenja.',
        6: '§ Popolnoma pobijte stare in mlade, tako device kakor majhne otroke in ženske, toda ne pridite blizu nobenemu človeku, na katerem je znamenje; in začnite pri mojem svetišču.« Potem so začeli pri starodavnih možeh, ki so bili pred hišo.',
        7: 'Rekel jim je: »Omadežujte hišo in napolnite dvore z umorjenimi. Pojdite naprej.« In odšli so naprej in morili v mestu.',
        8: 'In pripetilo se je, medtem ko so jih pobijali in sem ostal sam, da sem padel na svoj obraz in jokal ter rekel: »Ah, Gospod Bog! Ali boš ves Izraelov preostanek uničil v izlivanju svoje razjarjenosti nad [prestolnico] Jeruzalem?«',
        9: 'Potem mi je rekel: »Krivičnost Izraelove in Judove hiše je silno velika in dežela je polna krvi in mesto polno perverznosti, kajti pravijo: › Gospod je zapustil zemljo in Gospod ne vidi.‹',
        10: 'In tudi kar se mene tiče, moje oko ne bo prizaneslo niti ne bom imel usmiljenja, temveč bom njihovo pot poplačal na njihovi glavi.«',
        11: 'In glej, mož, oblečen z lanenim platnom, ki je imel ob svoji strani pisarski rog s črnilom, je poročal zadevo, rekoč: »Storil sem, kakor si mi zapovedal.«',
    },
    10: {
        1: 'Potem sem pogledal in glej, na nebesnem svodu, ki je bil nad glavo kerubov, tam se je nad njimi prikazal kakor kamen safir, kakor videz podobnosti prestola.',
        2: 'In spregovoril je človeku, oblečenemu z lanenim platnom in rekel: »Vstopi med kolesa, celó pod keruba in svojo roko napolni z ognjenim ogljem izmed kerubov in jih raztresi nad mestom.« In vstopil je pred mojim pogledom.',
        3: 'Torej kerubi so stali na desni strani hiše, ko je mož vstopil; in oblak je napolnil notranji dvor.',
        4: '§ Potem se je Gospodova slava vzdignila od keruba in stala nad hišnim pragom hiše; in hiša je bila napolnjena z oblakom in dvor je bil poln sijaja Gospodove slave.',
        5: 'In zvok kerubovih peruti je bilo slišati celó k zunanjemu dvoru, kakor glas Vsemogočnega Boga, ko spregovori.',
        6: 'In pripetilo se je, da ko je zapovedal možu, oblečenemu z lanenim platnom, rekoč: »Vzemi ogenj izmed koles, izmed kerubov;« potem je ta vstopil in stal poleg koles.',
        7: 'In en kerub je svojo roko iztegnil izmed kerubov k ognju, ki je bil med kerubi in vzel od njega in to položil v roke tistega, ki je bil oblečen z lanenim platnom; ki je to vzel in odšel ven.',
        8: 'In pri kerubih se je prikazala oblika človeške roke pod njihovimi perutmi.',
        9: '§ In ko sem pogledal, glej, štiri kolesa ob kerubih, eno kolo pri enem kerubu in drugo kolo pri drugem kerubu in videz koles je bil kakor barva kamna berila.',
        10: 'In glede njihovih videzov, so ti štirje imeli eno podobnost, kakor če bi bilo kolo v sredi kolesa.',
        11: '§ Ko so odšla, so odšla na svoje štiri strani; ko so odšla, se niso obračala, toda sledila so h kraju, kamor je pogledala glava; ko so odšla, se niso obračala.',
        12: 'In njihovo celotno telo in njihovi hrbti in njihove roke in njihove peruti in kolesa so bili naokoli polni oči, celó kolesa, ki so jih ta štiri imela.',
        13: 'Glede koles, jim je bilo klicano v mojem slišanju: »Oh kolo.«',
        14: '§ In vsako je imelo štiri obraze: prvi obraz je bil obraz keruba, drugi obraz je bil obraz človeka, tretji obraz leva in četrti obraz orla.',
        15: 'In kerubi so bili dvignjeni. To je živo ustvarjeno bitje, ki sem ga videl pri reki Kebár.',
        16: 'In ko so hodili kerubi, so ob njih šla kolesa, in ko so kerubi dvignili svoje peruti, da se povzpnejo z zemlje, se tudi ista kolesa niso odvrnila od njihove bližine.',
        17: 'Ko so se ustavili, so se ta ustavila; in ko so se dvignili, so se tudi ta sama dvignila, kajti duh živega ustvarjenega bitja je bil v njih.',
        18: 'Potem je Gospodova slava odšla od hišnega praga in obstala nad kerubi.',
        19: 'In kerubi so dvignili svoje peruti in se v mojem pogledu vzpeli z zemlje; ko so odšli, so bila tudi kolesa poleg njih in vsako je stalo pri vratih vzhodnih velikih vrat Gospodove hiše in slava Izraelovega Boga je bila zgoraj nad njimi.',
        20: 'To je živo ustvarjeno bitje, ki sem ga videl pod Izraelovim Bogom, poleg reke Kebár; in vedel sem, da so bili to kerubi.',
        21: 'Vsak je imel po štiri obraze in vsak štiri peruti; in podobnost človeških rok je bila pod njihovimi perutmi.',
        22: 'In podobnost njihovih obrazov so bili isti obrazi, ki sem jih videl poleg reke Kebár, njihovi videzi in oni sami. Vsak je hodil naravnost naprej.',
    },
    11: {
        1: 'Poleg tega me je duh dvignil navzgor in me privedel k vzhodnim velikim vratom Gospodove hiše, ki so gledala proti vzhodu. Glej, pri vratih velikih vrat sem zagledal petindvajset mož; med njimi sem videl Jaazanjá, Azúrjevega sina in Pelatjája, Benajájevega sina, princa ljudstva.',
        2: 'Potem mi je rekel: »Človeški sin, to so možje, ki snujejo vragolijo in dajejo zloben nasvet v tem mestu,',
        3: 'ki pravijo: › To ni blizu; dajmo, gradimo hiše; to mesto je kotel in mi smo meso.‹',
        4: 'Zato prerokuj zoper njih, prerokuj, oh človeški sin.«',
        5: 'In Gospodov Duh je padel name ter mi rekel: »Govori: ›Tako govori Gospod: ›Tako ste rekli, oh Izraelova hiša; kajti poznam besede, ki pridejo v vaš um, vsako izmed njih.',
        6: 'Pomnožili ste svoje umorjene v tem mestu in njegove ulice ste napolnili z umorjenimi.‹',
        7: 'Zato tako govori Gospod Bog: ›Vaši umorjeni, ki ste jih položili v njegovi sredi, oni so meso in to mesto je kotel, toda jaz vas bom privedel iz njegove srede.',
        8: 'Bali ste se meča; pa bom nad vas privedel meč,‹ govori Gospod Bog.',
        9: '›Privedel vas bom iz njegove srede in vas izročil v roke tujcem in med vami bom izvršil sodbe.',
        10: 'Pod mečem boste padli; sodil vas bom na Izraelovi meji, in spoznali boste, da jaz sem Gospod.',
        11: 'To mesto ne bo vaš kotel niti ne boste meso v njegovi sredi; temveč vas bom jaz sodil na Izraelovi meji',
        12: 'in spoznali boste, da jaz sem Gospod, kajti niste živeli po mojih zakonih niti izvrševali mojih sodb, temveč ste počeli po navadah poganov, ki so naokoli vas.‹«',
        13: 'In pripetilo se je, ko sem prerokoval, da je Benajájev sin Pelatjája umrl. Potem sem padel na svoj obraz in jokal z močnim glasom ter rekel: »Ah, Gospod Bog! Ali hočeš narediti popoln konec Izraelovemu preostanku?«',
        14: 'Ponovno je prišla k meni Gospodova beseda, rekoč:',
        15: '»Človeški sin, tvoji bratje, celó tvoji bratje, možje tvojega sorodstva in vsa celotna Izraelova hiša, ali so oni tisti, ki so jim prebivalci [prestolnice] Jeruzalem rekli: ›Spravite se daleč od Gospoda. Nam je dana ta dežela v posest.‹',
        16: 'Zato reci: ›Tako govori Gospod Bog: ›Čeprav sem jih vrgel daleč proč med pogane in čeprav sem jih razkropil med dežele, vendar jim bom kakor majhno svetišče v deželah, v katere bodo prišli.‹',
        17: 'Zato reci: ›Tako govori Gospod Bog: ›Jaz vas bom celo zbral izmed ljudstev in vas zbral izmed dežel, kamor ste bili razkropljeni in jaz vam bom dal Izraelovo deželo.',
        18: 'In prišli bodo tja in od tam bodo odvzeli vse njene ostudne stvari in vse njene ogabnosti.',
        19: 'Dal jim bom eno srce in znotraj vas bom položil novega duha; in odvzel bom kamnito srce iz njihovega mesa in jim dal meseno srce,',
        20: 'da se bodo lahko ravnali po mojih zakonih in se držali mojih odredb in jih izvajali in bodo moje ljudstvo in jaz bom njihov Bog.',
        21: 'Toda glede tistih, čigar srce hodi za srcem njihovih ostudnih stvari in njihovih ogabnosti, bom njihovo pot poplačal na njihovih lastnih glavah,‹ govori Gospod Bog.«',
        22: 'Potem so kerubi dvignili svoje peruti in kolesa poleg njih; in slava Izraelovega Boga je bila zgoraj nad njimi.',
        23: 'In Gospodova slava se je vzdignila iz srede mesta in se ustavila nad goro, ki je na vzhodni strani mesta.',
        24: 'Potem me je duh vzel gor in me v videnju, po Božjem Duhu, privedel v Kaldejo, k tem iz ujetništva. Tako se je videnje, ki sem ga videl, dvignilo od mene.',
        25: 'Potem sem tistim iz ujetništva, spregovoril vse stvari, ki mi jih je Gospod pokazal.',
    },
    12: {
        1: 'Prav tako je prišla k meni Gospodova beseda, rekoč:',
        2: '»Človeški sin, prebivaš v sredi uporne hiše, ki imajo oči, da vidijo, pa ne vidijo; imajo ušesa, da slišijo, pa ne slišijo, kajti uporna hiša so.',
        3: 'Zato, človeški sin, si pripravi stvari za selitev in se preseli podnevi, v njihovem pogledu; in preselil se boš iz svojega kraja na drug kraj, v njihovem pogledu. Morda bodo to preudarili, kajti uporna hiša so.',
        4: 'Potem boš podnevi prinesel svoje stvari, v njihovem pogledu, kakor stvari za selitev, in zvečer boš šel naprej, v njihovem pogledu, kakor tisti, ki gredo naprej v ujetništvo.',
        5: 'Prekoplji se skozi steno, v njihovem pogledu in tam odnesi ven.',
        6: 'V njihovem pogledu boš to nosil na svojih ramenih in to boš prenašal naprej v mraku. Pokril si boš svoj obraz, da ne vidiš tal, kajti postavil sem te za znamenje Izraelovi hiši.«',
        7: 'In storil sem tako, kakor mi je bilo zapovedano. Podnevi sem prinesel svoje stvari, kakor stvari za v ujetništvo, zvečer pa sem se s svojo roko prekopál skozi zid; to sem prinesel naprej v mraku in to sem nosil na svojem ramenu, v njihovem pogledu.',
        8: 'In zjutraj mi je prišla beseda od Gospoda, rekoč:',
        9: '»Človeški sin, ali ti ni Izraelova hiša, uporna hiša, rekla: ›Kaj delaš?‹',
        10: '§ Povej jim: ›Tako govori Gospod Bog: ›To breme zadeva princa v [prestolnici] Jeruzalem in vso Izraelovo hišo, ki so med njimi.‹',
        11: 'Reci: ›Jaz sem vaše znamenje. Kakor sem jaz storil, tako bo storjeno njim. Odselili se bodo in odšli v ujetništvo.',
        12: '§ In princ, ki je med njimi, bo v mraku nosil na svojem ramenu in bo šel naprej. Prekopali bodo skozi zid, da bi tamkaj nosili ven skozi steno. Pokril si bo svoj obraz, da s svojimi očmi ne bo videl tal.',
        13: 'Tudi svojo mrežo bom razširil nad njim in zajet bo v mojo zanko, in privedel ga bom v Babilon, v deželo Kaldejcev; vendar je ne bo videl, čeprav bo tam umrl.',
        14: 'In vse, ki so okoli njega, da mu pomagajo, bom razkropil proti vsakemu vetru in vse njegove čete; in za njimi bom izvlekel meč.',
        15: 'In spoznali bodo, da jaz sem Gospod, ko jih bom razkropil med narode in jih razpršil v dežele.',
        16: 'Toda izločil bom peščico ljudi izmed njih pred mečem, pred lakoto in kužno boleznijo; da bodo med pogani, kamor pridejo, lahko razglasili vse svoje ogabnosti; in spoznali bodo, da jaz sem Gospod.‹«',
        17: 'Poleg tega je prišla k meni Gospodova beseda, rekoč:',
        18: '»Človeški sin, svoj kruh jej z drgetanjem in svojo vodo pij s trepetanjem in previdnostjo;',
        19: 'in povej ljudstvu dežele: ›Tako govori Gospod Bog o prebivalcih [prestolnice] Jeruzalem in o Izraelovi deželi: ›Svoj kruh bodo jedli s previdnostjo in svojo vodo pili z osuplostjo, da bo njihova dežela lahko zapuščena od vseh, ki so v njej, zaradi nasilja vseh tistih, ki prebivajo v njej.',
        20: 'In mesta, ki so naseljena, bodo opustošena in dežela bo zapuščena; in spoznali boste, da jaz sem Gospod.‹«',
        21: 'In k meni je prišla Gospodova beseda, rekoč:',
        22: '»Človeški sin, kakšen je ta pregovor, ki ga imate v Izraelovi deželi, rekoč: ›Dnevi so podaljšani in vsako videnje odpove?‹',
        23: '§ Povej jim torej: ›Tako govori Gospod Bog: ›Temu pregovoru bom storil, da preneha in ne bodo ga več uporabljali kot pregovor v Izraelu; temveč jim reci: ›Blizu so dnevi in učinek vsakega videnja.',
        24: 'Kajti nobenih praznih videnj ne bo več niti laskajočih vedeževanj znotraj Izraelove hiše.',
        25: 'Kajti jaz sem Gospod. Jaz bom govoril in beseda, ki jo bom govoril, se bo izpolnila; ta se ne bo več odlagala, kajti v vaših dneh, oh uporna hiša, bom rekel besedo in jo izpolnil, govori Gospod Bog.‹«',
        26: 'Ponovno je prišla k meni Gospodova beseda, rekoč:',
        27: '»Človeški sin, glej, tisti iz Izraelove hiše pravijo: ›Videnje, ki ga on vidi, je za mnoge dni, ki pridejo in prerokuje o časih, ki so še daleč.‹',
        28: 'Zato jim reci: ›Tako govori Gospod Bog: ›Nobena izmed mojih besed se ne bo več odlagala, temveč se bo beseda, ki sem jo govoril, izpolnila,‹ govori Gospod Bog.«',
    },
    13: {
        1: 'In k meni je prišla Gospodova beseda, rekoč:',
        2: '»Človeški sin, prerokuj zoper Izraelove preroke, ki prerokujejo in reci tem, ki prerokujejo iz svojih lastnih src: ›Poslušajte Gospodovo besedo:',
        3: '›Tako govori Gospod Bog: ›Gorje nespametnim prerokom, ki sledijo svojemu lastnemu duhu in ničesar niso videli!‹',
        4: 'Oh Izrael, tvoji preroki so podobni lisicam v puščavah.',
        5: 'Vi niste odšli gor v razpoke niti niste postavili ograje za Izraelovo hišo, da obstane v bitki na Gospodov dan.',
        6: 'Videli so ničnost in lažniva vedeževanja, rekoč: › Gospod govori,‹ pa jih Gospod ni poslal. In druge so pripravili, da upajo, da bi potrdili besedo.',
        7: 'Mar niste videli praznega videnja in ali niste govorili lažnivega vedeževanja, medtem ko govorite: › To govori Gospod;‹ čeprav nisem govoril?‹',
        8: 'Zato tako govori Gospod Bog: ›Ker ste govorili prazne reči in videli laži, zato, glejte, jaz sem zoper vas,‹ govori Gospod Bog.',
        9: '§ ›In moja roka bo na prerokih, ki vidijo prazne reči in ki vedežujejo laži. Ne bodo v zboru mojega ljudstva niti ne bodo zapisani v zapisu Izraelove hiše niti ne bodo vstopili v Izraelovo deželo, in spoznali boste, da jaz sem Gospod Bog.',
        10: 'Zato, celo zato so zapeljali moje ljudstvo, rekoč: ›Mir;‹ pa tam ni bilo miru; in nekdo je zgradil zid in glej, drugi so ga ometali z neutrjeno malto.',
        11: '§ Recite tistim, ki ga ometujejo z neutrjeno malto, da bo ta padel. Preplavljajoč naliv bo; oh, velika zrna toče bodo padala; in viharni veter ga bo razklal.',
        12: 'Glejte, ko pade zid, ali vam ne bo rečeno: ›Kje je zmazek, s katerim ste ga namazali?‹',
        13: '§ Zato tako govori Gospod Bog: ›V svoji razjarjenosti ga bom celo razklal z viharnim vetrom; in tam bo preplavljajoč naliv v moji jezi in velika zrna toče v moji razjarjenosti, da ga použijejo.',
        14: 'Tako bom porušil zid, ki ste ga ometali z neutrjeno malto in ga porušim do tal, tako da bodo odkriti njegovi temelji in ta bo padel, vi pa boste použiti v njegovi sredi in spoznali boste, da jaz sem Gospod.',
        15: 'Tako bom dovršil svoj bes nad zidom in nad temi, ki so ga ometali z neutrjeno malto in vam bom rekel: ›Zidu ni več niti tistih, ki so ga ometali;',
        16: 'namreč Izraelovih prerokov, ki prerokujejo glede [prestolnice] Jeruzalem in ki zanjo vidijo videnja miru, pa tam ni miru,‹ govori Gospod Bog.',
        17: '›Prav tako ti, človeški sin, naravnaj svoj obraz zoper hčere svojega ljudstva, ki prerokujejo iz svojih lastnih src; in prerokuj zoper njih',
        18: '§ ter reci: ›Tako govori Gospod Bog: ›Gorje ženskam, ki šivajo blazine k vsem odprtinam za rokave in izdelujejo naglavne rute na glavi vsake postave, da bi lovile duše! Hočete loviti duše mojega ljudstva in ali boste duše, ki prihajajo k vam, rešile žive?',
        19: '§ In ali me hočete oskruniti med mojim ljudstvom za prgišča ječmena in za koščke kruha, da ubijate duše, ki naj ne bi umrle in da rešujete duše žive, ki naj ne bi živele, z vašim laganjem mojemu ljudstvu, ki posluša vaše laži?‹',
        20: 'Zato tako govori Gospod Bog: ›Glejte, jaz sem zoper vaše blazine, s katerimi ste tam lovile duše, da jih pripravite leteti in iztrgal jih bom iz vaših rok in jaz bom pustil dušam oditi, celó dušam, ki jih vi lovite, da jih pripravite leteti.',
        21: 'Tudi vse naglavne rute bom raztrgal in osvobodil svoje ljudstvo iz vaše roke in nič več ne bodo v vaši roki, da bi jih lovile; in spoznale boste, da jaz sem Gospod.',
        22: '§ Ker ste z lažmi užalostile srce pravičnega, ki ga nisem užalostil; in okrepile roke zlobnega, da se ta ne bi vrnil iz svoje zlobne poti, [s tem] da ste mu obljubljale življenje,',
        23: '§ zato ne boste več videle praznih reči niti božanskih vedeževanj, kajti jaz bom osvobodil svoje ljudstvo iz vaše roke, in spoznale boste, da jaz sem Gospod.«',
    },
    14: {
        1: 'Potem so prišli k meni nekateri izmed Izraelovih starešin in se usedli pred menoj.',
        2: 'In k meni je prišla Gospodova beseda, rekoč:',
        3: '§ »Človeški sin, ti možje so si v srcih postavljali malike in so si pred svoj obraz postavljali kamen spotike svoje krivičnosti; ali naj bi me oni potem sploh spraševali?«',
        4: 'Zato jim govori in jim povej: »Tako govori Gospod Bog: ›Vsak mož iz Izraelove hiše, ki si v svojem srcu postavlja malike in pred svoj obraz polaga kamen spotike svoje krivičnosti in prihaja k preroku; jaz, Gospod, bom odgovoril tistemu, ki prihaja, glede na množico njegovih malikov,',
        5: 'da bi Izraelovo hišo lahko ujel v njihovem lastnem srcu, ker so se zaradi svojih malikov vsi odtujili od mene.‹',
        6: 'Zato reci Izraelovi hiši: ›Tako govori Gospod Bog: ›Pokesajte se in odvrnite se od svojih malikov; odvrnite svoje obraze od vseh svojih ogabnosti.‹',
        7: 'Kajti vsakomur izmed Izraelove hiše, ali izmed tujca, ki začasno biva v Izraelu, ki se ločuje od mene in si v svojem srcu postavlja svoje malike in polaga kamen spotike svoje krivičnosti pred svoj obraz in prihaja k preroku, da bi od njega povprašal glede mene, mu bom jaz, Gospod, sam odgovoril.',
        8: 'Svoj obraz bom naravnal zoper tega moža in naredil ga bom za znamenje in pregovor in odrezal ga bom iz srede svojega ljudstva; in spoznali boste, da jaz sem Gospod.',
        9: 'Če pa je prerok zaveden, ko je govoril besedo, sem jaz, Gospod, zavedel tega preroka in jaz bom iztegnil svojo roko nanj in ga uničim iz srede svojega ljudstva Izraela.',
        10: 'Nosila bosta kazen svoje krivičnosti. Kazen preroka bo celo kakor kazen tistega, ki poizveduje k njemu;',
        11: 'da Izraelova hiša ne bo več zašla od mene niti ne bo več oskrunjena z vsemi svojimi prestopki; temveč da bodo lahko moje ljudstvo in bom jaz lahko njihov Bog, govori Gospod Bog.‹«',
        12: 'Gospodova beseda je prišla ponovno k meni, rekoč:',
        13: '»Človeški sin, kadar dežela greši zoper mene z mučnimi prekršitvami, takrat bom nadnjo iztegnil svojo roko in zlomil bom njeno oporo kruha in nadnjo bom poslal lakoto in iz nje bom iztrebil človeka in žival.',
        14: '§ Čeprav bi bili v njej ti trije možje: Noe, Daniel in Job, bi s svojo pravičnostjo rešili zgolj svoje lastne duše,‹ govori Gospod Bog.',
        15: '§ ›Če povzročim ogabnim živalim, da gredo skozi deželo, jo oplenijo tako, da je ta zapuščena, da zaradi živali noben človek ne bo mogel iti skoznjo;',
        16: 'čeprav bi bili ti trije možje v njej, kakor jaz živim,‹ govori Gospod Bog, ›ne bodo osvobodili niti sinov niti hčera; samo oni sami bodo osvobojeni, toda dežela bo zapuščena.',
        17: 'Ali če privedem meč nad to deželo in rečem: ›Meč, pojdi skozi to deželo;‹ tako, da iz nje iztrebim ljudi in živali;',
        18: '§ čeprav bi bili ti trije možje v njej, kakor jaz živim,‹ govori Gospod Bog, ›ne bi osvobodili niti sinov niti hčera; samo oni sami bi bili osvobojeni.',
        19: 'Ali če pošljem v to deželo kužno bolezen in če nanjo v krvi izlijem svojo razjarjenost, da iztrebim iz nje človeka in žival;',
        20: '§ čeprav bi bili v njej Noe, Daniel in Job, kakor jaz živim,‹ govori Gospod Bog, ›ne bi osvobodili niti sinov niti hčera, temveč bodo po svoji pravičnosti osvobodili zgolj svoje lastne duše.‹',
        21: 'Kajti tako govori Gospod Bog: ›Koliko bolj, ko pošljem svoje štiri boleče sodbe nad Jeruzalem: meč, lakoto in ogabno zver in kužno bolezen, da iztrebim iz nje ljudi in živali?',
        22: '§ In vendar, glejte, bo tam ostal ostanek, ki bo izpeljan, tako sinov kakor hčera. Glejte, prišli bodo k vam in videli boste njihovo pot in njihova dejanja in potolaženi boste glede zla, ki sem ga privedel nad Jeruzalem, celó glede vsega, kar sem privedel nadenj.',
        23: 'In potolažili vas bodo, ko boste videli njihove poti in njihova dejanja, in spoznali boste, da nisem brez vzroka storil vsega, kar sem storil v njem,‹ govori Gospod Bog.‹«',
    },
    15: {
        1: 'In k meni je prišla Gospodova beseda, rekoč:',
        2: '»Človeški sin: ›Kaj je trta boljša kakor katerokoli drevo ali kakor mladika, ki je med gozdnimi drevesi?',
        3: 'Mar bo vzet njen les, da bi opravljal katerokoli delo? Ali bodo možje od nje vzeli klin, da bi nanj obesili katerokoli posodo?',
        4: 'Glej, vržena je v ogenj za gorivo. Ogenj pogoltne oba njena konca in njena sreda je ožgana. Ali je primerna za kakršnokoli delo?',
        5: 'Glej, ko je bila cela, ni bila primerna za nobeno delo. Kako veliko manj bo vendar ta primerna za kakršnokoli delo, ko jo je požrl ogenj in je ožgana?‹',
        6: 'Zato tako govori Gospod Bog: ›Kakor je trta med gozdnimi drevesi, ki sem jo izročil ognju za gorivo, tako bom izročil prebivalce Jeruzalema.',
        7: 'Svoj obraz bom naravnal zoper njih. Šli bodo iz enega ognja, pa jih bo pogoltnil drug ogenj. In spoznali boste, da jaz sem Gospod, ko svoj obraz naravnam zoper njih.',
        8: 'Deželo bom naredil zapuščeno, ker so zagrešili prekršek,‹ govori Gospod Bog.«',
    },
    16: {
        1: 'Ponovno je prišla k meni Gospodova beseda, rekoč:',
        2: '»Človeški sin, povzroči [prestolnici] Jeruzalem, da spozna svoje ogabnosti',
        3: 'in reci: ›Tako govori Gospod Bog [prestolnici] Jeruzalem: ›Tvoj rod in tvoje rojstvo je iz kánaanske dežele; tvoj oče je bil Amoréjec, tvoja mati pa Hetejka.',
        4: 'Glede tvojega rojstva, na dan, ko si bila rojena, tvoj popek ni bil odrezan niti nisi bila umita v vodi, da ti omehča [kožo]; sploh nisi bila odrgnjena s soljo niti povita.',
        5: 'Niti se te nobeno oko ni usmililo, da bi ti storilo karkoli od tega, da bi imelo do tebe sočutje; temveč si bila vržena na odprto polje, do gnusenja glede tvoje osebe, na dan, ko si bila rojena.',
        6: 'In ko sem šel mimo tebe in te videl oskrunjeno v svoji krvi, sem ti rekel, ko si bila v svoji krvi: ›Živi;‹ da, rekel sem ti, ko si bila v svoji krvi: ›Živi.‹',
        7: '§ Dal sem ti, da si se namnožila kakor brstje polja in povečala si se in postala velika in prišla k odličnim ornamentom. Tvoje prsi so se oblikovale in tvoji lasje so zrasli, medtem ko si bila naga in gola.',
        8: 'Torej, ko sem šel mimo tebe in pogledal nate, glej, tvoj čas je bil čas ljubezni. Razširil sem krajec svojega oblačila nad teboj in pokril tvojo nagoto. Da, prisegel sem ti in vstopil v zavezo s teboj,‹ govori Gospod Bog ›in postala si moja.',
        9: 'Potem sem te umil z vodo; da, temeljito sem izmil tvojo kri iz tebe in te mazilil z oljem.',
        10: 'Oblekel sem te tudi z izvezenim delom in ti obul jazbečevo kožo in te naokoli opasal s tankim lanenim platnom in te ogrnil s svilo.',
        11: 'Odel sem te tudi z ornamenti in na tvoje roke sem nataknil zapestnice in verižico na tvoj vrat.',
        12: '§ Položil sem dragulj na tvoje čelo in uhane v tvoja ušesa in krasno krono na tvojo glavo.',
        13: 'Tako si bila odeta z zlatom in srebrom, in tvoje oblačilo je bilo iz tankega lanenega platna, svile in izvezenega dela. Jedla si fino moko, med in olje. Bila si silno krasna in uspevala si v kraljestvu.',
        14: 'Tvoj ugled je zaradi tvoje lepote odšel naprej med pogane, kajti ta je bila popolna zaradi moje ljubkosti, ki sem jo položil nadte,‹ govori Gospod Bog.',
        15: '›Toda zaupala si v svojo lastno lepoto in igrala pocestnico zaradi svojega ugleda in svoje prešuštvovanje si izlila na vsakega, ki je šel mimo; njegovo je bilo.',
        16: 'Vzela si od svojih oblek in svoje visoke kraje si odela s številnimi barvami in na njih igrala pocestnico. Podobne stvari ne bodo prišle niti to ne bo tako.',
        17: 'Vzela si tudi svoje lepe dragocenosti od mojega zlata in od mojega srebra, ki sem ti jih dal in si si naredila moške podobe in z njimi zagrešila vlačugarstvo',
        18: 'in jemala si svoje izvezene obleke in jih pokrivala in prednje si postavljala moje olje in moje kadilo.',
        19: 'Tudi moja hrana, ki sem ti jo dal, fina moka, olje in med, s katero sem te hranil, celo to si postavljala prednje v prijeten vonj. In tako je to bilo,‹ govori Gospod Bog.',
        20: '›Poleg tega si jemala svoje sinove in svoje hčere, ki si mi jih rodila in te si jim žrtvovala, da bi bili požrti. Je to izmed tvojih vlačugarstev majhna zadeva,',
        21: 'da si morila moje otroke in jim jih izročala, da gredo zanje skozi ogenj?',
        22: 'In v vseh svojih ogabnostih in svojih vlačugarstvih se nisi spomnila dni svoje mladosti, ko si bila naga in gola in si bila oskrunjena v svoji krvi.‹',
        23: 'In pripetilo se je po vseh tvojih zlobnostih (gorje, gorje tebi!‹ govori Gospod Bog),',
        24: 'da si si zgradila tudi eminenten kraj in si si naredila visok kraj na vsaki ulici.',
        25: 'Visok kraj si si zgradila na vsakem začetku poti in storila si, da je bila tvoja lepota prezirana in svoja stopala si razprla vsakemu, ki je šel mimo in pomnožila si svoja vlačugarstva.',
        26: 'Prav tako si zagrešila prešuštvovanje z Egipčani, svojimi sosedi velikega uda in svoja vlačugarstva si povečala, da bi me dražila do jeze.',
        27: 'Glej, zato sem nad teboj iztegnil svojo roko in zmanjšal tvojo vsakdanjo hrano in te izročil volji tistih, ki te sovražijo, hčeram Filistejcev, ki se sramujejo tvojih nespodobnih poti.',
        28: 'Vlačugo si igrala tudi z Asirci, ker si bila nenasitna; da, z njimi si igrala pocestnico, pa vendar nisi mogla biti potešena.',
        29: 'Poleg tega si pomnožila svoje prešuštvovanje v kánaanski deželi do Kaldeje; in vendar nisi bila potešena s tem.',
        30: 'Kako šibko je tvoje srce,‹ govori Gospod Bog, ›glede na to, da počneš vse te stvari, delo gospodovalne vlačugarske ženske;',
        31: 'v tem, da si gradiš svoje eminentne kraje na začetku vsake poti in si delaš svoje visoke kraje na vsaki ulici; in nisi bila kot pocestnica, v tem, da preziraš plačilo,',
        32: 'temveč kakor žena, ki zagreši zakonolomstvo, ki jemlje tujce namesto svojega soproga!',
        33: 'Oni dajejo darila vsem vlačugam, toda ti daješ svoja darila vsem svojim ljubimcem in jih najemaš, da lahko pridejo k tebi na vsaki strani zaradi tvojega vlačugarstva.',
        34: 'In v tvojem vlačugarstvu je v tebi nasprotje od drugih žensk, da zagrešiš vlačugarstva, medtem ko ti nihče ne sledi, in pri tem ti daješ nagrado, tebi pa ni dana nobena nagrada, zato si nasprotje.‹',
        35: 'Zatorej, oh pocestnica, poslušaj besedo od Gospoda:',
        36: '›Tako govori Gospod Bog: ›Ker je bila tvoja umazanost izlita in tvoja nagota odkrita zaradi tvojega vlačugarstva s tvojimi ljubimci in z vsemi maliki tvojih ogabnosti in s krvjo tvojih otrok, ki si jim jih dala;',
        37: 'glej, zato bom zbral vse tvoje ljubimce, s katerimi si uživala in vse tiste, ki si jih ljubila, z vsemi tistimi, ki si jih sovražila; jaz jih bom celo zbral naokoli tebe zoper tebe in jim odkril tvojo nagoto, da bodo lahko videli vso tvojo nagoto.',
        38: 'Sodil te bom, kakor so sojene ženske, ki prelomijo zakonsko zvezo in prelijejo kri; in dal ti bom kri v razjarjenosti in ljubosumnosti.',
        39: 'Prav tako te bom izročil v njihovo roko in zrušili bodo tvoj eminenten kraj in zlomili tvoje visoke kraje. Slekli te bodo tudi iz tvojih oblačil in vzeli tvoje lepe dragocenosti in te pustili nago in golo.',
        40: 'Prav tako bodo zoper tebe privedli skupino in te bodo kamnali s kamni in te prebodli s svojimi meči.',
        41: 'Tvoje hiše bodo požgali z ognjem in izvršili sodbe nad teboj v očeh mnogih žensk. Povzročil ti bom, da prenehaš z igranjem pocestnice in tudi nobenega plačila ne boš več dajala.',
        42: 'Tako bom svoji razjarjenosti zoper tebe naredil, da počiva in moja ljubosumnost bo odšla od tebe in bom miren in ne bom več jezen.',
        43: 'Ker se nisi spomnila dni svoje mladosti, temveč si me razburjala v vseh teh stvareh; glej, zato bom tudi jaz poplačal tvojo pot na tvoji glavi,‹ govori Gospod Bog: ›in ne boš zagrešila te nespodobnosti nad vsemi svojimi ogabnostmi.',
        44: 'Glej, vsak, kdor uporablja pregovore, bo ta pregovor uporabil zoper tebe, govoreč: ›Kakršna je mati, takšna je njena hči.‹',
        45: '§ Ti si hči svoje matere, ki prezira svojega soproga in svoje otroke; in ti si sestra svojih sestrá, ki so prezirale svoje soproge in svoje otroke. Tvoja mati je bila Hetejka in tvoj oče Amoréjec.',
        46: '§ Tvoja starejša sestra je Samarija, ona in njene hčere, ki prebivajo na tvoji levici. Tvoja mlajša sestra, ki prebiva pri tvoji desnici, je Sódoma in njene hčere.',
        47: 'Vendar nisi hodila po njihovih poteh niti storila po njihovih ogabnostih. Temveč kot bi bila to malenkost, si bila bolj izprijena kakor one na vseh svojih poteh.',
        48: 'Kakor jaz živim,‹ govori Gospod Bog, ›niti tvoja sestra Sódoma niti njene hčere niso počele, kakor si storila ti in tvoje hčere.',
        49: 'Glej, to je bila krivičnost tvoje sestre Sódome, ponos, polnost kruha, obilje brezdelja v njej in v njenih hčerah niti ni krepila roke ubogega in pomoči potrebnega.',
        50: 'Bile so ošabne in zagrešile ogabnost pred menoj, zato sem jih vzel proč, kakor se mi je videlo dobro.',
        51: 'Niti ni Samarija zagrešila polovice tvojih grehov, temveč si pomnožila svoje ogabnosti bolj kakor oni [dve] in opravičila si svoji sestri v vseh svojih ogabnostih, ki si jih storila.',
        52: 'Tudi ti, ki si sodila svoji sestri, nosi svojo lastno sramoto za svoje grehe, ki si jih zagrešila bolj gnusno kakor oni [dve]. Oni sta pravičnejši kakor ti. Da, tudi ti bodi zbegana in nosi svojo sramoto v tem, da si opravičila svoji sestri.',
        53: '§ Ko bom ponovno privedel njihovo ujetništvo, ujetništvo Sódome in njenih hčera in ujetništvo Samarije in njenih hčera, takrat bom ponovno privedel ujetništvo tvojih ujetnikov v njihovi sredi,',
        54: 'da boš lahko nosila svojo lastno sramoto in boš lahko zbegana v vsem, kar si storila, v tem, da si jima tolažba.',
        55: 'Ko se bodo tvoje sestre, Sódoma in njene hčere, vrnile k svojemu prejšnjemu stanju in se bodo Samarija in njene hčere vrnile k svojemu prejšnjemu stanju, takrat se boste ti in tvoje hčere vrnile k svojemu prejšnjemu stanju.',
        56: 'Kajti tvoja sestra Sódoma ni bila omenjena s tvojimi usti na dan tvojega ponosa,',
        57: 'preden je bila odkrita tvoja zlobnost, kakor ob času, ko so te grajale sirske hčere in vsi tisti, ki so okrog nje, hčere Filistejcev, ki te prezirajo vsenaokrog.',
        58: 'Nosila si svojo nespodobnost in svoje ogabnosti,‹ govori Gospod.',
        59: '§ Kajti tako govori Gospod Bog: ›S teboj bom postopal celo kakor si ti storila, ki si prezirala prisego v prelamljanju zaveze.',
        60: 'Kljub temu se bom spomnil svoje zaveze s teboj v dneh tvoje mladosti in osnoval ti bom večno zavezo.',
        61: '§ Potem se boš spomnila svojih poti in boš osramočena, ko boš sprejela svoje sestre, svoje starejše in svoje mlajše, in dal ti jih bom za hčere, toda ne s tvojo zavezo.',
        62: 'S teboj bom utrdil svojo zavezo in vedela boš, da jaz sem Gospod,',
        63: 'da se lahko spomniš in boš zbegana in zaradi svoje sramote nikoli več ne boš odprla svojih ust, ko bom pomirjen proti tebi za vse, kar si storila,‹ govori Gospod Bog.‹«',
    },
    17: {
        1: 'K meni je prišla Gospodova beseda, rekoč:',
        2: '»Človeški sin, zastavi uganko in Izraelovi hiši spregovori prispodobo',
        3: 'in reci: ›Tako govori Gospod Bog: ›Velik orel, z velikimi perutmi, z dolgimi krili, polnimi peres, ki ima različne barve, je prišel k Libanonu in vzel najvišjo cedrovo mladiko.',
        4: 'Odstrigel je vrh njenih mladih vej in ga prenesel v deželo preprodajanja; postavil ga je v mestu trgovcev.',
        5: 'Prav tako je vzel od semena dežele in ga zasadil na rodovitno polje. Namestil ga je ob velikih vodah in ga postavil kakor drevo vrbe.',
        6: 'To je raslo in postalo razraščajoča se trta nizke rasti, čigar mladike so se obrnile proti njemu in njene korenine so bile pod njim. Tako je postala trta in obrodila mladike in poganjala vejice.',
        7: '§ Tam je bil tudi drug velik orel, z velikimi perutmi in mnogimi peresi. In glej, ta trta je svoje korenine upognila proti njemu in svoje mladike poganjala proti njemu, da bi jo ta lahko zalival pri brazdah njenega nasada.',
        8: 'Zasajena je bila v dobri zemlji, ob velikih vodah, da bi lahko pognala mladike in da bi lahko obrodila sad, da bi bila lahko čedna trta.‹',
        9: 'Reci: ›Tako govori Gospod Bog: ›Ali bo ta uspevala? Ali ji ne bo izruval njenih korenin in odrezal njen sad, da ovene? Ovenela bo pri vseh listih njenega izvira, celo brez velike moči ali mnogih ljudstev, da bi jo izruvali pri njenih koreninah.',
        10: 'Da, glej, ko je vsajena, ali bo uspevala? Ali ne bo popolnoma ovenela, ko se je dotakne vzhodnik? Ovenela bo na brazdah, kjer je zrasla.‹«',
        11: 'Poleg tega je prišla k meni Gospodova beseda, rekoč:',
        12: '»Reci torej uporni hiši: ›Mar ne veste kaj pomenijo te stvari?‹ Povej jim: ›Glejte, babilonski kralj je prišel v [prestolnico] Jeruzalem in zajel njenega kralja in njene prince in jih s seboj odvedel v Babilon',
        13: 'in zajel od kraljevega semena in z njim sklenil zavezo in od njega vzel prisego. Prav tako je zajel mogočneže dežele,',
        14: 'da bi bilo kraljestvo lahko ponižano, da se ne bi povzdigovalo, temveč da bi z ohranjanjem njegove zaveze lahko obstalo.',
        15: 'Toda ta se je uprl zoper njega s pošiljanjem svojih predstavnikov v Egipt, da bi mu lahko dali konje in veliko ljudstva. Ali bo uspel? Ali bo pobegnil ta, ki dela takšne stvari? Mar bo prelomil zavezo in bo osvobojen?',
        16: 'Kakor jaz živim,‹ govori Gospod Bog, ›zagotovo bo na kraju, kjer prebiva kralj, ki ga je postavil [za] kralja, čigar prisego je preziral in čigar zavezo je prelomil, celó pri njem bo umrl v sredi Babilona.',
        17: 'Niti ne bo faraon s svojo mogočno vojsko in svojim velikim spremstvom delal zanj v vojni, s postavljanjem okopov in gradnjo trdnjav, da iztrebi mnogo oseb,',
        18: 'ker je preziral prisego s prelamljanjem zaveze, ko je, glej, dal svojo roko in [vendar] storil vse te stvari; ne bo pobegnil.‹',
        19: 'Zato tako govori Gospod Bog: › Kakor jaz živim, zagotovo bo meni dano prisego, ki jo je preziral in mojo zavezo, ki jo je prelomil, celo to bom poplačal na njegovi lastni glavi.',
        20: 'Svojo mrežo bom razširil nad njim in ujet bo v mojo zanko in privedel ga bom v Babilon in tam se bom z njim pravdal zaradi njegovega prekrška, ki ga je prekršil zoper mene.',
        21: 'Vsi njegovi ubežniki, z vsemi njegovimi četami, bodo padli pod mečem, tisti pa, ki preostanejo, bodo razkropljeni proti vsem vetrovom. In vedeli boste, da sem jaz, Gospod, to govoril.‹',
        22: 'Tako govori Gospod Bog: ›Prav tako bom vzel od najvišje mladike na visoki cedri in jo bom posadil; od vrha njenih mladih vejic bom odstrigel eno nežno in jo zasadil na visoki in eminentni gori.',
        23: 'Na gori Izraelove višine jo bom zasadil in pognala bo veje in obrodila sad in postane čedna cedra. Pod njo bo prebivala vsa perjad od vsakega krila; v senci njenih mladik bodo prebivale.',
        24: '§ Vsa drevesa polja bodo vedela, da sem jaz, Gospod, ponižal visoko drevo, povišal nizko drevo, posušil zeleno drevo in suhemu drevesu storil, da cveti. Jaz, Gospod, sem govoril in sem to storil.‹«',
    },
    18: {
        1: 'Ponovno je prišla k meni Gospodova beseda, rekoč:',
        2: '»Kaj mislite, da uporabljate ta pregovor glede Izraelove dežele, rekoč: ›Očetje so jedli kislo grozdje, zobje otrok pa so skominasti?‹',
        3: 'Kakor jaz živim,‹ govori Gospod Bog, ›nič več ne boste imeli priložnosti, da v Izraelu uporabljate ta pregovor.',
        4: 'Glejte, vse duše so moje; kakor očetova duša, tako je tudi sinova duša moja. Duša, ki greši, ta bo umrla.',
        5: 'Toda če je človek pravičen in dela to, kar je zakonito in pravilno',
        6: 'in ni jedel po gorah, niti ni svojih oči povzdigoval k malikom Izraelove hiše, niti ni omadeževal žene svojega soseda, niti ni prišel blizu ženski, ki ima menstruacijo,',
        7: 'in ni nikogar zatiral, temveč je dolžniku povrnil njegovo jamstvo, ni nikogar oplenil z nasiljem, svoj kruh dajal lačnemu in nagega pokrival z obleko;',
        8: 'ta, ki ni dajal za obresti, niti ni jemal nobenega dobička, ki je svojo roko umikal pred krivičnostjo, izvrševal pošteno sodbo med možem in možem,',
        9: 'hodil po mojih zakonih in se držal mojih sodb, da pravilno postopa; ta je pravičen, zagotovo bo živel,‹ govori Gospod Bog.',
        10: '›Če zaplodi sina ta, ki je ropar, prelivalec krvi in ki dela podobno katerikoli izmed teh stvari',
        11: 'in ki ne dela katerokoli izmed teh dolžnosti, temveč je celo jedel po gorah in omadeževal ženo svojega soseda,',
        12: 'zatiral revnega in pomoči potrebnega, plenil z nasiljem, ni povračal jamstva in svoje oči povzdigoval k malikom, zagrešil ogabnost,',
        13: '§ dajal za obresti in jemal donos. Ali bo potem živel? Ta ne bo živel. Počenjal je vse te ogabnosti; zagotovo bo umrl; njegova kri bo na njem.',
        14: 'Torej glej, če zaplodi sina, ki vidi vse grehe svojega očeta, ki jih je storil in preudarja in ne dela temu podobno,',
        15: 'da ni jedel po gorah niti svojih oči ni povzdigoval k malikom Izraelove hiše, ni omadeževal žene svojega soseda',
        16: 'niti nobenega ni zatiral, ni zadrževal jamstva niti ni plenil z nasiljem, temveč je svoj kruh dajal lačnemu in nagega pokrival z obleko,',
        17: 'ki je zadrževal svoje roke pred [zatiranjem] revnega, ki ni prejemal obresti niti donosa, [ki je] izvrševal moje sodbe, hodil po mojih zakonih; ta ne bo umrl zaradi krivičnosti svojega očeta; zagotovo bo živel.',
        18: 'Kar se tiče njegovega očeta, ker je kruto zatiral, svojega brata plenil z nasiljem in med svojim ljudstvom počel to kar ni dobro, glej, celo ta bo umrl v svoji krivičnosti.',
        19: 'Vendar vi pravite: ›Zakaj? Ali sin ne nosi očetove krivičnosti? Kadar je sin storil, kar je zakonito in pravilno in se je držal vseh mojih zakonov in jih izvršil, bo zagotovo živel.',
        20: 'Duša, ki greši, ta bo umrla. Sin ne bo nosil očetove krivičnosti niti ne bo oče nosil sinove krivičnosti. Pravičnost pravičnega bo na njem in zlobnost zlobnega bo na njem.',
        21: 'Toda če se bo zlobni obrnil od vseh svojih grehov, ki jih je zagrešil in se držal vseh mojih zakonov in storil to, kar je zakonito in pravilno, bo zagotovo živel, ne bo umrl.',
        22: '§ Vsi njegovi prestopki, ki jih je zagrešil, mu ne bodo omenjeni. V svoji pravičnosti, ki jo je storil, bo živel.',
        23: 'Ali imam sploh kakšno zadovoljstvo, da bi zlobni umrl?‹ govori Gospod Bog: › in ne, da bi se vrnil iz svojih poti in živel?',
        24: '§ Toda ko se pravični obrne proč od svoje pravičnosti in zagreši krivičnost in počne glede na vse ogabnosti, ki jih počne zloben človek, ali bo živel? Vsa njegova pravičnost, ki jo je storil, ne bo omenjena. V svojem prekršku, ki ga je prekršil in v svojem grehu, ki ga je zagrešil, v njima bo umrl.',
        25: 'Vendar vi pravite: ›Gospodova pot ni primerna.‹ Poslušaj sedaj, oh Izraelova hiša; mar moja pot ni primerna? Ali niso vaše poti neprimerne?',
        26: 'Ko se pravičen človek obrne proč od svoje pravičnosti in zagreši krivičnost in umira v njiju; zaradi svoje krivičnosti, ki jo je storil, bo umrl.',
        27: '§ Ponovno, kadar se zloben človek obrne proč od svoje zlobnosti, ki jo je zagrešil in dela to, kar je zakonito in pravilno, bo svojo dušo rešil živo.',
        28: 'Ker preudarja in se odvrača proč od vseh svojih prestopkov, ki jih je zagrešil, bo zagotovo živel, ne bo umrl.',
        29: '§ Vendar Izraelova hiša pravi: ›Gospodova pot ni primerna.‹ Oh Izraelova hiša, mar moje poti niso primerne? Ali niso vaše poti neprimerne?',
        30: '§ Zatorej vas bom sodil, oh Izraelova hiša, vsakogar glede na njegove poti,‹ govori Gospod Bog. Pokesajte se in se obrnite od vseh svojih prestopkov; tako krivičnost ne bo vaš propad.',
        31: 'Od sebe odvrzite vse svoje prestopke, s katerimi ste se pregrešili in si naredite novo srce in novega duha, kajti zakaj hočete umreti, oh hiša Izraelova?',
        32: '§ Kajti jaz nimam nobenega zadovoljstva v smrti tistega, ki umira,‹ govori Gospod Bog: ›zatorej se obrnite in živite.‹',
    },
    19: {
        1: '›Poleg tega vzdigni žalostinko za Izraelovimi princi',
        2: 'in reci: ›Kaj je tvoja mati? Levinja. Ulegla se je med levi, svoje mladiče je hranila med mladimi levi.',
        3: 'Vzgojila je enega izmed svojih mladičev. Ta je postal mlad lev in se naučil loviti plen; ta je žrl ljudi.',
        4: 'Tudi narodi so slišali o njem; ujel se je v njihovo jamo in z verigami so ga odvedli v egiptovsko deželo.',
        5: '§ Torej ko je videla, da je čakala in je bilo njeno upanje izgubljeno, potem je vzela še enega izmed svojih mladičev in ga naredila za mladega leva.',
        6: 'In hodil je gor in dol med levi in postal mlad lev in se naučil loviti plen in žreti ljudi.',
        7: '§ In poznal je njihove zapuščene palače in pustošil njihova mesta; in dežela je bila zapuščena in njena polnost s hrupom njegovega rjovenja.',
        8: 'Potem so se narodi od provinc na vsaki strani naravnali zoper njega in nad njim razprostrli svojo mrežo. Ujet je bil v njihovo jamo.',
        9: 'In dali so ga pod stražo, v verige in ga privedli k babilonskemu kralju. Privedli so ga v utrdbe, da njegovega glasu ne bi bilo več slišati na Izraelovih gorah.',
        10: 'Tvoja mati je podobna trti v tvoji krvi, zasajena pri vodah. Bila je rodovitna in polna mladik zaradi razloga mnogih vodá.',
        11: 'Imela je močne palice za žezla tistih, ki so vladali in njena postava je bila povišana med debelimi mladikami in v svoji višini se je pojavila z množico svojih mladik.',
        12: 'Toda izruvana je bila v razjarjenosti, vržena je bila na tla in vzhodnik je posušil njen sad. Njene močne palice so bile polomljene in so ovenele, ogenj jih je použil.',
        13: 'In sedaj je zasajena v divjini, v suhih in žejnih tleh.',
        14: 'In ogenj je izšel iz palice njenih mladik, ki je požrl njen sad, tako da ni imela nobene močne palice, ki bi bila žezlo za vladanje. To je žalostinka in bo za žalostinko.‹«',
    },
    20: {
        1: 'In pripetilo se je v sedmem letu, v petem mesecu, deseti dan meseca, da so določeni izmed Izraelovih starešin prišli, da bi povpraševali od Gospoda in se usedli pred menoj.',
        2: 'Potem je prišla k meni Gospodova beseda, rekoč:',
        3: '»Človeški sin, govori Izraelovim starešinam in jim reci: ›Tako govori Gospod Bog: ›Ali ste prišli, da povprašujete od mene? Kakor jaz živim,‹ govori Gospod Bog, ›nočem biti povpraševan od vas.',
        4: 'Ali jih hočeš soditi, človeški sin, ali jih hočeš soditi? Povzroči jim, da spoznajo ogabnosti njihovih očetov',
        5: 'in jim reci: ›Tako govori Gospod Bog: ›Na dan, ko sem izbral Izraela in dvignil svojo roko k semenu Jakobove hiše in se jim dal spoznati v egiptovski deželi, ko sem vzdignil svojo roko k njim, rekoč: ›Jaz sem Gospod, vaš Bog;‹',
        6: 'na dan, ko sem vzdignil svojo roko k njim, da jih privedem iz egiptovske dežele v deželo, ki sem jo odkril zanje, tekočo z mlekom in medom, ki je slava vseh dežel.',
        7: 'Potem sem jim rekel: ›Vsak mož naj odvrže ogabnosti svojih oči in ne omadežujte se z egiptovskimi maliki.‹ Jaz sem Gospod, vaš Bog.‹',
        8: '›Toda uprli so se zoper mene in me niso hoteli poslušati. Noben mož ni odvrgel ogabnosti svojih oči niti niso zapustili egiptovskih malikov. Tedaj sem rekel: ›Nanje bom izlil svojo razjarjenost, da dovršim svojo jezo zoper njih v sredi egiptovske dežele.',
        9: 'Toda ravnal sem zaradi svojega imena, da to ne bi bilo oskrunjeno pred pogani, med katerimi so bili, v čigar pogledu sem se jim dal spoznati v tem, da sem jih privedel iz egiptovske dežele.',
        10: 'Zatorej sem jim velel, da gredo iz egiptovske dežele in jih privedel v divjino.',
        11: 'In dal sem jim svoje zakone in jim pokazal svoje sodbe, katere, če jih človek izpolnjuje, bo torej živel v njih.',
        12: 'Poleg tega sem jim dal tudi svoje šabate, da bodo znamenje med menoj in njimi, da bodo lahko vedeli, da jaz sem Gospod, ki jih posvečujem.',
        13: 'Toda Izraelova hiša se je uprla zoper mene v divjini. Niso hodili po mojih zakonih in prezirali so moje sodbe, katere, če jih človek izpolnjuje, bo torej živel v njih; in moje šabate so silno oskrunili. Potem sem rekel: ›V divjini bom nadnje izlil svojo razjarjenost, da jih použije.',
        14: 'Toda ravnal sem zaradi svojega imena, da le-to ne bi bilo oskrunjeno pred pogani, v katerem pogledu sem jih privedel ven.',
        15: 'Vendar sem prav tako vzdignil svojo roko k njim v divjini, da jih ne bom privedel v deželo, ki sem jim jo dal, tekočo z mlekom in medom, katera je slava vseh dežel;',
        16: 'zato ker so prezirali moje sodbe in niso hodili po mojih zakonih, temveč so oskrunili moje šabate, kajti njihovo srce je šlo za njihovimi maliki.',
        17: 'Kljub temu jim je moje oko prizaneslo pred tem, da bi jih uničil niti jim v divjini nisem storil konca.',
        18: 'Temveč sem njihovim otrokom v divjini rekel: ›Ne hodite po zakonih svojih očetov niti ne obeležujte njihovih sodb niti se ne omadežujte z njihovimi maliki.',
        19: 'Jaz sem Gospod, vaš Bog; ravnajte se po mojih zakonih in držite se mojih sodb in jih izvršujte;',
        20: 'in posvečujte moje šabate; in te bodo znamenje med menoj in vami, da boste lahko vedeli, da jaz sem Gospod, vaš Bog.‹',
        21: 'Vendar so se otroci uprli zoper mene. Niso se ravnali po mojih zakonih niti se niso ravnali po mojih sodbah, da bi jih izpolnjevali, katere, če človek izpolnjuje, bo torej živel po njih; oskrunjali so moje šabate. Potem sem rekel: ›Nadnje bom izlil svojo razjarjenost, da dovršim svojo jezo zoper njih v divjini.‹',
        22: 'Kljub temu sem umaknil svojo roko in zaradi svojega imena storil, da le-to ne bi bilo oskrunjeno pred očmi poganov, v čigar očeh sem jih izpeljal.',
        23: 'V divjini sem prav tako svojo roko vzdignil k njim, da bi jih razkropil med pogane in jih razpršil skozi dežele;',
        24: 'ker niso izvrševali mojih sodb, temveč so prezirali moje zakone in skrunili moje šabate in njihove oči so bile za maliki njihovih očetov.',
        25: '§ Zatorej sem jim prav tako izročil zakone, ki niso bili dobri in sodbe, po katerih naj ne bi živeli;',
        26: 'in oskrunil sem jih v njihovih lastnih darovih, s tem, da so počeli, da gre skozi ogenj vse, kar odpre maternico, da bi jih lahko naredil zapuščene, z namenom, da bi lahko vedeli, da jaz sem Gospod.‹',
        27: 'Zatorej, človeški sin, govori Izraelovi hiši in jim reci: ›Tako govori Gospod Bog: ›Vendar so vaši očetje proti meni izrekali bogokletje v tem, da so zagrešili prekršek zoper mene.',
        28: 'Kajti ko sem jih privedel v deželo, za katero sem vzdignil svojo roko, da jim jo dam, takrat so videli vsak visok hrib in vsa debela drevesa in tam so darovali svoje klavne daritve in tam so predstavljali izzivanje svojega daru. Tam so tudi naredili svoje prijetne dišave in tam so izlivali svoje pitne daritve.‹',
        29: 'Potem sem jim rekel: ›Kaj je visok kraj, kamor greste?‹ In njegovo ime je imenovano Bama do današnjega dne.',
        30: 'Zato reci Izraelovi hiši: ›Tako govori Gospod Bog: ›Ali ste oskrunjeni po načinu svojih očetov? In grešite vlačugarstvo po njihovih ogabnostih?',
        31: 'Kajti ko darujete svoje darove, ko svojim sinovom povzročate, da gredo skozi ogenj, same sebe oskrunjate z vsemi svojimi maliki, celo do današnjega dne. In ali naj bom povpraševan od vas, oh Izraelova hiša? Kakor jaz živim,‹ govori Gospod Bog, ›nočem biti povpraševan od vas.',
        32: 'In to, kar prihaja v vaše misli, sploh ne bo, da pravite: ›Mi bomo kakor pogani, kakor družine dežel, da služimo lesu in kamnu.‹',
        33: '› Kakor jaz živim,‹ govori Gospod Bog, ›zagotovo bom z mogočno roko in z iztegnjenim laktom in z izlito razjarjenostjo vladal nad vami',
        34: 'in vas izpeljem izmed ljudstva in vas zberem iz dežel, po katerih ste razkropljeni, z mogočno roko, z iztegnjenim laktom in z izlito razjarjenostjo.',
        35: 'In jaz vas bom privedel v divjino ljudstev in tam se bom pravdal z vami iz obličja v obličje.',
        36: 'Podobno kakor sem se pravdal z vašimi očeti v divjini egiptovske dežele, tako se bom pravdal z vami,‹ govori Gospod Bog.',
        37: '›In povzročil vam bom, da boste šli pod palico in privedel vas bom v vez zaveze',
        38: 'in izmed vas bom očistil upornike in tiste, ki so odpadli zoper mene. Izpeljal jih bom iz dežele, kjer začasno prebivajo in ne bodo vstopili v Izraelovo deželo in spoznali boste, da jaz sem Gospod.',
        39: '§ Glede vas, oh Izraelova hiša,‹ tako govori Gospod Bog: ›Pojdite, služite vsak svojim malikom in tudi v prihodnje, če mi nočete prisluhniti. Toda ne skrunite več mojega svetega imena s svojimi darovi in svojimi maliki.',
        40: 'Kajti na moji sveti gori, na gori Izraelove višine,‹ govori Gospod Bog, ›tam mi bo [služila] vsa Izraelova hiša, vsi izmed njih v deželi mi [bodo] služili. Tam jih bom sprejel in tam bom zahteval vaše daritve in prve sadove vaših daritev, z vsemi vašimi svetimi stvarmi.',
        41: 'Sprejel vas bom z vašim prijetnim vonjem, ko vas odvedem izmed ljudstev in vas zberem iz dežel, kamor ste bili razkropljeni; in jaz bom posvečen v vas pred pogani.',
        42: 'In vedeli boste, da jaz sem Gospod, ko vas bom privedel v Izraelovo deželo, v deželo, za katero sem vzdignil svojo roko, da jo dam vašim očetom.',
        43: 'In tam se boste spomnili svojih poti in vseh svojih dejanj, s katerimi ste bili omadeževani; in gnusili se boste samim sebi, v svojem lastnem pogledu, zaradi vseh svojih hudobij, ki ste jih storili.',
        44: 'In spoznali boste, da jaz sem Gospod, ko z vami postopam zaradi svojega imena, ne glede na vaše zlobne poti niti ne glede na vaša izprijena početja, oh vi, hiša Izraelova,‹ govori Gospod Bog.‹«',
        45: 'Poleg tega je prišla k meni Gospodova beseda, rekoč:',
        46: '»Človeški sin, naravnaj svoj obraz proti jugu in svojo besedo spusti proti jugu in prerokuj zoper gozd južnega polja;',
        47: 'in reci južnemu gozdu: ›Poslušaj Gospodovo besedo: ›Tako govori Gospod Bog: ›Glej, v tebi bom zanetil ogenj in ta bo v tebi pogoltnil vsako zeleno drevo in vsako suho drevo. Plameneč ogenj ne bo pogašen in vsi obrazi, od juga do severa, bodo v njem ožgani.',
        48: 'In vse meso bo videlo, da sem ga zanetil jaz, Gospod. Ta ne bo pogašen.‹«',
        49: 'Potem sem rekel: »Ah, Gospod Bog! O meni pravijo: ›Mar on ne govori prispodob?‹«',
    },
    21: {
        1: 'In k meni je prišla Gospodova beseda, rekoč:',
        2: '»Človeški sin, naravnaj svoj obraz proti Jeruzalemu in spusti svojo besedo proti svetim krajem in prerokuj zoper Izraelovo deželo',
        3: 'in reci Izraelovi deželi: ›Tako govori Gospod: ›Glej, jaz sem zoper tebe in izvlekel bom svoj meč iz nožnice in iz tebe bom iztrebil pravičnega in zlobnega.',
        4: 'Ker bom iz tebe iztrebil pravičnega in zlobnega, bo zato moj meč šel iz nožnice zoper vse meso od juga do severa,',
        5: 'da bo lahko vse meso vedelo, da sem jaz, Gospod, izvlekel svoj meč iz nožnice. Ta se ne bo več vrnil.',
        6: 'Zdihuj torej, ti, človeški sin, s trganjem svojih ledij; in z grenkim vzdihom pred njihovimi očmi.',
        7: 'In zgodilo se bo, ko ti bodo rekli: ›Zakaj vzdihuješ?‹ da boš odgovoril: ›Zaradi novic, ker le-te prihajajo.‹ In vsako srce se bo stopilo in vse roke bodo slabotne in vsak duh bo medlel in vsa kolena bodo šibka kakor voda. Glej, to prihaja in se bo zgodilo,‹ govori Gospod Bog.«',
        8: 'Ponovno je prišla k meni Gospodova beseda, rekoč:',
        9: '»Človeški sin, prerokuj in reci: ›Tako govori Gospod: ›Reci: ›Meč, meč je nabrušen in tudi zglajen.',
        10: 'Nabrušen je, da naredi boleč pokol; zglajen je, da se lahko lesketa. Naj bi se mi potem razveseljevali? Ta zaničuje palico mojega sina kakor vsako drevo.',
        11: 'In on ga je dal zgladiti, da bi lahko z njim rokoval. Ta meč je nabrušen in zglajen, da ga da v roko ubijalca.',
        12: 'Jokaj in tuli, človeški sin, kajti ta bo nad mojim ljudstvom, ta bo nad Izraelovimi princi. Strahote zaradi meča bodo nad mojim ljudstvom. Udari torej na svoje stegno.',
        13: 'Ker je to preizkušnja in kaj če meč zaničuje celo palico? To ne bo več,‹ govori Gospod Bog.',
        14: '›Ti torej, človeški sin, prerokuj in zaploskaj s svojima rokama in naj bo meč tretjič podvojen, meč umorjenih. To je meč velikih ljudi, ki so umorjeni, ki vstopa v njihove skrivne sobe.',
        15: 'Konico meča sem naravnal zoper vsa njihova velika vrata, da bo njihovo srce lahko slabelo in [bodo] njihovi propadi pomnoženi. Ah! Narejen je [da se] lesketa, zavit je za pokol.',
        16: 'Pojdi eno pot ali drugo, ali na desno ali na levo, kamor je naravnan tvoj obraz.',
        17: 'Tudi jaz bom plosknil s svojima rokama in bom umiril svojo razjarjenost. Jaz, Gospod, sem to govoril.‹«',
        18: 'Ponovno je prišla k meni Gospodova beseda, rekoč:',
        19: '»Tudi ti, človeški sin, si določi dve poti, da bo lahko prišel meč babilonskega kralja. Obe bosta izšli iz ene dežele in izberi kraj, izberi ga ob začetku poti v mesto.',
        20: 'Določi pot, da lahko pride meč v Rabo Amóncev in v Juda in zaščiteno [prestolnico] Jeruzalem.',
        21: 'Kajti babilonski kralj je stal pri razpotju poti, ob začetku dveh poti, da uporabi vedeževanje. Svoje puščice je posvetlil, posvetoval se je z družinskimi maliki, gledal je v jetra.',
        22: 'Pri njegovi desni roki je bilo vedeževanje za [prestolnico] Jeruzalem, da določi častnike, da odpre usta v pokol, da povzdigne glas s kričanjem, da določi oblegovalne ovne proti velikim vratom, da nasuje nasip in da zgradi utrdbo.',
        23: 'In to jim bo kakor napačno vedeževanje v njihovem pogledu, tistim, ki so prisegli prisege, toda v spomin bo priklical krivičnost, da bodo lahko zajeti.‹',
        24: 'Zato tako govori Gospod Bog: ›Ker ste storili, da se bo spominjalo vaše krivičnosti v tem, da so vaši prestopki odkriti, tako da se pri vseh vaših dejanjih pojavijo vaši grehi; ker jaz pravim, da ste prišli v spomin, boste zajeti z roko.',
        25: 'In ti, oskrunjen, zloben Izraelov princ, katerega dan je prišel, ko se krivičnosti naredi konec,‹',
        26: 'tako govori Gospod Bog: ›Odstrani diadem in snemi krono. To ne bo [več] isto. Povišaj tistega, ki je nizek in ponižaj tistega, ki je visok.',
        27: 'Jaz bom to preobrnil, preobrnil, preobrnil in tega ne bo nič več, dokler ne pride tisti, katerega pravica je to in njemu jo bom izročil.‹',
        28: 'Ti pa, človeški sin, prerokuj in reci: ›Tako govori Gospod Bog glede Amóncev in glede njihove graje; celo reci: ›Meč, meč je izvlečen. Za pokol je zglajen, da použiva zaradi lesketanja.',
        29: 'Medtem ko zate vidijo ničnost, medtem ko ti vedežujejo laž, da te privedejo nad vratove tistih, ki so umorjeni izmed zlobnih, katerih dan je prišel, ko bo njihova krivičnost končana.',
        30: 'Ali mu bom povzročil, da se vrne v svojo nožnico? Sodil te bom na kraju, kjer si bil ustvarjen, v deželi tvojega rojstva.',
        31: 'In nate bom izlil svoje ogorčenje in zoper tebe bom pihal v ognju svojega besa in te izročil v roko brutalnežev in veščih, da uničujejo.',
        32: 'Ti boš za gorivo ognju; tvoja kri bo v sredi dežele; ne bo se te več spominjalo, kajti jaz, Gospod, sem to govoril.‹«',
    },
    22: {
        1: 'Poleg tega je prišla k meni Gospodova beseda, rekoč:',
        2: '»Torej, človeški sin, ali boš sodil, ali boš sodil krvoločno mesto? Da, pokazal mu boš vse njegove ogabnosti.',
        3: 'Potem reci: ›Tako govori Gospod Bog: ›Mesto v svoji sredi preliva kri, da lahko pride njegov čas in zoper sebe izdeluje malike, da se omadežuje.',
        4: 'Postalo si krivo v svoji krvi, ki si jo prelilo; in omadeževalo si se s svojimi maliki, ki si jih naredilo; in svojim dnevom si povzročilo, da so se približali in prišlo si celó k svojim letom. Zato sem te naredil za grajo poganom in zasmeh vsem deželam.',
        5: 'Tisti, ki so blizu in tisti, ki so daleč od tebe, te bodo zasmehovali, ki so neslavni in precej nadležni.',
        6: 'Glej, Izraelovi princi, vsak je bil v tebi k njihovi moči, da preliva kri.',
        7: 'V tebi so prezirali očeta in mater. V tvoji sredi so z zatiranjem postopali s tujcem. V tebi so nadlegovali osirotelega in vdovo.',
        8: 'Preziralo si moje svete stvari in oskrunilo moje šabate.',
        9: 'V tebi so ljudje, ki prenašajo govorice, da prelijejo kri; in v tebi jedo po gorah. V tvoji sredi zagrešujejo nespodobnost.',
        10: 'V tebi so odkrili nagoto svojih očetov. V tebi so ponižali tisto, ki je bila oddvojena zaradi oskrunitve.',
        11: 'In nekdo je zagrešil ogabnost z ženo svojega soseda; in drugi je opolzko omadeževal svojo snaho; in drugi je v tebi ponižal svojo sestro, hčer svojega očeta.',
        12: 'V tebi so jemali darila, da prelijejo kri. Jemalo si obresti in donos in z izsiljevanjem si lakomno pridobivalo od svojih sosedov in si me pozabilo,‹ govori Gospod Bog.',
        13: '›Glej, zato sem udaril svojo roko ob tvoj nepošten dobiček, ki si ga naredilo in pri tvoji krvi, ki je bila v tvoji sredi.',
        14: 'Ali tvoje srce lahko prenese, ali so tvoje roke lahko močne v dneh, ko bom obračunal s teboj? Jaz, Gospod sem to govoril in bom to storil.',
        15: 'In razkropil te bom med pogane in te razpršil v dežele in iz tebe použil tvojo umazanost.',
        16: 'In vzelo boš svojo dediščino v sebi, pred očmi poganov in vedelo boš, da jaz sem Gospod.‹«',
        17: 'In k meni je prišla Gospodova beseda, rekoč:',
        18: '»Človeški sin, Izraelova hiša mi je postala žlindra. Vsi so bron, kositer, železo in svinec v sredi talilne peči; so celó srebrova žlindra.',
        19: 'Zato tako govori Gospod Bog: ›Ker ste vsi postali žlindra, glejte, zato vas bom zbral v sredi [prestolnice] Jeruzalem.',
        20: 'Kakor oni zbirajo srebro in bron in železo in svinec in kositer v sredi talilne peči, da nanjo pihajo ogenj, da to raztalijo; tako vas bom jaz zbral v svoji jezi in svoji razjarjenosti in vas bom pustil tam in vas raztalil.',
        21: 'Da, zbral vas bom in pihal nad vas v ognju svojega besa in vi boste raztaljeni v njeni sredi.',
        22: 'Kakor je srebro raztaljeno v sredi talilne peči, tako boste raztaljeni v njeni sredi in spoznali boste, da sem jaz, Gospod, nad vas izlil svojo razjarjenost.‹«',
        23: 'In k meni je prišla Gospodova beseda, rekoč:',
        24: '»Človeški sin, reci ji: ›Ti si dežela, ki ni očiščena niti ni nanjo deževalo na dan ogorčenja.',
        25: 'Tam je zarota njenih prerokov v njeni sredi, podobna rjovenju leva, željnega plena. Požrli so duše, vzeli so zaklad in dragocene stvari; v njeni sredi so naredili mnogo vdov.',
        26: 'Njeni duhovniki so prekršili mojo postavo in oskrunili moje svete stvari. Niso pokazali nobene razlike med svetim in oskrunjenim niti niso pokazali razlike med nečistim in čistim in svoje oči so skrili pred mojimi šabati in jaz sem med njimi oskrunjen.',
        27: 'Njeni princi v njeni sredi so podobni volkovom, željnim plena, da prelijejo kri in da uničijo duše, da pridobijo nepošten dobiček.',
        28: 'In njeni preroki so jih ometali z neutrjeno malto, gledoč ničnost in vedeževali so jim laži, rekoč: ›Tako govori Gospod Bog,‹ ko Gospod ni govoril.',
        29: 'Ljudstvo dežele je uporabljalo zatiranje in izvajalo rop in jezilo revne in pomoči potrebne; da, krivično so zatirali tujca.',
        30: 'In iskal sem človeka med njimi, ki bi naredil ograjo in stal v razpoki pred menoj za deželo, da je ne bi uničil, toda nikogar nisem našel.',
        31: 'Zato sem nadnje izlil svoje ogorčenje; použil sem jih z ognjem svojega besa. Njihovo lastno pot sem poplačal na njihovih glavah,‹ govori Gospod Bog.‹«',
    },
    23: {
        1: 'Beseda Gospodova je ponovno prišla k meni, rekoč:',
        2: '»Človeški sin, bili sta dve ženski, hčeri ene matere.',
        3: '§ Zagrešili sta vlačugarstva v Egiptu, v svoji mladosti sta zagrešili vlačugarstva. Tam so bile njune prsi stiskane, tam so poškodovali seske njunega devištva.',
        4: 'Njuni imeni sta bili: Ohóla, starejša in njena sestra Oholíba. Bili sta moji in rodili sta sinove in hčere. Taki sta bili njuni imeni: Samarija je Ohóla, [prestolnica] Jeruzalem pa Oholíba.',
        5: 'Ohóla je igrala pocestnico, ko je bila moja in nora je bila na svoje ljubimce, na Asirce, svoje sosede,',
        6: 'ki so bili oblečeni z modro, častnike in vladarje, vse izmed njih privlačne mladeniče, konjenike, jahajoče na konjih.',
        7: 'Tako je z njimi zagrešila svoja vlačugarstva, z vsemi tistimi, ki so bili izbrani možje Asirije in z vsemi, na katere je bila nora, z vsemi njihovimi maliki, s katerimi se je omadeževala.',
        8: 'Niti ni zapustila svojih vlačugarstev, prinesenih iz Egipta, kajti v njeni mladosti so ležali z njo in poškodovali prsi njenega devištva in nanjo izlili svoja vlačugarstva.',
        9: 'Zatorej sem jo izročil v roko njenih ljubimcev, v roko Asircev, na katere je bila nora.',
        10: 'Ti so odkrili njeno nagoto. Vzeli so njene sinove in njene hčere in jo usmrtili z mečem in postala je slavna med ženskami, kajti izvršili so sodbo nad njo.',
        11: 'In ko je njena sestra Oholíba to videla, je bila bolj izprijena v svoji neobrzdani ljubezni kakor ona in v svojih vlačugarstvih bolj kakor njena sestra v njenih vlačugarstvih.',
        12: 'Nora je bila na Asirce, svoje sosede, častnike in vladarje, najbolj krasno oblečene, konjenike, jahajoče na konjih, vse izmed njih privlačne mladeniče.',
        13: 'Potem sem videl, da je bila omadeževana, da sta obe šli eno pot.',
        14: 'In povečala je svoja vlačugarstva, kajti ko je zagledala može, upodobljene na zidu, podobe Kaldejcev, upodobljene z živo rdečo,',
        15: 'opasane s pasovi na svojih ledjih, z izjemnim okrasom na svojih glavah, vse izmed njih na pogled prince, po načinu Babiloncev iz Kaldeje, dežele njihovega rojstva;',
        16: 'takoj ko jih je s svojimi očmi zagledala, je bila nora nanje in k njim poslala poslance v Kaldejo.',
        17: 'In Babilonci so prišli k njej v posteljo ljubezni in jo omadeževali s svojim vlačugarstvom in bila je onesnažena z njimi in njen um se je odtujil od njih.',
        18: 'Tako je odkrila svoja vlačugarstva in odkrila svojo nagoto. Potem se je moj um odtujil od nje, podobno kakor je bil moj um odtujen od njene sestre.',
        19: 'Vendar je svoja vlačugarstva pomnožila s spominjanjem na dni svoje mladosti, v katerih je igrala pocestnico v egiptovski deželi.',
        20: 'Kajti nora je bila na svoje nezakonite ljubimce, katerih meso je kakor meso oslov in katerih izliv je podoben izlivu konjev.',
        21: 'Tako si klicala v spomin nespodobnost svoje mladosti, v poškodovanju tvojih seskov s strani Egipčanov, zaradi tvojih mladostnih prsi.',
        22: 'Zato, oh Oholíba,‹ tako govori Gospod Bog: ›Glej, zoper tebe bom obudil tvoje ljubimce, od katerih se je odtujil tvoj um in na vsaki strani jih bom privedel zoper tebe;',
        23: 'Babilonce in vse Kaldejce, Pekód in Šoo in Koo in vse Asirce z njimi, vse izmed njih privlačne mladeniče, častnike in vladarje, velike gospode in ugledne, vse izmed njih jahajoče na konjih.',
        24: 'In prišli bodo zoper tebe z bojnimi vozovi, vozovi in kolesi in z zborom ljudstva, ki bo naokoli nastavilo zoper tebe majhen ščit in ščit in čelado. Prednje bom postavil sodbo in sodili te bodo glede na svoje sodbe.',
        25: 'In zoper tebe bom naravnal svojo ljubosumnost in besno bodo postopali s teboj. Odvzeli ti bodo tvoj nos in tvoja ušesa; in tvoj preostanek bo padel pod mečem. Odvzeli bodo tvoje sinove in tvoje hčere; in tvoj preostanek bo požrt z ognjem.',
        26: 'Tudi slekli te bodo iz tvojih oblačil in ti odvzeli tvoje lepe dragocenosti.',
        27: 'Tako bom tvoji nespodobnosti storil, da izgine od tebe in tvojemu vlačugarstvu, privedenemu iz egiptovske dežele, da svojih oči ne boš dvignila k njim niti se ne boš več spominjala Egipta.‹',
        28: 'Kajti tako govori Gospod Bog: ›Glej, izročil te bom v roko tistih, ki jih sovražiš, v roko tistih, od katerih se je tvoj um odtujil.',
        29: 'S teboj bodo postopali sovražno in ves tvoj trud bodo odvedli in pustili te bodo nago in boso. Odkrita bo nagota tvojih vlačugarstev, tako tvoja nespodobnost kot tvoja vlačugarstva.',
        30: 'Jaz ti bom storil te stvari, ker si vlačugarsko odšla za pogani in ker si oskrunjena z njihovimi maliki.',
        31: 'Hodila si po poti svoje sestre; zato bom njeno čašo dal v tvojo roko.‹',
        32: 'Tako govori Gospod Bog: ›Pila boš iz čaše svoje sestre, globoke in velike. Zasmehovana boš do norčevanja in v posmeh; ta mnogo drži.',
        33: 'Napolnjena boš s pijanostjo in bridkostjo, s čašo osuplosti in opustošenja, s čašo tvoje sestre Samarije.',
        34: 'To boš celo pila in to izsesala in zlomila boš njene črepinje in iztrgala svoje lastne prsi, kajti jaz sem to govoril,‹ govori Gospod Bog.',
        35: 'Zato tako govori Gospod Bog: ›Ker si me pozabila in me vrgla za svoj hrbet, zatorej tudi ti nosi svoje nespodobnosti in svoja vlačugarstva.‹',
        36: 'Gospod mi je poleg tega rekel: »Človeški sin, hočeš soditi Ohólo in Oholíbo? Da, razglasi jima njune ogabnosti;',
        37: 'da sta zagrešili zakonolomstvo in je kri na njunih rokah in s svojimi maliki sta zagrešili zakonolomstvo in tudi svojim sinovom, ki sta mi jih rodili, sta storili, da so zanju prešli skozi ogenj, da jih je požrl.',
        38: 'Poleg tega sta mi storili še to: v istem dnevu sta omadeževali moje svetišče in oskrunili moje šabate.',
        39: 'Kajti ko sta svoje otroke morili svojim malikom, potem sta istega dne prišli v moje svetišče, da ga oskrunita; in glej, tako sta počeli v sredi moje hiše.',
        40: 'In nadalje, da sta poslali po može, da pridejo od daleč, h katerim je bil poslan poslanec; in glej, prišli so, za katere si se umivala in ličila svoje oči in se odevala z ornamenti.',
        41: 'Sedela si na imenitni postelji in miza je pripravljena pred njo, na katero si postavljala moje kadilo in moje olje.',
        42: '§ In glas brezskrbne množice je bil z njo, in z običajnimi možmi so bili privedeni Sabejci iz divjine, ki si na svoje roke natikajo zapestnice in krasne krone na svoje glave.',
        43: 'Potem sem rekel njej, ki je bila stara v zakonolomstvih: ›Ali bodo sedaj zagrešili vlačugarstva z njo in ona z njimi?‹',
        44: 'Vendar so odšli noter k njej, kakor gredo v žensko, ki igra pocestnico, tako so šli noter v Ohólo in v Oholíbo, nespodobni ženski.',
        45: 'Pravični možje pa ju bodo sodili po načinu zakonolomk in po načinu žensk, ki prelivajo kri, ker sta zakonolomki in je kri na njunih rokah.‹',
        46: 'Kajti tako govori Gospod Bog: ›Nadnju bom privedel skupino in izročil ju bom, da bosta odstranjeni in oplenjeni.',
        47: 'In skupina ju bo kamnala s kamni in razmesarila s svojimi meči; ubili bodo njune sinove in njune hčere, njune hiše pa bodo požgali z ognjem.',
        48: 'Tako bom nespodobnosti storil, da izgine iz dežele, da bodo lahko vse ženske poučene, da ne počnejo po vajini nespodobnosti.',
        49: '§ In vajino nespodobnost bodo poplačali na vama in nosili bosta grehe svojih malikov, in spoznali bosta, da jaz sem Gospod Bog.‹«',
    },
    24: {
        1: 'V devetem letu, v desetem mesecu, na deseti dan meseca je ponovno prišla k meni Gospodova beseda, rekoč:',
        2: '»Človeški sin, zapiši si ime dneva, celó tega istega dne. Babilonski kralj se je ta isti dan nameril zoper [prestolnico] Jeruzalem.',
        3: 'In izreci prispodobo uporni hiši ter jim reci: ›Tako govori Gospod Bog: ›Pristavi lonec, pristavi ga in prav tako vanj nalij vodo.',
        4: 'Zberi vanj kose, celó vsak dober kos, stegno in pleče; napolni ga z izbranimi kostmi.',
        5: 'Vzemi izbrano od tropa in pod njim prav tako sežgi kosti in naredi, da bo dobro vrelo in v njem naj prevrejo njegove kosti.‹',
        6: 'Zato tako govori Gospod Bog: ›Gorje krvoločnemu mestu, loncu, čigar plast umazanije je v njem in katerega plast umazanije ni odšla od njega! Prinesi to ven, kos za kosom; naj noben žreb ne pade na to.',
        7: 'Kajti njena kri je v njeni sredi; postavljala jo je na vrh skale; ni je izlivala na tla, da jo pokrije s prahom;',
        8: 'da bi lahko povzročila razjarjenosti, da pride gor, da se maščuje; njeno kri sem postavil na vrh skale, da ne bi bila pokrita.‹',
        9: 'Zato tako govori Gospod Bog: ›Gorje krvoločnemu mestu! Naredil bom celo grmado za velik ogenj.',
        10: 'Nakopičite les, zanetite ogenj, použijte meso in ga dobro začinite in naj bodo kosti sežgane.',
        11: 'Potem ga praznega postavite na ognjeno oglje, da njegov bron lahko razbeli in lahko zagori in da bo njegova umazanost lahko v njem stopljena, da bo plast umazanije v njem lahko použita.',
        12: 'Samo sebe je izmučila z lažmi in njena velika plast umazanije ni šla ven iz nje. Njena plast umazanije bo v ognju.',
        13: 'V tvoji umazanosti je nespodobnost. Ker sem te očistil, ti pa nisi bila očiščena, ne boš več očiščena svoje umazanosti, dokler svoji razjarjenosti ne storim, da počiva na tebi.',
        14: '§ Jaz, Gospod, sem to govoril. To se bo zgodilo in jaz bom to storil; ne bom šel nazaj niti ne bom prizanašal niti se ne bom kesal; glede na tvoje poti in glede na tvoja početja te bodo sodili,‹ govori Gospod Bog.«',
        15: 'Prav tako je prišla k meni Gospodova beseda, rekoč:',
        16: '»Človeški sin, glej, z udarcem vzamem od tebe željo tvojih oči. Vendar ne boš žaloval niti jokal niti tvoje solze ne bodo tekle.',
        17: 'Zadrži se jokanja, nobenega žalovanja za mrtvimi ne opravljaj, nad svojo glavo si zaveži ruto in nadeni si svoje čevlje na svoja stopala in ne pokrivaj svojih ustnic in ne jej kruha od ljudi.«',
        18: 'Tako sem ljudstvu govoril zjutraj, zvečer pa je moja žena umrla; in zjutraj sem storil, kakor mi je bilo ukazano.',
        19: 'In ljudstvo mi je reklo: »Ali nam ne boš povedal kaj so nam te stvari, da jih tako počneš?«',
        20: 'Potem sem jim odgovoril: »K meni je prišla Gospodova beseda, rekoč:',
        21: '›Govori Izraelovi hiši: ›Tako govori Gospod Bog: ›Glejte, oskrunil bom svoje svetišče, odličnost vaše moči, željo vaših oči in to, kar vaša duša pomiluje; in vaši sinovi in vaše hčere, ki ste jih pustili, bodo padli pod mečem.',
        22: 'In storili boste, kakor sem jaz storil: ne boste pokrili svojih ustnic niti jedli kruha od ljudi.',
        23: 'In vaše rute bodo na vaših glavah in vaši čevlji na vaših stopalih. Ne boste niti žalovali niti jokali; temveč boste hirali zaradi svojih krivičnosti in žalovali drug proti drugemu.',
        24: 'Tako vam je Ezekiel znamenje: glede na vse, kar je storil, boste vi storili. In ko to pride, boste spoznali, da jaz sem Gospod Bog.',
        25: 'Tudi ti, človeški sin, ali ne bo to na dan, ko jim odvzamem njihovo moč, radost njihove slave, željo njihovih oči in to, na kar so naravnali svoje ume, njihove sinove in njihove hčere,',
        26: 'da bo tisti, ki pobegne na ta dan, prišel k tebi, da ti povzroči, da to slišiš s svojimi lastnimi ušesi?',
        27: 'Na tisti dan se bodo tvoja usta odprla k tistemu, ki je pobegnil in govoril boš in ne boš več nem. Ti jim boš znamenje. In spoznali bodo, da jaz sem Gospod.‹«',
    },
    25: {
        1: 'Beseda Gospodova je ponovno prišla k meni, rekoč:',
        2: '»Človeški sin, naravnaj svoj obraz proti Amóncem in prerokuj zoper njih;',
        3: 'in reci Amóncem: ›Poslušajte besedo Gospoda Boga. Tako govori Gospod Bog, ker praviš: ›Aha, zoper moje svetišče, ko je bilo oskrunjeno; in zoper Izraelovo deželo, ko je bila zapuščena; in zoper Judovo hišo, ko so odšli v ujetništvo;‹',
        4: 'glej, zatorej te bom izročil možem vzhoda za posest in v tebi si bodo postavili svoje palače in svoja prebivališča bodo naredili v tebi. Jedli bodo tvoj sad in pili bodo tvoje mleko.',
        5: 'In jaz bom Rabo naredil hlev za kamele in Amónce kraj ležišča za trope, in spoznali boste, da jaz sem Gospod.‹',
        6: 'Kajti tako govori Gospod Bog: ›Ker si ploskal s svojima rokama in topotal s stopali in se razveseljeval v srcu z vsem svojim prezirom zoper Izraelovo deželo;',
        7: 'glej, zato bom nadte iztegnil svojo roko in te izročil v plen poganom; in jaz te bom odrezal izmed ljudstev in ti povzročil, da izgineš iz dežel. Uničil te bom, in vedel boš, da jaz sem Gospod.‹',
        8: 'Tako govori Gospod Bog: ›Zato ker Moáb in Seír govorita: ›Glej, Judova hiša je podobna vsem poganom;‹',
        9: 'zatorej, glej, odprl bom Moábov bok od mest, od njegovih mest, ki so na njegovih mejah, slavo dežele: Bet Ješimót, Báal Meón in Kirjatájim,',
        10: 'do mož vzhoda z Amónci [vred] in jih dal v posest, da se Amóncev ne bo spominjalo med narodi.',
        11: 'In izvršil bom sodbe nad Moábom; in spoznali bodo, da jaz sem Gospod.‹',
        12: 'Tako govori Gospod Bog: ›Zato ker je Edóm zoper Judovo hišo ravnal z maščevanjem in [jih] silno užalil in se maščeval nad njimi;‹',
        13: 'zato tako govori Gospod Bog: ›Tudi jaz bom svojo roko iztegnil nad Edóm in iz njega bom iztrebil moža in žival; in opustošil ga bom od Temána; in tisti iz Dedána bodo padli pod mečem.',
        14: 'In svoje maščevanje bom položil nad Edóm po roki svojega ljudstva Izraela, in v Edómu bodo storili glede na mojo jezo in glede na mojo razjarjenost; in spoznali bodo moje maščevanje,‹ govori Gospod Bog.',
        15: 'Tako govori Gospod Bog: ›Ker so Filistejci postopali z maščevanjem in so se maščevali s krutim srcem, da ga uničijo zaradi starega sovraštva;‹',
        16: 'zato tako govori Gospod Bog: ›Glej, svojo roko bom iztegnil nad Filistejce in iztrebil bom Keretéjce in uničil bom preostanek morske obale.',
        17: 'In nad njimi bom izvršil veliko maščevanje z besnimi grajami; in spoznali bodo, da jaz sem Gospod, ko bom nanje položil svoje maščevanje.‹«',
    },
    26: {
        1: 'In pripetilo se je v enajstem letu, na prvi dan meseca, da je prišla k meni Gospodova beseda, rekoč:',
        2: '»Človeški sin, zato ker je Tir zoper [prestolnico] Jeruzalem rekel: ›Aha, zlomljena je tista, ki je bila velika vrata ljudstvom, obrnjena je k meni: ›Na novo bom napolnjena,‹ sedaj je opustošena.‹',
        3: 'Zato tako govori Gospod Bog: ›Glej, jaz sem zoper tebe, oh Tir in povzročil bom, da bodo zoper tebe prišli številni narodi, kakor morje povzroči svojim valovom, da se vzdignejo gor.',
        4: 'In uničili bodo zidove Tira in porušili njegove stolpe. Prav tako bom iz njega postrgal prah in ga naredil podobnega vrhu skale.',
        5: 'To bo kraj za razprostiranje mrež sredi morja, kajti jaz sem to govoril,‹ govori Gospod Bog: ›in bo postal plen narodom.',
        6: '§ In njegove hčere, ki so na polju, bodo umorjene z mečem; in spoznali bodo, da jaz sem Gospod.‹',
        7: 'Kajti tako govori Gospod Bog: ›Poglej, nad Tir bom privedel babilonskega kralja Nebukadnezarja, kralja kraljev, iz severa, s konji in bojnimi vozovi in s konjeniki in skupinami in mnogo ljudstva.',
        8: 'Na polju bo z mečem ubil tvoje hčere in naredil bo utrdbo zoper tebe in zoper tebe nasul nasip in zoper tebe vzdignil majhen ščit.',
        9: 'Svoje vojne stroje bo uperil zoper tvoje zidove in s svojimi sekirami bo porušil tvoje stolpe.',
        10: 'Zaradi obilja njegovih konj te bo pokril njihov prah. Tvoji zidovi se bodo tresli ob hrupu konjenikov, koles in bojnih vozov, ko bo vstopil v tvoja velika vrata, kakor možje vstopijo v mesto, v katerem je narejena vrzel.',
        11: 'S kopiti svojih konj bo pomendral vse tvoje ulice. Tvoje ljudstvo bo pobil z mečem in tvoje močne posadke bodo popadale na tla.',
        12: 'Iz tvojih bogastev bodo naredili plen in zaplenili bodo tvoje trgovanje in porušili bodo tvoje zidove in uničili tvoje prijetne hiše in tvoje kamne, tvoj les in tvoj prah bodo pometali v sredo voda.',
        13: 'In povzročil bom, da bo hrup tvojih pesmi prenehal, in zvoka tvojih harf ne bo več slišati.',
        14: 'In naredil te bom kakor vrh skale. Ti boš kraj, na katerem se razprostirajo mreže; ne boš več pozidan, kajti jaz, Gospod, sem to govoril,‹ govori Gospod Bog.',
        15: 'Tako govori Gospod Bog Tiru: ›Mar se ne bodo otoki stresli ob zvoku tvojega padca, ko bodo ranjeni jokali, ko bo v tvoji sredi narejen pokol?',
        16: 'Potem bodo vsi morski princi stopili dol iz svojih prestolov in odložili svoja svečana oblačila in slekli svoje izvezene obleke. Oblekli se bodo s trepetanjem. Sedeli bodo na tleh in trepetali bodo vsak trenutek in osupli bodo nad teboj.',
        17: 'In zate bodo povzdignili žalostinko in ti rekli: ›Kako si uničen, ki si bil naseljen s pomorščaki, ugledno mesto, ki je bilo močno na morju, ono in njegovi prebivalci, ki so svoji strahoti povzročili, da je bila na vseh, ki so ga strašili!',
        18: 'Sedaj bodo otoki trepetali na dan tvojega padca; da, otoki, ki so na morju, bodo vznemirjeni ob tvojem odhodu.‹',
        19: 'Kajti tako govori Gospod Bog: ›Ko te bom naredil [za] zapuščeno mesto, podobno mestom, ki niso naseljena; ko bom nadte privedel globino in te bodo pokrile velike vode,',
        20: 'ko te bom privedel dol s tistimi, ki se spuščajo v jamo, z ljudstvom iz starih časov in te bodo postavili v spodnje kraje zemlje, na kraje, ki so zapuščeni od davnine, s tistimi, ki gredo dol do jame, da ne boš naseljen, in jaz bom postavil slavo v deželi živih;',
        21: 'naredil te bom strahoto in tebe ne bo več. Čeprav te bodo iskali, vendar nikoli več ne boš najden,‹ govori Gospod Bog.‹«',
    },
    27: {
        1: 'Beseda Gospodova je ponovno prišla k meni, rekoč:',
        2: '»Torej ti, človeški sin, vzdigni žalostinko za Tirom;',
        3: 'in reci Tiru: ›Oh ti, ki si postavljen na vhodu morja, ki si trgovec ljudstvom na številnih otokih: ›Tako govori Gospod Bog: ›O Tir, rekel si: ›Jaz sem popolne lepote.‹‹',
        4: 'Tvoje meje so v sredi morij, tvoji graditelji so dovršili tvojo lepoto.',
        5: 'Vse tvoje ladijske deske so naredili iz cipresovega lesa iz Senírja. Vzeli so libanonske cedre, da bi zate naredili jambore.',
        6: '§ Iz bašánskih hrastov so naredili tvoja vesla; skupina Ašhúrcev je naredila tvoje klopi iz slonovine, pripeljane iz kitéjskih otokov.',
        7: 'Tanko laneno platno z izvezenim delom iz Egipta je bilo to, kar si razširjala, da bi bilo tvoje jadro; modro in vijolično z otokov Elišája, je bilo to, kar te je pokrivalo.',
        8: 'Prebivalci Sidóna in Arváda so bili tvoji mornarji. Tvoji modri možje, oh Tir, ki so bili v tebi, so bili tvoji krmarji.',
        9: 'Gebálski starci in njegovi modri možje so bili v tebi tvoji popravljavci razpok. Vse morske ladje s svojimi mornarji so bile v tebi, da so prekupčevali tvoje trgovsko blago.',
        10: 'Tisti iz Perzije in iz Luda in iz Puta so bili v tvoji vojski, tvoji bojevniki. V tebi so obešali ščit in čelado; oni kažejo tvojo ljubkost.',
        11: 'Možje Arváda, s tvojo vojsko, so bili na tvojih zidovih naokoli in Gamádci so bili v tvojih stolpih. Svoje ščite so obešali naokoli po tvojih zidovih; tvojo lepoto so naredili popolno.',
        12: 'Taršíš je bil tvoj trgovec zaradi razloga množice vseh vrst bogastev; s srebrom, železom, kositrom in svincem so trgovali na tvojih sejmih.',
        13: 'Javán, Tubál in Mešeh so bili tvoji trgovci. Trgovali so s človeškimi osebami in posodami iz brona na tvojem trgu.',
        14: 'Tisti iz hiše Togarmá so na tvojih sejmih trgovali s konji, konjeniki in mulami.',
        15: 'Možje iz Dedána so bili tvoji trgovci, številni otoki so bili trgovsko blago tvoje roke, za darilo so ti prinašali rogove iz slonovine in ebenovino.',
        16: '§ Sirija je bila tvoj trgovski partner zaradi razloga množičnosti stvari tvoje izdelave. Na tvojih sejmih so se zaposlovali s smaragdi, vijoličnim in izvezenim delom in tankim lanenim platnom in koraldo in ahatom.',
        17: 'Juda in Izraelova dežela so bili tvoji trgovci. Trgovali so na tvojem trgu s pšenico iz Miníta in Pannago in medom, oljem in balzamom.',
        18: 'Damask je bil tvoj trgovski partner v množici stvari tvoje izdelave zaradi množice vseh bogastev; z vinom iz Helbóna in belo volno.',
        19: 'Tudi Dán in Javán, ki sta šla sem ter tja, sta se zaposlovala na tvojih sejmih. Svetlo železo, kasija in kolmež so bili na tvojem trgu.',
        20: 'Dedán je bil tvoj trgovec v dragocenih oblačilih za bojne vozove.',
        21: 'Arabija in vsi princi Kedárja so se zaposlovali s teboj z jagnjeti, ovni in kozli; v teh so bili oni tvoji trgovci.',
        22: 'Trgovci iz Sabe in Ramája, oni so bili tvoji trgovci. Zaposlovali so se na tvojih sejmih z glavnino izmed vseh dišav in z vsemi dragocenimi kamni in z zlatom.',
        23: 'Harán in Kané in Eden, trgovci iz Sabe, Asúrja in Kilmáda so bili tvoji trgovci.',
        24: '§ To so bili tvoji trgovci v vseh vrstah stvari, v modrih oblačilih in izvezenem delu in v skrinjah bogatega videza, povezanih z vrvicami in narejenimi iz cedre, med tvojim trgovanjem.',
        25: 'Ladje iz Taršíša so pele o tebi na tvojem trgu in ti si bil na novo napolnjen in zelo veličastno narejen v sredi morij.',
        26: 'Tvoji veslači so te privedli v velike vode. Vzhodni veter te je zlomil v sredi morij.',
        27: 'Tvoja bogastva, tvoji sejmi, tvoji trgovci, tvoji mornarji in tvoji krmarji, tvoji popravljavci razpok, zaposlovalci tvojega trgovanja in vsi tvoji bojevniki, ki so v tebi in v vsej tvoji skupini, ki je v tvoji sredi, bodo padli v sredo morij na dan tvojega propada.',
        28: 'Predmestja se bodo tresla ob zvoku krika tvojih krmarjev.',
        29: 'In vsi, ki prijemajo veslo, mornarji in vsi krmarji morja bodo prišli dol iz svojih ladij, stali bodo na kopnem;',
        30: 'in svojemu glasu bodo povzročili, da bo slišan zoper tebe in grenko bodo jokali in metali prah na svoje glave in se valjali v pepelu,',
        31: 'in zate se bodo naredili popolnoma plešaste in se prepasali z vrečevino in jokali bodo zaradi tebe s srčno grenkobo in grenko tarnali.',
        32: 'In v svojem tarnanju bodo vzdignili žalostinko za teboj in žalovali nad teboj, rekoč: ›Katero mesto je podobno Tiru, podobno uničenemu v sredi morja?',
        33: 'Ko so tvoje stvari šle naprej iz morij, si sitil mnoga ljudstva, kralje zemlje si obogatil z množico svojih bogastev in od svojega trgovanja.',
        34: '§ V času, ko boš zlomljen z morji, v globinah voda, bo tvoje trgovsko blago in vsa tvoja druščina padla v tvoji sredi.',
        35: 'Vsi prebivalci otokov bodo osupli nad teboj in njihovi kralji bodo boleče prestrašeni, vznemirjeni bodo na svojem obličju.',
        36: 'Trgovci med ljudstvom bodo sikali nad teboj; strahota boš in nikoli več te ne bo.‹«',
    },
    28: {
        1: 'Beseda Gospodova je ponovno prišla k meni, rekoč:',
        2: '»Človeški sin, povej princu Tira: ›Tako govori Gospod Bog: ›Ker je tvoje srce povzdignjeno in si rekel: ›Jaz sem Bog, sedim na Božjem sedežu v sredi morij;‹ vendar si človek in ne Bog, čeprav si svoje srce postavljal kakor srce Boga.',
        3: 'Glej, modrejši si kakor Daniel; ni skrivnosti, ki jo lahko skrijejo pred teboj.',
        4: 'S svojo modrostjo in s svojim razumevanjem si si pridobil bogastva in v svojih zakladnicah si si pridobil zlato in srebro.',
        5: 'S svojo veliko modrostjo in s svojim preprodajanjem si povečal svoja bogastva in tvoje srce je povzdignjeno zaradi tvojih bogastev.‹',
        6: 'Zato tako govori Gospod Bog: ›Ker si svoje srce postavil kakor srce Boga;',
        7: 'glej, zato bom nadte privedel tujce, strašne izmed narodov. Svoje meče bodo izvlekli zoper lepoto tvoje modrosti in omadeževali bodo tvoj sijaj.',
        8: 'Privedli te bodo dol do jame in umrl boš [s] smrtmi tistih, ki so umorjeni v sredi morij.',
        9: 'Ali boš še govoril pred tistim, ki te ubija: ›Jaz sem Bog?‹ Toda ti boš mož in ne Bog, v roki tistega, ki te ubija.',
        10: 'Umrl boš s smrtmi neobrezancev, po roki tujcev, kajti jaz sem to govoril,‹ govori Gospod Bog.«',
        11: 'Poleg tega je prišla k meni Gospodova beseda, rekoč:',
        12: '»Človeški sin, vzdigni žalostinko nad kraljem Tira in mu reci: ›Tako govori Gospod Bog: ›Ti pečatiš vsoto, poln si modrosti in popoln v lepoti.',
        13: 'Bil si v Raju, Božjem vrtu; vsak dragocen kamen je bil tvoje pokrivalo: sardij, topaz in diamant, beril, oniks in jaspis, safir, smaragd, granat in zlato. Izdelava tvojih bobničev in tvojih piščali je bila pripravljena v tebi na dan, ko si bil ustvarjen.',
        14: 'Ti si maziljen kerub, ki zaslanja; in jaz sem te tako postavil. Bil si na sveti gori Boga; hodil si gor in dol v sredi ognjenih kamnov.',
        15: 'Bil si popoln na svojih poteh, od dneva, ko si bil ustvarjen, dokler ni bila v tebi najdena krivičnost.',
        16: 'Z množico tvojih trgovanj so tvojo sredo napolnili z nasiljem in si grešil, zato te bom pahnil, kot oskrunjenega iz Božje gore in te bom uničil, oh zaslanjajoči kerub, iz srede ognjenih kamnov.',
        17: 'Tvoje srce se je povzdignilo zaradi tvoje lepote, svojo modrost si izpridil zaradi svojega sijaja. Jaz te bom vrgel na tla, jaz te bom položil pred kralje, da te bodo lahko gledali.',
        18: 'Svoja svetišča si omadeževal z množico svojih krivičnosti, s krivičnostjo svojega preprodajanja; zato bom privedel ogenj iz tvoje srede; ta te bo požrl, jaz pa te bom spremenil v pepel na zemlji, pred očmi vseh tistih, ki te gledajo.',
        19: 'In tisti, ki te med ljudstvom poznajo, bodo osupli nad teboj. Strahota boš in nikoli te ne bo več.‹«',
        20: 'Ponovno je prišla k meni Gospodova beseda, rekoč:',
        21: '»Človeški sin, naravnaj svoj obraz proti Sidónu in prerokuj zoper njega',
        22: 'ter reci: ›Tako govori Gospod Bog: ›Glej, zoper tebe sem, oh Sidón; in proslavljen bom v tvoji sredi in vedeli bodo, da jaz sem Gospod, ko bom izvršil sodbe v njem in bom posvečen v njem.',
        23: 'Kajti vanj bom poslal kužno bolezen in kri na njegove ulice; in ranjeni bodo sojeni v njegovi sredi z mečem na njem, na vsaki strani; in spoznali bodo, da jaz sem Gospod.',
        24: 'In ne bo več bodečega osata nad Izraelovo hišo niti kakršnegakoli bolečega trna od vseh, ki so okoli njih, ki so jih prezirali; in spoznali bodo, da jaz sem Gospod Bog.‹',
        25: 'Tako govori Gospod Bog: ›Ko bom Izraelovo hišo zbral izmed ljudstev, med katere so razkropljeni in bom posvečen v njih v očeh poganov, potem bodo prebivali v svoji deželi, ki sem jo dal svojemu služabniku Jakobu.',
        26: 'In v njej bodo varno prebivali in gradili bodo hiše in sadili vinograde; da, prebivali bodo z zaupanjem, ko izvršim sodbe nad vsemi tistimi, ki jih prezirajo naokoli njih; in spoznali bodo, da jaz sem Gospod, njihov Bog.‹«',
    },
    29: {
        1: 'V desetem letu, v desetem mesecu, na dvanajsti dan meseca je prišla k meni Gospodova beseda, rekoč:',
        2: '»Človeški sin, naravnaj svoj obraz proti faraonu, egiptovskemu kralju in prerokuj zoper njega in zoper ves Egipt.',
        3: 'Govori in reci: ›Tako govori Gospod Bog: ›Glej, jaz sem zoper tebe, faraon, egiptovski kralj, veliki zmaj, ki ležiš v sredi svojih rek, ki praviš: ›Moja reka je moja lastna in naredil sem jo zase.‹',
        4: 'Toda dal ti bom kavlje v čeljusti in ribam tvojih rek bom povzročil, da se prilepijo na tvoje luskine in izvlekel te bom iz srede tvojih rek in vse ribe tvojih rek se bodo prilepile na tvoje luskine.',
        5: 'In pustil te bom vreči v divjino, tebe in vse ribe tvojih rek. Padel boš na odprta polja; ne boš zbližan niti ne zbran. Dal sem te za hrano poljskim živalim in perjadi neba.',
        6: 'In vsi prebivalci Egipta bodo spoznali, da jaz sem Gospod, ker so bili trstična palica za Izraelovo hišo.‹',
        7: 'Kadar so te prijeli za tvojo roko, si se zlomil in raztrgal vso njihovo ramo, in ko so se oprli nate, si se zlomil in storil, da vsa njihova ledja odrevenijo.‹',
        8: 'Zato tako govori Gospod Bog: ›Glej, nadte bom privedel meč in iz tebe iztrebil človeka in žival.',
        9: 'In egiptovska dežela bo zapuščena in opustošena; in spoznali bodo, da jaz sem Gospod, ker je rekel: ›Reka je moja in jaz sem jo naredil.‹',
        10: 'Glej, zato sem zoper tebe in zoper tvoje reke in egiptovsko deželo bom naredil popolnoma opustošeno in zapuščeno od Siénskega stolpa celó do meje Etiopije.',
        11: 'Skoznjo ne bo šlo nobeno človeško stopalo niti ne bo šlo skozi živalsko stopalo niti štirideset let ne bo naseljena.',
        12: 'In egiptovsko deželo bom naredil zapuščeno v sredi pokrajin, ki so zapuščene in njena mesta, med mesti, ki so opustošena, bodo zapuščena štirideset let in Egipčane bom razkropil med narode in jih razpodil po pokrajinah.‹',
        13: 'Vendar tako govori Gospod Bog: ›Ob koncu štiridesetih let bom zbral Egipčane izmed ljudstev, kamor so bili razkropljeni,',
        14: 'in ponovno bom privedel ujetništvo Egipta in povzročil jim bom, da se vrnejo v deželo Patrós, v deželo svojega prebivališča; in tam bodo nizko kraljestvo.',
        15: 'To bo najnižje izmed kraljestev niti se ne bo več povzdigovalo nad narodi, kajti jaz jih bom zmanjšal, da ne bodo več vladali nad narodi.',
        16: 'In le-to ne bo več zaupanje Izraelove hiše, ki v spomin prinaša njihovo krivičnost, ko bodo gledali za njimi, toda spoznali bodo, da jaz sem Gospod Bog.‹«',
        17: 'Pripetilo se je v sedemindvajsetem letu, v prvem mesecu, na prvi dan meseca, [da] je prišla k meni Gospodova beseda, rekoč:',
        18: '»Človeški sin, babilonski kralj Nebukadnezar je svoji vojski storil, da služi sijajno službo zoper Tir. Vsaka glava je bila narejena plešasto in vsaka rama je bila oluščena, vendar ni imel nobenih plačil niti njegova vojska za Tir, za službo, ki jo je opravil zoper njega.',
        19: 'Zato tako govori Gospod Bog: ›Glej, egiptovsko deželo bom dal Nebukadnezarju, babilonskemu kralju; in on bo zajel njeno množico in vzel njeno ukradeno blago in vzel njen plen; in to bodo plačila za njegovo vojsko.',
        20: 'Izročil sem mu egiptovsko deželo za njegov trud, s katerim je služil zoper njo, ker so delali zame,‹ govori Gospod Bog.',
        21: '›Na tisti dan bom rogu Izraelove hiše povzročil, da vzbrsti in jaz ti bom dal odprtje ust v njihovi sredi, in spoznali bodo, da jaz sem Gospod.‹«',
    },
    30: {
        1: 'Beseda Gospodova je ponovno prišla k meni, rekoč:',
        2: '»Človeški sin, prerokuj in reci: ›Tako govori Gospod Bog: ›Tulite: ›Dan, vreden gorja!‹‹',
        3: 'Kajti dan je blizu, celo Gospodov dan je blizu, oblačen dan; to bo čas poganov.',
        4: 'Meč bo prišel nad Egipt in velika bolečina bo v Etiopiji, ko bodo umorjeni padli v Egiptu in bodo proč odpeljali njegovo množico in njegovi temelji bodo zrušeni.',
        5: '§ Etiopija, Libija in Ludéja in vsa pomešana ljudstva in Kub in možje dežele, ki je v zavezi, bodo z njimi padli pod mečem.‹',
        6: 'Tako govori Gospod: ›Tudi tisti, ki podpirajo Egipt, bodo padli; in ponos njegove oblasti se bo zrušil. Od siénskega stolpa bodo v njem padli pod mečem,‹ govori Gospod Bog.',
        7: '›In opustošeni bodo v sredi dežel, ki so opustošene in njegova mesta bodo v sredi mest, ki so opustošena.',
        8: 'In spoznali bodo, da jaz sem Gospod, ko sem dal ogenj v Egipt in ko bodo vsi njegovi pomočniki uničeni.',
        9: 'Na tisti dan bodo poslanci šli pred menoj na ladjah, da prestrašijo brezskrbne Etiopijce in velika bolečina bo prišla nadnje kakor na dan Egipta, kajti, glej, ta prihaja.‹',
        10: 'Tako govori Gospod Bog: ›Tudi egiptovski množici bom storil, da odneha po roki babilonskega kralja Nebukadnezarja.',
        11: 'On in njegovo ljudstvo z njim, strašni izmed narodov, bodo privedeni, da uničijo deželo in svoje meče bodo izvlekli zoper Egipt in deželo napolnili z umorjenimi.',
        12: '§ Posušil bom reke in deželo prodal v roko zlobnega, in deželo in vse, kar je v njej, bom naredil opustošenje po roki tujcev. Jaz, Gospod sem to govoril.‹',
        13: 'Tako govori Gospod Bog: ›Prav tako bom uničil malike in njihovim podobam bom povzročil, da bodo izginile iz Nofa; in tam ne bo nič več princa iz egiptovske dežele, in na egiptovsko deželo bom položil strah.',
        14: 'Patrós bom naredil zapuščen in prižgal bom ogenj na Coanu in izvršil bom sodbe v Noju.',
        15: 'In svojo razjarjenost bom izlil nad Sin, moč Egipta; in iztrebil bom množico iz Noja.',
        16: 'Zanetil bom ogenj v Egiptu. Sin bo imel veliko bolečino in No bo raztrgan in Nof bo imel dnevne tegobe.',
        17: 'Mladeniči iz Avena in iz Pi Beseta bodo padli pod mečem, in ta mesta bodo šla v ujetništvo.',
        18: 'Tudi v Tahpanhésu bo dan otemnel, ko bom tam zlomil egiptovske jarme, in pomp njegove moči bo prenehal v njem. Kar se tiče njega, oblak ga bo pokril in njegove hčere bodo šle v ujetništvo.',
        19: 'Tako bom izvršil sodbe v Egiptu, in spoznali bodo, da jaz sem Gospod.‹«',
        20: 'In pripetilo se je v enajstem letu, v prvem mesecu, na sedmi dan meseca, da je prišla k meni Gospodova beseda, rekoč:',
        21: '»Človeški sin zlomil sem laket faraonu, egiptovskemu kralju; in glej, ta ne bo obvezan, da bi bil ozdravljen, da položi povoj, da ga poveže, da ga naredi močnega za držanje meča.',
        22: 'Zato tako govori Gospod Bog: ›Glej jaz sem zoper faraona, egiptovskega kralja in zlomil bom njegova lakta, zdravega in tistega, ki je bil zlomljen; in storil bom, da iz njegove roke pade meč.',
        23: 'Egipčane bom razkropil med narode in jih razpodil po deželah.',
        24: 'Okrepil pa bom lakte babilonskega kralja in v njegovo roko položim svoj meč. Toda faraonova lakta bom zlomil in pred njim bo stokal s stokanjem smrtno ranjenega moža.',
        25: 'Toda okrepil bom lakta babilonskega kralja, faraonova lakta pa bosta upadla in spoznali bodo, da jaz sem Gospod, ko bom svoj meč položil v roko babilonskega kralja in iztegnil ga bo nad egiptovsko deželo.',
        26: 'In Egipčane bom razkropil med narode in jih razpodil med dežele; in spoznali bodo, da jaz sem Gospod.‹«',
    },
    31: {
        1: 'In pripetilo se je v enajstem letu, v tretjem mesecu, na prvi dan meseca, da je prišla k meni Gospodova beseda, rekoč:',
        2: '»Človeški sin, spregovori faraonu, egiptovskemu kralju in njegovi množici: ›Komu si podoben v svoji veličini?',
        3: 'Glej, Asirec je bil cedra na Libanonu, z lepimi mladikami in s senčnato kopreno in visoke rasti; in njegov vrh je bil med debelimi vejami.',
        4: 'Vode so ga naredile velikega, globina ga je s svojimi rekami, ki tečejo naokoli njegovih rastlin, postavila gor na višavo in pošiljala ven svoje majhne reke do vseh poljskih dreves.',
        5: 'Zatorej je bila njegova višina povišana nad vsa poljska drevesa in njegove veje so bile pomnožene in njegove mladike so postale dolge zaradi obilice voda, ko je poganjal.',
        6: 'Vsa perjad neba je naredila svoja gnezda v njegovih vejah in pod njegovimi mladikami so vse živali polja kotile svoje mlade in pod njegovo senco so prebivali vsi veliki narodi.',
        7: 'Tako je bil lep v svoji veličini, v dolžini svojih mladik, kajti njegova korenina je bila ob velikih vodah.',
        8: 'Cedre v Božjem vrtu ga niso mogle skriti. Ciprese niso bile podobne njegovim vejam in kostanjeva drevesa niso bila podobna njegovim mladikam; niti katerokoli drevo v Božjem vrtu ni bilo podobno njemu v njegovi lepoti.',
        9: 'Naredil sem ga lepega z množico njegovih mladik, tako da so mu vsa edenska drevesa, ki so bila v Božjem vrtu, zavidala.‹',
        10: 'Zato tako govori Gospod Bog: ›Ker si se povzdigoval na višino in je svoj vrh poganjal med debelimi vejami in je njegovo srce povzdignjeno na njegovo višino;',
        11: 'zato sem ga izročil v roko mogočnega izmed poganov; zagotovo bo obračunal z njim. Ven sem ga izgnal zaradi njegove zlobnosti.',
        12: 'In tujci, strašni izmed narodov, so ga odrezali in ga zapustili. Po gorah in po vseh dolinah so padle njegove mladike in njegove veje so zlomljene ob vseh rekah dežele; in vsa ljudstva zemlje so šla dol iz njegove sence in ga zapustila.',
        13: 'Na njegovem uničenju bo ostala vsa perjad neba in vse živali polja bodo na njegovih mladikah,',
        14: 'z namenom, da se nobeno izmed vseh dreves ob vodah ne bo povzdigovalo zaradi svoje višine niti svojega vrha poganjalo med debele veje niti ne bodo njihova drevesa stala na njihovi višini, vsa, ki pijejo vodo, kajti vsa so izročena smrti, k spodnjim delom zemlje, v sredo človeških otrok, s tistimi, ki gredo dol k jami.‹',
        15: 'Tako govori Gospod Bog: ›Na dan, ko je šel dol do groba, sem povzročil žalovanje. Zanj sem pokril globino in omejil njegove tokove in velike vode so bile ustavljene. Libanonu sem storil, da je žaloval za njim in vsa poljska drevesa so medlela zaradi njega.',
        16: 'Narodom sem storil, da se tresejo ob zvoku njegovega padca, ko sem ga vrgel dol do pekla, s tistimi, ki se spuščajo v jamo in vsa edenska drevesa, izbrana in najboljša iz Libanona, vsa, ki pijejo vodo, bodo potolažena v spodnjih delih zemlje.',
        17: 'Tudi oni so z njim odšli dol v pekel, k tistim, ki so umorjeni z mečem; in tisti, ki so bili njegov laket, ki so prebivali pod njegovo senco v sredi narodov.',
        18: 'Komu si ti tako podoben v slavi in v veličini med edenskimi drevesi? Vendar boš z edenskimi drevesi priveden dol v spodnje dele zemlje. Ležal boš v sredi neobrezancev, s tistimi, ki so umorjeni z mečem. To je faraon in vsa njegova množica,‹ govori Gospod Bog.‹«',
    },
    32: {
        1: 'In pripetilo se je v dvanajstem letu, v dvanajstem mesecu, na prvi dan meseca, da je prišla k meni Gospodova beseda, rekoč:',
        2: '»Človeški sin, vzdigni žalostinko za faraonom, egiptovskim kraljem in mu reci: ›Podoben si mlademu levu izmed narodov in ti si kakor kit v morjih in prihajaš naprej s svojimi rekami in s svojimi stopali burkaš vode in usmrajuješ njihove reke.‹',
        3: 'Tako govori Gospod Bog: ›Zato bom nad teboj razprostrl svojo mrežo s spremstvom mnogih ljudstev; in privedli te bodo gor v mojo mrežo.',
        4: 'Potem te bom pustil na deželi, vrgel te bom naprej na odprto polje in vsej perjadi neba bom povzročil, da ostanejo na tebi in s teboj bom nasitil živali celotne zemlje.',
        5: 'In tvoje meso bom položil na gore in s tvojo višino napolnil doline.',
        6: 'Tudi s tvojo krvjo bom namočil deželo, v kateri plavaš, celó do gora; in reke te bodo polne.',
        7: 'Ko te bom ugasnil, bom pokril nebo in zatemnil zvezde; sonce bom pokril z oblakom in luna ne bo dajala svoje svetlobe.',
        8: 'Vse svetle luči neba nad teboj bom otemnil in postavil temo nad tvojo deželo,‹ govori Gospod Bog.',
        9: 'Prav tako bom dražil srca mnogih ljudi, ko bom med narode privedel tvoje uničenje, v dežele, ki jih nisi poznal.',
        10: 'Da, naredil bom, da bodo mnoga ljudstva osupla nad teboj in njihovi kralji bodo strašno prestrašeni zaradi tebe, ko bom pred njimi vihtel svoj meč; in trepetali bodo ob vsakem trenutku, vsak človek za svoje lastno življenje, na dan tvojega padca.‹',
        11: 'Kajti tako govori Gospod Bog: ›Meč babilonskega kralja bo prišel nadte.',
        12: 'Z meči mogočnega bom tvoji množici povzročil, da pade, strašni izmed narodov, vsi izmed njih, in oplenili bodo pomp Egipta in vsa njegova množica bo uničena.',
        13: 'Prav tako bom uničil tudi vse njegove živali, ki so poleg velikih vodá. Niti jih ne bo več vznemirjalo človeško stopalo niti jih ne bodo vznemirjala kopita živine.',
        14: 'Potem bom njihove vode naredil globoke in njihovim rekam povzročil, da tečejo kakor olje,‹ govori Gospod Bog.',
        15: '›Ko bom egiptovsko deželo naredil zapuščeno in bo dežela oropana tega, česar je bila polna, ko bom udaril vse tiste, ki prebivajo tam, takrat bodo vedeli, da jaz sem Gospod.',
        16: 'To je žalostinka, s katero ga bodo objokovali. Hčere narodov ga bodo objokovale. Žalovali bodo za njim, celó za Egiptom in za vso njegovo množico,‹ govori Gospod Bog.‹«',
        17: 'In prav tako se je pripetilo v dvanajstem letu, na petnajsti dan meseca, da je k meni prišla Gospodova beseda, rekoč:',
        18: '»Človeški sin, tarnaj za egiptovsko množico in vrzi jo dol, celó njo in hčere slavnih narodov, v spodnje dele zemlje, s tistimi, ki gredo dol v jamo.',
        19: 'Koga prekašaš v lepoti? Pojdi dol in bodi položen z neobrezanimi.',
        20: 'Padli bodo v sredo tistih, ki so umorjeni z mečem. Izročen je meču. Potegni njega in vse njegove množice.',
        21: 'Močni izmed mogočnih mu bodo govorili iz srede pekla s tistimi, ki mu pomagajo. Odšli so dol, ležijo neobrezani, umorjeni z mečem.',
        22: 'Tam je Asúr in vse njegovo spremstvo. Njegovi grobovi so okoli njega, vsi izmed njih umorjeni, padli pod mečem,',
        23: 'katerih grobovi so postavljeni ob straneh jame in njegovo spremstvo je naokoli njegovega groba; vsi izmed njih umorjeni, padli pod mečem, ki so povzročili strahoto v deželi živih.',
        24: 'Tam je Elám in vsa njegova množica naokoli njegovega groba, vsi izmed njih umorjeni, padli pod mečem, ki so neobrezani odšli dol, v spodnje dele zemlje, ki so povzročili njihovo strahoto v deželi živih; vendar so nosili svojo sramoto s tistimi, ki gredo dol v jamo.',
        25: 'Pripravili so mu posteljo v sredi umorjenih, z vso njegovo množico. Njegovi grobovi so okoli njega; vsi izmed njih neobrezani, umorjeni z mečem. Čeprav je bila njihova strahota storjena v deželi živih, so vendar nosili svojo sramoto s tistimi, ki gredo dol v jamo. Položen je v sredo tistih, ki so umorjeni.',
        26: 'Tam je Mešeh, Tubál in vsa njegova množica. Njegovi grobovi so okoli njega; vsi izmed njih neobrezani, umorjeni z mečem, četudi so svojo strahoto povzročali v deželi živih.',
        27: 'Ne bodo ležali z mogočnimi, ki so padli od neobrezancev, ki so odšli dol k peklu z njihovimi bojnimi orožji. Njihove meče so položili pod njihove glave, toda njihove krivičnosti bodo na njihovih kosteh, čeprav so bili strahota mogočnih v deželi živih.',
        28: 'Da, zlomljen boš v sredi neobrezancev in ležal boš s tistimi, ki so umorjeni z mečem.',
        29: 'Tam je Edóm, njegovi kralji in vsi njegovi princi, ki so s svojo močjo položeni od tistih, ki so bili umorjeni z mečem. Ležali bodo z neobrezanimi in s tistimi, ki gredo dol v jamo.',
        30: 'Tam bodo princi iz severa, vsi izmed njih in vsi Sidónci, ki so odšli dol z umorjenimi; s svojo strahoto se sramujejo svoje moči; in ležijo neobrezani, s tistimi, ki so umorjeni z mečem in svojo sramoto nosijo s tistimi, ki gredo dol v jamo.',
        31: 'Faraon jih bo videl in potolažen bo nad vso svojo množico, celó faraon in vsa njegova vojska, umorjena z mečem,‹ govori Gospod Bog.',
        32: '›Kajti povzročil sem svojo strahoto v deželi živih in položen bo v sredo neobrezancev, s tistimi, ki so umorjeni z mečem, celó faraon in vsa njegova množica,‹ govori Gospod Bog.‹«',
    },
    33: {
        1: 'Ponovno je prišla k meni Gospodova beseda, rekoč:',
        2: '»Človeški sin, spregovori otrokom svojega ljudstva in jim reci: ›Ko privedem meč nad deželo, če ljudstvo dežele vzame človeka iz svojih obal in ga postavi za svojega stražarja.',
        3: 'Če ta zatrobi na šofar in posvari ljudstvo, kadar vidi nad deželo prihajati meč;',
        4: 'potem kdorkoli sliši zvok šofarja in ne sprejme svarila; če pride meč in ga vzame, bo njegova kri na njegovi lastni glavi.',
        5: 'Slišal je zvok šofarja in ni sprejel svarila; njegova kri bo nad njim. Toda kdor sprejme svarilo, bo rešil svojo dušo.',
        6: 'Toda če stražar vidi prihajati meč, pa ne zatrobi na šofar in ljudstvo ni posvarjeno, če pride meč in vzame kateregakoli človeka izmed njih, je ta odvzet v svoji krivičnosti; toda njegovo kri bom zahteval iz stražarjeve roke.',
        7: 'Tako sem tebe, oh človeški sin, postavil [za] stražarja Izraelovi hiši; zato boš slišal besedo pri mojih ustih in jih posvaril v mojem imenu.',
        8: 'Ko rečem zlobnemu: ›Oh zlobni človek, zagotovo boš umrl;‹ če ne spregovoriš, da zlobnega posvariš pred njegovo potjo, bo ta zloben človek umrl v svoji krivičnosti, toda njegovo kri bom zahteval pri tvoji roki.',
        9: 'Vendar če posvariš zlobnega o njegovi poti, da se odvrne od nje; če se ta ne odvrne iz svoje poti, bo umrl v svoji krivičnosti; toda ti si rešil svojo dušo.',
        10: 'Zato, oh ti, človeški sin, spregovori Izraelovi hiši: ›Tako govorite, rekoč: ›Če so naši prestopki in naši grehi nad nami in v njih hiramo, kako bi potem živeli?‹',
        11: 'Reci jim: › Kakor jaz živim,‹ govori Gospod Bog, ›nobenega zadovoljstva nimam v smrti zlobnega; temveč, da se zlobni odvrne od svoje poti in živi. Obrnite se, obrnite se od svojih zlih poti; kajti zakaj hočete umreti, oh hiša Izraelova?‹',
        12: 'Zato ti, človeški sin, reci otrokom svojega ljudstva: ›Pravičnost pravičnega ga ne bo rešila na dan njegovega prestopka. Glede zlobnosti zlobnega, on s tem ne bo padel na dan, ko se obrne od svoje zlobnosti; niti pravični ne bo zmožen živeti po svoji pravičnosti na dan, ko greši.',
        13: 'Ko bom rekel pravičnemu, da bo zagotovo živel; če ta zaupa svoji lastni pravičnosti in zagreši krivičnost, se vse njegove pravičnosti ne bo spominjalo; toda zaradi svoje krivičnosti, ki jo je zagrešil, bo zaradi nje umrl.‹',
        14: 'Ponovno, kadar rečem zlobnemu: ›Ti boš zagotovo umrl;‹ če se ta obrne od svojega greha in dela to, kar je zakonito in pravilno;',
        15: 'če zlobni povrne jamstvo, ponovno da, kar je naropal, se ravna po zakonih življenja, ne da bi zagrešil krivičnost; zagotovo bo živel, ne bo umrl.',
        16: 'Nobeden izmed njegovih grehov, ki jih je zagrešil, mu ne bo omenjen. Storil je to, kar je zakonito in pravilno; zagotovo bo živel.‹',
        17: 'Vendar otroci tvojega ljudstva pravijo: ›Gospodova pot ni enakovredna.‹ Toda kar se tiče njih, njihova pot ni enakovredna.',
        18: 'Ko se pravični obrne od svoje pravičnosti in grešno zagreši krivičnost, bo s tem torej umrl.',
        19: 'Toda če se zlobni odvrne od svoje zlobnosti in počne to, kar je zakonito in pravilno, bo s tem živel.',
        20: 'Vendar vi pravite: ›Gospodova pot ni enakovredna.‹ Oh vi, hiša Izraelova, vsakogar bom sodil po njegovih poteh.‹«',
        21: 'In pripetilo se je v dvanajstem letu našega ujetništva, v desetem mesecu, na peti dan meseca, da je tisti, ki je pobegnil iz [prestolnice] Jeruzalem, prišel k meni, rekoč: »Mesto je udarjeno.«',
        22: 'Torej Gospodova roka je bila nad menoj zvečer, prej, preden je prišel ta, ki je pobegnil. Odprl je moja usta, dokler ni oni zjutraj prišel k meni; in moja usta so bila odprta in nisem bil več nem.',
        23: 'Potem je prišla k meni Gospodova beseda, rekoč:',
        24: '»Človeški sin, tisti, ki poseljujejo opustošenosti dežele Izrael, govorijo, rekoč: ›Abraham je bil en in je podedoval deželo, toda nas je mnogo. Dežela nam je dana v dediščino.‹',
        25: 'Zato jim reci: ›Tako govori Gospod Bog: ›Vi jeste s krvjo in svoje oči povzdigujete k svojim malikom in prelivate kri; in ali boste vzeli v last deželo?',
        26: 'Stojite na svojem meču, počnete ogabnost in omadežujete, vsak ženo svojega soseda; in ali boste vzeli v last deželo?‹',
        27: 'Tako jim reci: ›Tako govori Gospod Bog: › Kakor jaz živim, zagotovo bodo tisti, ki so v opustošenostih, padli pod mečem in kdor je na odprtem polju, ga bom izročil živalim, da bo požrt in tisti, ki so v utrdbah in votlinah, bodo umrli od kužne bolezni.',
        28: 'Kajti jaz bom deželo naredil najbolj zapuščeno in pomp njene moči bo prenehal; in gore Izraelove bodo zapuščene, da nihče ne bo šel čeznje.',
        29: 'Potem bodo vedeli, da jaz sem Gospod, ko sem deželo naredil najbolj zapuščeno zaradi vseh njihovih ogabnosti, ki so jih zagrešili.',
        30: 'Tudi ti, človeški sin, otroci tvojega ljudstva še vedno govorijo zoper tebe pri zidovih in v vratih hiš in drug drugemu govorijo, vsak svojemu bratu, rekoč: ›Pridi, prosim te in poslušaj, kakšna je beseda, ki prihaja od Gospoda.‹',
        31: 'In k tebi pridejo kakor prihajajo ljudje in sedijo pred teboj kakor moje ljudstvo in slišijo tvoje besede, toda nočejo jih izpolnjevati, kajti s svojimi usti so pokazali mnogo ljubezni, toda njihovo srce gre za njihovo pohlepnostjo.',
        32: 'In glej, ti si jim kakor zelo očarljiva pesem nekoga, ki ima prijeten glas in lahko dobro igra na glasbilo, kajti slišijo tvoje besede, toda po njih se ne ravnajo.',
        33: 'In ko se to zgodi (glej, to bo prišlo), potem bodo vedeli, da je bil med njimi prerok.‹«',
    },
    34: {
        1: 'In k meni je prišla Gospodova beseda, rekoč:',
        2: '»Človeški sin prerokuj proti Izraelovim pastirjem, prerokuj in jim reci: ›Tako govori Gospod Bog pastirjem: ›Gorje bodi Izraelovim pastirjem, ki pasejo same sebe! Ali naj ne bi pastirji pasli tropov?',
        3: 'Jeste tolščo in se oblačite z volno, koljete tiste, ki so rejeni, toda tropa ne pasete.',
        4: 'Bolnih niste krepili, niti niste zdravili tega, kar je bilo bolno, niti niste povezali tega, kar je bilo zlomljeno, niti niste ponovno privedli tega, kar je bilo odpeljano, niti niste iskali tega, kar je bilo izgubljeno; temveč ste jim vladali s silo in s krutostjo.',
        5: 'In bili so razkropljeni, ker tam ni pastirja. In ko so bili razkropljeni, so postali hrana vsem živalim polja.',
        6: 'Moje ovce so tavale po vseh gorah in na vsakem visokem hribu; da, moj trop je bil razkropljen po vsem obličju zemlje in nihče ni preiskoval ali iskal za njimi.‹',
        7: 'Zato, vi pastirji, poslušajte Gospodovo besedo:',
        8: '› Kakor jaz živim,‹ govori Gospod Bog, ›zagotovo, ker je moj trop postal plen in je moj trop postal hrana vsaki divji živali polja, ker tam ni bilo pastirja niti moji pastirji niso iskali za mojim tropom, temveč so pastirji pasli same sebe in niso pasli mojega tropa;',
        9: 'zato, oh vi pastirji, poslušajte Gospodovo besedo.',
        10: 'Tako govori Gospod Bog: ›Glejte, jaz sem proti pastirjem; in svoj trop bom zahteval iz njihove roke in jim povzročil, da prenehajo pasti trop; niti pastirji ne bodo več pasli same sebe; kajti svoj trop bom osvobodil iz njihovih ust, da ne bodo več hrana zanje.‹',
        11: 'Kajti tako govori Gospod Bog: ›Glejte, jaz, celó jaz, bom tako iskal svoje ovce kot jih poiskal.',
        12: 'Kakor pastir išče svoj trop na dan, ko je med svojimi ovcami, ki so razkropljene; tako bom poiskal svoje ovce in osvobodil jih bom iz vseh krajev, kamor so bile razkropljene na oblačen in temačen dan.',
        13: 'In jaz jih bom privedel izmed ljudstva in jih zbral izmed dežel in jih privedel k njihovi lastni deželi in jih pasel na Izraelovih gorah, poleg rek in po vseh naseljenih krajih dežele.',
        14: 'Pasel jih bom na dobrem pašniku in na visokih Izraelovih gorah bo njihova staja. Tam bodo ležale v dobri staji in pasle se bodo na obilnem pašniku na Izraelovih gorah.',
        15: 'Jaz bom pasel svoj trop in povzročil jim bom, da se uležejo,‹ govori Gospod Bog.',
        16: '›Iskal bom tisto, kar je bilo izgubljeno in ponovno privedel to, kar je bilo odvedeno stran in povezal bom to, kar je bilo zlomljeno in okrepil to, kar je bilo bolno. Toda uničil bom debelo in močno; jaz jih bom pasel s sodbo.',
        17: 'Glede vas pa, oh moj trop,‹ tako govori Gospod Bog: ›Glejte, jaz sodim med živino in živino, med ovni in kozli.',
        18: 'Ali se vam zdi majhna stvar, da ste pojedli dobro pašo, toda s svojimi stopali morate pomendrati preostanek svojih pašnikov? In da ste pili od globokih vodá, toda preostanek morate zapacati s svojimi stopali?',
        19: 'In glede mojega tropa, jedo to, kar ste poteptali s svojimi stopali, in pijejo to, kar ste zapacali s svojimi stopali.‹',
        20: 'Zato jim tako govori Gospod Bog: ›Glejte, jaz, celó jaz, bom sodil med debelo živino in med suho živino.',
        21: 'Ker ste odrivali s stranjo in z ramo in vse bolne porivali s svojimi rogovi, dokler jih niste razkropili na tuje;',
        22: 'zatorej bom rešil svoj trop in nič več ne bodo plen; in sodil bom med živino in živino.',
        23: 'In nadnje bom postavil enega pastirja in ta jih bo pasel, celó svojega služabnika Davida; pasel jih bo in on bo njihov pastir.',
        24: 'In jaz, Gospod, bom njihov Bog in moj služabnik David princ med njimi;‹ jaz, Gospod, sem to govoril.',
        25: '§ ›In z njimi bom sklenil zavezo miru in zlim živalim bom povzročil, da izginejo iz dežele; in tam bodo varno prebivali v divjini in spali v gozdovih.',
        26: 'In jaz bom naredil njih in kraje naokoli svojega hriba blagoslov; in nalivu bom povzročil, da pride dol v svojem obdobju; tam bodo nalivi blagoslova.',
        27: '§ In drevo polja bo obrodilo svoj sad in zemlja bo obrodila svoj donos in oni bodo varni v svoji deželi in spoznali bodo, da jaz sem Gospod, ko zlomim vezi njihovega jarma in jih osvobodim iz roke tistih, ki so si od njih dali streči.',
        28: 'In nič več ne bodo plen poganom niti jih ne bodo požrle kopenske živali; temveč bodo varno prebivali in nihče jih ne bo prestrašil.',
        29: 'In jaz bom zanje vzdignil ugleden nasad in ne bodo več použiti z lakoto v deželi niti ne bodo več nosili sramote poganov.',
        30: 'Tako bodo vedeli, da sem jaz, Gospod, njihov Bog, z njimi in da so oni, celó Izraelova hiša, moje ljudstvo,‹ govori Gospod Bog.',
        31: '›Vi pa, moj trop, trop mojega pašnika, ste ljudje in jaz sem vaš Bog,‹ govori Gospod Bog.‹«',
    },
    35: {
        1: 'Poleg tega je prišla k meni Gospodova beseda, rekoč:',
        2: '»Človeški sin, naravnaj svoj obraz proti gori Seír in prerokuj zoper njo',
        3: 'ter ji reci: ›Tako govori Gospod Bog: ›Glej, oh gora Seír, jaz sem zoper tebe in zoper tebe bom iztegnil svojo roko in naredil te bom najbolj zapuščeno.',
        4: 'Tvoja mesta bom opustošil in zapuščena boš in vedela boš, da jaz sem Gospod.',
        5: 'Ker si imela neprestano sovraštvo in si s silo meča prelila kri Izraelovih otrok v času njihove katastrofe, v času, ko je njihova krivičnost imela konec.',
        6: 'Zato kakor jaz živim,‹ govori Gospod Bog, ›te bom pripravil za kri in kri te bo zasledovala. Ker nisi sovražila krvi, te bo celo kri zasledovala.',
        7: 'Tako bom goro Seír naredil najbolj zapuščeno in iz nje iztrebil tistega, ki gre skozi in tistega, ki se vrača.',
        8: 'Njene gore bom napolnil z njenimi umorjenimi možmi. Na tvojih hribih in v tvojih dolinah in v vseh tvojih rekah bodo padli, ki so umorjeni z mečem.',
        9: 'Naredil te bom za neprestana opustošenja in tvoja mesta se ne bodo vrnila. In spoznali boste, da jaz sem Gospod.‹',
        10: 'Ker si rekla: ›Ta dva naroda in ti dve deželi bosta moji in mi bomo to vzeli v last; medtem ko je bil tam Gospod.',
        11: 'Zatorej, kakor jaz živim,‹ govori Gospod Bog, ›storil bom celo glede na tvojo jezo in glede na tvojo zavist, ki si jo uporabila iz svojega sovraštva zoper njih; in jaz se bom med njimi dal spoznati, ko sem te sodil.',
        12: 'Vedela boš, da jaz sem Gospod in da sem slišal vsa tvoja bogokletja, ki si jih govorila zoper Izraelove gore, rekoč: ›Zapuščene so, dane so nam, da jih použijemo.‹',
        13: 'Tako ste se s svojimi usti bahali zoper mene in pomnožili svoje besede zoper mene. Jaz sem jih slišal. ‹',
        14: 'Tako govori Gospod Bog: ›Ko se vsa zemlja razveseljuje, bom jaz tebe naredil zapuščeno.',
        15: 'Kakor si se ti razveseljeval ob dediščini Izraelove hiše, ker je bila zapuščena, tako bom jaz storil tebi. Zapuščena boš, oh gora Seír in ves Edóm, celó ves. In spoznali bodo, da jaz sem Gospod.‹«',
    },
    36: {
        1: '»Tudi ti, človeški sin, prerokuj Izraelovim goram in reci: ›Ve Izraelove gore, poslušajte Gospodovo besedo:',
        2: '›Tako govori Gospod Bog: ›Ker je sovražnik rekel proti vam: ›Aha, celo starodavni visoki kraji so naša posest;‹',
        3: 'zato prerokuj in reci: ›Tako govori Gospod Bog: ›Ker so vas naredili opustošene in vas požrli na vsaki strani, da bi lahko bile posest preostanku poganov in ste vzete na ustnice jezičnikov in ste razvpitost ljudstva.',
        4: 'Zato ve gore Izraelove, poslušajte besedo Gospoda Boga: ›Tako govori Gospod Bog goram in hribom, rekam in dolinam, pustim opustošenostim in mestom, ki so zapuščena, ki so postala plen in posmeh preostanku poganov, ki so naokoli;‹',
        5: 'zato tako govori Gospod Bog: ›Zagotovo sem govoril v ognju svoje ljubosumnosti zoper preostanek poganov in zoper ves Edóm, ki so mojo deželo določili v svojo posest z radostjo vsega svojega srca, s krutimi umi, da bi ga vrgli ven za plen.‹',
        6: 'Zato prerokuj glede dežele Izrael in reci goram in gričem, rekam in dolinam: ›Tako govori Gospod Bog: ›Glejte, govoril sem v svoji ljubosumnosti in v svoji razjarjenosti, ker ste nosili sramoto poganov.‹',
        7: 'Zato tako govori Gospod Bog: ›Povzdignil sem svojo roko: ›Zagotovo bodo pogani, ki so okoli vas, nosili svojo sramoto.‹',
        8: 'Toda ve, oh Izraelove gore, boste pognale svoje mladike in obrodile svoj sad mojemu ljudstvu Izraelu; kajti pri roki so, da pridejo.',
        9: 'Kajti, glejte, jaz sem za vas in obrnil se bom k vam in ve boste preorane in posejane,',
        10: 'in jaz bom pomnožil ljudi na vas, vso Izraelovo hišo, celó vse izmed njih, in mesta bodo naseljena in opustošenosti bodo pozidane,',
        11: 'in jaz bom na vas pomnožil človeka in žival; in narasli bodo in prinašali sad. In jaz vas bom naselil po vaših prejšnjih posestvih in vam bom storil boljše kakor ob vaših začetkih: in spoznale boste, da jaz sem Gospod.',
        12: 'Da, ljudem bom povzročil, da hodijo po vas, celó moje ljudstvo Izrael; in vzeli te bodo v last in boš njihova dediščina in odslej jih ne boš več oropala ljudi.‹',
        13: 'Tako govori Gospod Bog: ›Ker ti pravijo: ›Ti dežela, požiraš ljudi in si oropala svoje narode;‹',
        14: 'zatorej ne boš več požirala ljudi niti ne boš več oropala svojih narodov,‹ govori Gospod Bog.',
        15: '›Niti ne bom več povzročal ljudem, da v tebi slišijo sramoto poganov niti ne boš več nosila graje ljudstev niti ne boš več povzročala padca svojim narodom,‹ govori Gospod Bog.‹«',
        16: 'Poleg tega je prišla k meni Gospodova beseda, rekoč:',
        17: '»Človeški sin, ko je Izraelova hiša prebivala v svoji lastni deželi, so jo omadeževali s svojo lastno potjo in svojimi lastnimi početji. Njihova pot je bila pred menoj kakor nečistost odstranjene ženske.',
        18: 'Zatorej sem nanje izlil svojo razjarjenost zaradi krvi, ki so jo prelili nad deželo in zaradi njihovih malikov, s katerimi so jo oskrunili',
        19: 'in razgnal sem jih med pogane in razpršeni so bili med dežele; glede na njihovo pot in glede na njihova dejanja sem jih sodil.',
        20: 'In ko so vstopili k poganom, kamorkoli so odšli, so oskrunili moje sveto ime, ko so jim rekli: ›Ti so Gospodovo ljudstvo, pa so odšli ven iz njegove dežele.‹',
        21: 'Toda imel sem usmiljenje zaradi svojega svetega imena, ki ga je Izraelova hiša oskrunila med pogani, kamor so odšli.‹',
        22: 'Zato reci Izraelovi hiši: ›Tako govori Gospod Bog: › Tega ne delam zaradi tebe, oh hiša Izraelova, temveč zaradi svojega svetega imena, ki ste ga oskrunili med pogani, kamor ste odšli.',
        23: 'In jaz bom svoje veliko ime, ki je bilo oskrunjeno med pogani, ki ste ga oskrunili v njihovi sredi, posvetil; in pogani bodo spoznali, da jaz sem Gospod ‹, govori Gospod Bog, ›ko bom v vas posvečen, pred njihovimi očmi.',
        24: 'Kajti jaz vas bom vzel izmed poganov in vas zbral iz vseh dežel in vas privedel v vašo lastno deželo.',
        25: 'Potem bom na vas poškropil čisto vodo in boste čisti. Pred vso vašo umazanostjo in pred vsemi vašimi maliki vas bom očistil.',
        26: 'Prav tako vam bom dal novo srce in novega duha bom položil znotraj vas in iz vašega mesa bom odvzel kamnito srce in vam dal meseno srce.',
        27: 'Svojega duha bom položil znotraj vas in povzročim vam, da se boste ravnali po mojih zakonih in boste ohranjali moje sodbe in jih izvajali.',
        28: 'In prebivali boste v deželi, ki sem jo dal vašim očetom; in vi boste moje ljudstvo in jaz bom vaš Bog.',
        29: 'Prav tako vas bom rešil pred vašo nečistostjo, in jaz bom poklical žito in ga povečal, na vas pa ne bom položil nobene lakote.',
        30: 'In pomnožil bom sad od drevesa in donos od polja, da ne boste več prejeli graje zaradi lakote med pogani.',
        31: 'Potem se boste spomnili svojih lastnih zlih poti in svojih početij, ki niso bila dobra in gnusili se boste v svojih lastnih očeh zaradi svojih krivičnosti in zaradi svojih ogabnosti.',
        32: 'Tega ne storim zaradi vas,‹ govori Gospod Bog, ›to naj vam bo znano: bodite osramočeni in zbegani zaradi svojih lastnih poti, oh hiša Izraelova.‹',
        33: 'Tako govori Gospod Bog: ›Na dan, ko vas bom očistil pred vsemi vašimi krivičnostmi, vam bom prav tako povzročil, da prebivate v mestih in opustošenosti bodo pozidane.',
        34: 'In zapuščena dežela bo preorana, kakor ta leži zapuščena pred očmi vseh, ki so hodili mimo.',
        35: 'In rekli bodo: ›Ta dežela, ki je bila zapuščena, je postala podobna edenskemu vrtu; in opustošena in zapuščena in porušena mesta so postala ograjena in naseljena.‹',
        36: 'Potem bodo pogani, ki so ostali okoli vas, vedeli, da sem jaz, Gospod, zgradil porušene kraje in zasadil to, kar je bilo zapuščeno. Jaz, Gospod, sem to govoril in jaz bom to storil.‹',
        37: 'Tako govori Gospod Bog: ›Vendar bom zaradi tega povpraševan od Izraelove hiše, da to storim zanje; povečal jih bom z možmi kakor trop.',
        38: 'Kakor svet trop, kakor trop [prestolnice] Jeruzalem ob njenih slovesnih praznikih, tako bodo opustošena mesta napolnjena s tropi ljudi, in spoznali bodo, da jaz sem Gospod.‹«',
    },
    37: {
        1: 'Gospodova roka je bila nad menoj in me odvedla ven v Gospodovem duhu in me postavila dol v sredo doline, ki je bila polna kosti',
        2: 'in dal mi je, da sem šel okoli njih. In glej, tam jih je bilo zelo veliko v odprti dolini. In glej, bile so zelo suhe.',
        3: 'Rekel mi je: »Človeški sin, ali lahko te kosti živijo?« Odgovoril sem: »Oh Gospod Bog, ti veš.«',
        4: 'Ponovno mi je rekel: »Prerokuj nad temi kostmi in jim reci: ›Oh ve, suhe kosti, poslušajte Gospodovo besedo.',
        5: 'Tako govori Gospod Bog tem kostem: ›Glejte, povzročil bom, da v vas vstopi dih in boste živele.',
        6: 'Na vas bom položil kite in privedel meso na vas in vas pokril s kožo in položil dih v vas in ve boste živele in spoznale boste, da jaz sem Gospod.‹«',
        7: 'Tako sem prerokoval, kakor mi je bilo zapovedano. Ko sem prerokoval, je bil tam hrup in glej tresenje in kosti so prišle skupaj, kost k svoji kosti.',
        8: 'In ko sem gledal, glej, kite in meso so prišli nanje in zgoraj jih je pokrila koža, toda v njih ni bilo diha.',
        9: 'Potem mi je rekel: »Prerokuj vetru, prerokuj, človeški sin in reci vetru: ›Tako govori Gospod Bog: ›Pridi iz štirih vetrov, oh dih in dihni na te umorjene, da bodo lahko živeli.‹«',
        10: 'Tako sem prerokoval, kakor mi je zapovedal in dih je prišel vanje in oživeli so in vstali na svoja stopala, silno velika vojska.',
        11: '§ Potem mi je rekel: »Človeški sin, te kosti so celotna Izraelova hiša. Glej, govorijo: ›Naše kosti so suhe in naše upanje je izgubljeno. Odrezani smo iz svoje dežele.‹',
        12: 'Zato prerokuj in jim reci: ›Tako govori Gospod Bog: ›Glej, oh moje ljudstvo, odprl bom vaše grobove in povzročim vam, da pridete iz svojih grobov in vas privedem v Izraelovo deželo.',
        13: 'In vi boste spoznali, da jaz sem Gospod, ko odprem vaše grobove, oh moje ljudstvo in vas privedel gor, ven iz vaših grobov.',
        14: 'Svojega duha bom položil v vas in boste živeli in namestil vas bom v vašo lastno deželo. Potem boste vedeli, da sem jaz, Gospod, to govoril in to izvêdel, govori Gospod.‹«',
        15: 'Beseda Gospodova je ponovno prišla k meni, rekoč:',
        16: '»Poleg tega si ti, človeški sin, vzemi eno palico in nanjo napiši: ›Za Juda in za Izraelove otroke, njegove družabnike.‹ Potem vzemi drugo palico in nanjo napiši: ›Za Jožefa, Efrájimovo palico in za vso Izraelovo hišo njegovih družabnikov.‹',
        17: 'Pridruži ju eno k drugi, v eno palico; in postali bosta eno v tvoji roki.',
        18: 'In ko ti bodo otroci tvojega ljudstva govorili, rekoč: ›Ali nam ne boš pokazal, kaj misliš s tem?‹',
        19: 'jim reci: ›Tako govori Gospod Bog: ›Glejte, vzel bom Jožefovo palico, ki je v Efrájimovi roki in Izraelove rodove, njegove rojake in jih položil z njim, celó z Judovo palico in jih naredil eno palico in oni bodo eno v moji roki.',
        20: 'In palici, na kateri pišeš, bosta v tvoji roki pred njihovimi očmi.‹',
        21: 'In reci jim: ›Tako govori Gospod Bog: ›Glej vzel bom Izraelove otroke izmed poganov, kamor so odšli in zbral jih bom na vsaki strani in jih privedel v njihovo lastno deželo.',
        22: 'In naredil jih bom en narod v deželi, na Izraelovih gorah; in en kralj bo kralj nad njimi vsemi, in ne bodo več dva naroda niti sploh ne bodo več razdeljeni v dve kraljestvi.',
        23: 'Niti se ne bodo več omadeževali s svojimi maliki niti s svojimi ostudnimi stvarmi niti s katerimikoli izmed njihovih prestopkov, temveč jih bom rešil iz vseh njihovih bivališč, v katerih so grešili in jih bom očistil. Tako bodo moje ljudstvo in jaz bom njihov Bog.',
        24: 'Moj služabnik David bo kralj nad njimi; in vsi bodo imeli enega pastirja. Prav tako se bodo ravnali po mojih sodbah in obeleževali moje zakone in jih izvajali.',
        25: 'In prebivali bodo v deželi, ki sem jo dal Jakobu, svojemu služabniku, v kateri so prebivali vaši očetje; in prebivali bodo tam, celó oni, njihovi otroci in otroci njihovih otrok na veke, in moj služabnik David bo njihov princ na veke.',
        26: 'Poleg tega bom z njimi sklenil zavezo miru. To bo večna zaveza z njimi in jaz jih bom namestil in jih pomnožil in svoje svetišče bom postavil v njihovi sredi na vékomaj.',
        27: 'Prav tako bo z njimi moje šotorsko svetišče. Da, jaz bom njihov Bog in oni bodo moje ljudstvo.',
        28: 'In pogani bodo spoznali, da jaz, Gospod, posvečujem Izraela, ko bo moje svetišče v njihovi sredi na vékomaj.‹«',
    },
    38: {
        1: 'In k meni je prišla Gospodova beseda, rekoč:',
        2: '»Človeški sin, naravnaj svoj obraz zoper Gog, deželo Magóg, glavnega princa Mešeha in Tubála in prerokuj zoper njega',
        3: 'in reci: ›Tako govori Gospod Bog: ›Glej, jaz sem zoper tebe, oh Gog, glavni princ Mešeha in Tubála.',
        4: 'Obrnil te bom nazaj in vtaknil kavlje v tvoje čeljusti in te privedel naprej in vso tvojo vojsko, konje in konjenike, vse izmed njih oblečene z vsemi vrstami bojne opreme, celo veliko družbo z majhnimi ščiti in ščiti; vsi izmed njih rokujejo z meči:',
        5: 'Perzija, Etiopija in Libija z njimi; vsi izmed njih s ščitom in čelado:',
        6: 'Gomer in vse njegove čete; hiša Togarmá od severnih četrti in vse njegove čete in mnogo ljudstva s teboj.',
        7: 'Bodi pripravljen in pripravi zase, ti in vsa tvoja skupina, ki so zbrani k tebi in ti jim bodi stražar.',
        8: 'Po mnogih dneh boš obiskan. V zadnjih letih boš prišel v deželo, ki je privedena nazaj pred mečem in je zbrana izmed številnih ljudstev zoper Izraelove gore, ki so bile vedno opustošene, toda ta je privedena izmed narodov in vsi izmed njih bodo varno prebivali.',
        9: 'Povzpel se boš in prišel kakor vihar, podoben boš oblaku, da pokriješ deželo, ti in vse tvoje čete in mnogo ljudstev s teboj.‹',
        10: 'Tako govori Gospod Bog: ›Zgodilo se bo tudi to, da bodo ob istem času v tvoj um prišle stvari, ti pa boš mislil zlo misel.‹',
        11: 'Rekel boš: ›Šel bom gor k deželi neobzidanih vasi; šel bom k tem, ki so v miru, ki varno prebivajo, vsi izmed njih prebivajo zunaj zidov in nimajo niti zapahov niti velikih vrat,',
        12: 'da vzamem ukradeno blago in da vzamem plen; da svojo roko obrnem nad zapuščene kraje, ki so sedaj naseljeni in nad ljudstva, ki so zbrana izmed narodov, ki so pridobili živino in dobrine, ki prebivajo v sredi dežele.‹',
        13: 'Saba in Dedán in trgovci iz Taršíša, z vsemi njihovimi mladimi levi, ti bodo govorili: ›Ali si prišel, da vzameš plen? Ali si zbral svojo družbo, da vzameš plen? Da odneseš srebro in zlato, da odneseš govedo in dobrine, da vzameš velik plen?‹',
        14: 'Zatorej, človeški sin, prerokuj in reci Gogu: ›Tako govori Gospod Bog: ›Na tisti dan, ko bo moje ljudstvo Izrael varno prebivalo, mar tega ne boš vedel?',
        15: 'In prišel boš iz svojega kraja, iz severnih delov, ti in številna ljudstva s teboj, vsi izmed njih bodo jahali na konjih, velika družba in mogočna vojska',
        16: 'in prišel boš gor zoper moje ljudstvo Izraela kakor oblak, da pokriješ deželo; to bo v zadnjih dneh in privedel te bom zoper mojo deželo, da me bodo pogani lahko spoznali, ko bom posvečen v tebi, oh Gog, pred njihovimi očmi.‹',
        17: 'Tako govori Gospod Bog: › Ali si ti tisti, o katerem sem govoril v starih časih po svojih služabnikih, Izraelovih prerokih, ki so prerokovali v tistih dneh mnoga leta, da te bom privedel zoper njih?',
        18: 'In zgodilo se bo ob istem času, ko bo proti Izraelovi deželi prišel Gog,‹ govori Gospod Bog, › da bo na moj obraz prišla moja razjarjenost.',
        19: 'Kajti v svojem ljubosumju in v ognju svojega besa sem govoril: ›Zagotovo bo na ta dan v Izraelovi deželi veliko tresenje;',
        20: 'tako da bodo ribe morja in perjad neba in poljske živali in vse plazeče stvari, ki se plazijo po zemlji in vsi ljudje, ki so na obličju zemlje, trepetali ob moji prisotnosti in gore bodo zrušene in strmi kraji bodo padli in vsak zid bo padel na tla.‹',
        21: 'In proti njemu bom prek vseh svojih gora poklical meč,‹ govori Gospod Bog. ›Vsakogar meč bo zoper svojega brata.',
        22: 'In jaz bom navajal dokaze zoper njega s kužno boleznijo in s krvjo, in deževal bom nanj in na njegove čete in na mnoga ljudstva, ki so z njim, preplavljajoč dež in velika zrna toče, ogenj in žveplo.',
        23: 'Tako se bom poveličal in se posvetil; in znan bom v očeh mnogih narodov in spoznali bodo, da jaz sem Gospod.‹',
    },
    39: {
        1: '›Zato, ti, človeški sin, prerokuj zoper Gog in reci: ›Tako govori Gospod Bog: ›Glej, jaz sem zoper tebe, oh Gog, glavni princ Mešeha in Tubála,',
        2: 'in obrnil te bom nazaj in pustil samo šesti del tebe in ti povzročil, da prideš gor iz severnih krajev in privedel te bom na Izraelove gore',
        3: 'in izbil ti bom lok iz tvoje leve roke in tvojim puščicam povzročil, da izpadejo iz tvoje desnice.',
        4: 'Padel boš na Izraelovih gorah, ti in vse tvoje čete in ljudstvo, ki je s teboj. Izročil te bom pticam roparicam vsake vrste in k živalim polja, da boš požrt.',
        5: 'Padel boš na odprtem polju, kajti jaz sem to govoril,‹ govori Gospod Bog.',
        6: '›In poslal bom ogenj na Magóg in med tiste, ki brezskrbno prebivajo na otokih. In spoznali bodo, da jaz sem Gospod.',
        7: 'Tako bom svoje sveto ime naredil znano v sredi svojega ljudstva Izraela; in ne bom jim več dopustil, da oskrunijo moje sveto ime. In pogani bodo spoznali, da jaz sem Gospod, Sveti v Izraelu.',
        8: 'Glej, prišel je in narejeno je,‹ govori Gospod Bog; ›to je dan, o katerem sem govoril.',
        9: 'Tisti, ki prebivajo v Izraelovih mestih, bodo šli naprej in bodo zakurili ogenj, sežgali orožje, tako ščite in majhne ščite, loke, puščice, krepelca ter sulice in sedem let jih bodo sežigali z ognjem,',
        10: 'tako da ne bodo vzeli nobenega lesa iz polja niti posekali nobenega iz gozdov; kajti orožje bodo sežigali z ognjem in plenili bodo tiste, ki so jih plenili in ropali bodo tiste, ki so jih ropali,‹ govori Gospod Bog.',
        11: '›In na tisti dan se bo zgodilo, da bom Gogu dal kraj za grobove v Izraelu, dolino popotnikov na vzhodu morja, in ta bo zamašila nosove popotnikom, in tam bodo sežgali Goga in vso njegovo množico in imenovali jo bodo Dolina Gogove množice.',
        12: 'In sedem mesecev jih bo Izraelova hiša pokopavala, da bodo lahko očistili deželo.',
        13: 'Da, vse ljudstvo dežele jih bo pokopavalo; in to jim bo ugled na dan, ko bom proslavljen,‹ govori Gospod Bog.',
        14: '§ ›In oddvojili bodo može z nenehno zaposlitvijo, ki bodo hodili skozi deželo, da bi s potniki pokopavali tiste, ki ostajajo na obličju zemlje, da jo očistijo; po koncu sedmih mesecev bodo iskali.',
        15: 'In potniki, ki gredo skozi deželo, ko kdorkoli zagleda človeško kost, potem bo ob njej postavil znamenje, dokler je grobarji ne pokopljejo v dolini Gogove množice.',
        16: 'In ime mesta bo prav tako Hamóna. Tako bodo očistili deželo.',
        17: 'In ti, človeški sin,‹ tako govori Gospod Bog: ›Govori vsaki operjeni perjadi in vsaki živali polja: ›Zberite se in pridite; zberite se na vsaki strani k moji klavni daritvi, ki jo darujem za vas, torej veliki klavni daritvi na Izraelovih gorah, da boste lahko jedle meso in pile kri.',
        18: 'Jedle boste meso mogočnih in pile kri zemeljskih princev, ovnov, jagnjet in koz, bikcev, vsi izmed njih bašánski pitanci.',
        19: 'In jedle boste tolščo, dokler ne boste nasičene in pile kri, dokler ne boste pijane od moje klavne daritve, ki sem jo žrtvoval za vas.',
        20: 'Tako boste nasičene pri moji mizi s konji in bojnimi vozovi in z mogočnimi možmi in z vsemi bojevniki,‹ govori Gospod Bog.',
        21: '›In svojo slavo bom postavil med pogane in vsi pogani bodo videli mojo sodbo, ki sem jo izvršil in mojo roko, ki sem jo položil nanje.',
        22: 'Tako bo Izraelova hiša spoznala, da jaz sem Gospod, njihov Bog, od tega dne naprej.',
        23: 'In pogani bodo vedeli, da je hiša Izraelova odšla v ujetništvo zaradi svojih krivičnosti, ker so kršili zoper mene, zato sem svoj obraz skril pred njimi in jih izročil v roko njihovih sovražnikov; tako so vsi padli pod mečem.',
        24: 'Glede na njihovo nečistost in glede na njihove prestopke sem jim storil in svoj obraz sem skril pred njimi.‹',
        25: 'Zato tako govori Gospod Bog: ›Sedaj bom ponovno privedel Jakobovo ujetništvo in usmiljenje bom imel nad celotno Izraelovo hišo in ljubosumen bom zaradi svojega svetega imena;',
        26: 'po tem, ko so nosili svojo sramoto in vse svoje prestopke, s katerimi so kršili zoper mene, ko so varno prebivali v svoji deželi in jih nihče ni strašil.',
        27: 'Ko sem jih ponovno privedel izmed ljudstva in jih zbral iz dežel njihovih sovražnikov in sem posvečen v njih pred očmi mnogih narodov;',
        28: 'potem bodo spoznali, da jaz sem Gospod, njihov Bog, ki jim je storil, da so bili odvedeni v ujetništvo med pogane, toda zbral sem jih k njihovi lastni deželi in nikogar izmed njih nisem več pustil tam.',
        29: 'Niti svojega obraza ne bom več skrival pred njimi, kajti svojega duha sem izlil na Izraelovo hišo,‹ govori Gospod Bog.‹«',
    },
    40: {
        1: 'V petindvajsetem letu našega ujetništva, v začetku leta, na deseti dan meseca, v štirinajstem letu, potem ko je bilo mesto udarjeno, na prav isti dan, je bila nad menoj Gospodova roka in me privedla tja.',
        2: 'V Božjih videnjih me je privedel v deželo Izrael in me postavil na zelo visoko goro, pri kateri je bil kakor okvir mesta na jugu.',
        3: 'In privedel me je tja in glej, tam je bil mož, katerega videz je bil podoben videzu brona, z laneno vrvico v svoji roki in merilno trstiko; in stal je v velikih vratih.',
        4: 'In mož mi je rekel: »Človeški sin, glej s svojimi očmi in poslušaj s svojimi ušesi in svoje srce naravnaj na vse to, kar ti bom pokazal; kajti z namenom, da ti jih lahko pokažem, si bil priveden sèm. Vse to, kar vidiš, oznani Izraelovi hiši.«',
        5: 'Glej obzidje zunaj, naokoli hiše in v človeški roki merilna trstika, šest komolcev dolga, po komolec in širino roke, tako je izmeril širino zgradbe, ena trstika; in višino, ena trstika.',
        6: 'Potem je prišel k velikim vratom, ki gledajo proti vzhodu in odšel gor po njegovih stopnicah in izmeril prag velikih vrat, ki je bil širok eno trstiko; in drugi prag velikih vrat, ki je bil širok eno trstiko.',
        7: 'In vsaka majhna soba je bila eno trstiko dolga in eno trstiko široka; in med majhnimi sobami je bilo pet komolcev; in prag velikih vrat, znotraj, pri preddverju velikih vrat, je bil eno trstiko [širok].',
        8: 'Izmeril je tudi preddverje znotraj velikih vrat, ena trstika.',
        9: 'Potem je izmeril preddverje velikih vrat, osem komolcev; in njegovi podboji, dva komolca; in preddverje velikih vrat je bilo znotraj.',
        10: 'In majhne sobe velikih vrat proti vzhodu so bile tri na tej strani in tri na oni strani; te tri so bile ene mere; in podboji so imeli eno mero na tej strani in na oni strani.',
        11: 'In izmeril je širino vhoda velikih vrat, deset komolcev; in dolžino velikih vrat, trinajst komolcev.',
        12: 'Tudi prostora pred majhnimi sobami je bilo en komolec na tej strani in en komolec prostora je bilo na oni strani; in majhne sobe so bile šest komolcev na tej strani in šest komolcev na oni strani.',
        13: 'Potem je izmeril velika vrata od strehe ene majhne sobe do strehe druge: širina je bila petindvajset komolcev, vrata nasproti vratom.',
        14: 'Naredil je tudi podboje šestdesetih komolcev, celo podboj dvora naokoli velikih vrat.',
        15: 'In od pročelja velikih vrat vhoda do pročelja preddverja notranjih velikih vrat je bilo petdeset komolcev.',
        16: 'In tam so bila ozka okna k majhnim sobam in k njihovim podbojem znotraj, naokoli velikih vrat in podobno k obokom, in okna so bila naokoli navznoter sobe, in na vsakem podboju so bila palmova drevesa.',
        17: 'Potem me je privedel na zunanji dvor in glej, tam so bile sobe in tlak, narejen za dvor naokoli. Trideset sob je bilo na tlaku.',
        18: 'In tlak, ki je bil pri strani velikih vrat, nasproti dolžine velikih vrat, je bil nižji tlak.',
        19: 'Potem je izmeril širino od sprednjega dela spodnjih velikih vrat do sprednjega dela notranjega dvora zunaj; sto komolcev proti vzhodu in proti severu.',
        20: 'In velika vrata zunanjega dvora, ki so gledala proti severu, izmeril je njihovo dolžino in njihovo širino.',
        21: 'In njihove majhne sobe so bile tri na tej strani in tri na oni strani; in njihovi podboji in njihovi oboki so bili po meri prvih vrat. Njihova dolžina je bila petdeset komolcev in širina petindvajset komolcev.',
        22: 'In njihova okna in njihovi oboki in njihova palmova drevesa so bila po meri velikih vrat, ki gledajo proti vzhodu; in k tem so se vzpeli po sedmih stopnicah; in njihovi oboki so bili pred njimi.',
        23: 'In velika vrata notranjega dvora so bila nasproti velikih vrat proti severu in proti vzhodu; in od velikih vrat do velikih vrat je izmeril sto komolcev.',
        24: 'Po tem me je privedel proti jugu in glej, velika vrata proti jugu. Izmeril je njihove podboje in njihove oboke, glede na te mere.',
        25: 'In tam so bila okna in njihovi oboki naokoli, podobni tistim oknom. Dolžina je bila petdeset komolcev in širina petindvajset komolcev.',
        26: 'In tam je bilo sedem stopnic, da se gre gor do njih in njihovi oboki so bili pred njimi. Ta so imela palmovi drevesi, eno na tej strani in drugo na oni strani, na njihovih podbojih.',
        27: 'In na notranjem dvoru, proti jugu, so bila velika vrata, in od velikih vrat do velikih vrat je proti jugu izmeril sto komolcev.',
        28: 'In privedel me je na notranji dvor pri južnih velikih vratih: in južna velika vrata je izmeril glede na te mere;',
        29: 'in njihove majhne sobe in njihovi podboji in njihovi oboki, glede na te mere: in tam so bila okna v njej in njihovi oboki naokoli: in ta so bila petdeset komolcev dolga in petindvajset komolcev široka.',
        30: 'Oboki naokoli so bili petindvajset komolcev dolgi in pet komolcev široki.',
        31: 'Njihovi oboki so bili proti skrajnemu dvoru; palmova drevesa so bila na njihovih podbojih. Gor do njih je vodilo osem stopnic.',
        32: 'Privedel me je na notranji dvor proti vzhodu in izmeril velika vrata glede na te mere.',
        33: 'Njihove majhne sobe, njihovi podboji in njihovi oboki so bili glede na te mere. Tam so bila okna v njihovih obokih naokoli. To je bilo petdeset komolcev dolgo in petindvajset komolcev široko.',
        34: 'Njihovi oboki so bili proti zunanjemu dvoru; in palmova drevesa so bila na njihovih podbojih, na tej strani in na oni strani in gor do njih je vodilo osem stopnic.',
        35: 'Privedel me je k severnim velikim vratom in jih izmeril glede na te mere;',
        36: 'njihove majhne sobe, njihove podboje in njihove oboke in okna k tem naokoli; dolžina je bila petdeset komolcev in širina petindvajset komolcev.',
        37: 'Njihovi podboji so bili proti skrajnemu dvoru; in palmova drevesa so bila na njihovih podbojih, na tej strani in na oni strani in gor do njih je vodilo osem stopnic.',
        38: 'Sobe in njihovi vhodi so bili ob podbojih velikih vrat, kjer so prali žgalno daritev.',
        39: 'V preddverju velikih vrat sta bili dve mizi na tej strani in dve mizi na oni strani, da na njih zakoljejo žgalno daritev in daritev za greh in daritev za prestopek.',
        40: 'Zunaj ob strani, kakor gre kdo gor k vhodu severnih velikih vrat, sta bili dve mizi; in na drugi strani, ki je bila pri preddverju velikih vrat, sta bili dve mizi.',
        41: 'Štiri mize so bile na tej strani in štiri mize na oni strani, pri straneh velikih vrat; osem miz, na katerih so klali svoje daritve.',
        42: 'Štiri mize so bile iz klesanega kamna za žgalno daritev, komolec in pol dolge in komolec in pol široke in en komolec visoke, na katere so prav tako položili orodje, s katerim so zaklali žgalno daritev in klavno daritev.',
        43: 'Znotraj so bili kavlji, dlan široki, pritrjeni naokoli in na mizah je bilo meso daritve.',
        44: 'Zunaj notranjih velikih vrat so bile sobe pevcev notranjega dvora, ki je bil ob strani severnih velikih vrat in njihova pročelja so bila proti jugu. Ena je bila ob strani vzhodnih velikih vrat in imela pročelje proti severu.',
        45: 'In rekel mi je: »Ta soba, katere pročelje je proti jugu, je za duhovnike, čuvaje oskrbe hiše.',
        46: 'Soba, katere pročelje je proti severu, je za duhovnike, čuvaje oskrbe oltarja: to so Cadókovi sinovi med Lévijevimi sinovi, ki so prišli blizu h Gospodu, da mu služijo.',
        47: 'Tako je izmeril dvor, sto komolcev dolg in sto komolcev širok, štirioglat; in oltar, ki je bil pred hišo.',
        48: 'Privedel me je k preddverju hiše in izmeril vsak podboj preddverja, pet komolcev na tej strani in pet komolcev na oni strani in širina velikih vrat je bila tri komolce na tej strani in tri komolce na oni strani.',
        49: '§ Dolžina preddverja je bila dvajset komolcev in širina enajst komolcev; in privedel me je poleg stopnic, po katerih so se dvignili do njega. Tam so bili stebri ob podbojih, eden na tej strani, drugi pa na oni strani.',
    },
    41: {
        1: 'Potem me je privedel k templju in izmeril podboje, šest komolcev široke na eni strani in šest komolcev široke na drugi strani, kar je bila širina šotorskega svetišča.',
        2: 'Širina vrat je bila deset komolcev; in strani vrat na eni strani je bilo pet komolcev in pet komolcev na drugi strani: in izmeril je njihovo dolžino, štirideset komolcev; in širino: dvajset komolcev.',
        3: 'Potem je odšel noter in izmeril podboj vrat: dva komolca; in vrata: šest komolcev; in širino vrat: sedem komolcev.',
        4: 'Tako je izmeril njegovo dolžino: dvajset komolcev; in širino: dvajset komolcev, pred templjem. Rekel mi je: »To je najsvetejši prostor.«',
        5: 'Potem je izmeril zid hiše: šest komolcev; in širino vsake stranske sobe: štiri komolce naokoli hiše na vsaki strani.',
        6: 'Stranske sobe so bile tri, ena nad drugo in trideset v vrsti; in vstopale so v zid, ki je bil iz hiše za stranske sobe naokoli, da bi lahko imele oporo, toda te se niso držale v zidu hiše.',
        7: 'In tam je bila razširitev in okljuke naokrog strmo navzgor k stranskim sobam, kajti okljuke naokrog hiše so šle strmo navzgor naokrog hiše. Zato je bila širina hiše strmo navzgor in se tako povečevala od najnižjih sob do najvišjih ob sredini.',
        8: 'Prav tako sem videl višino hiše naokrog. Temelji stranskih sob so bili cela trstika iz šestih velikih komolcev.',
        9: 'Debelina zidu, ki je bil znotraj, za stransko sobo, je bila pet komolcev. In to, kar je preostalo, je bil prostor stranskih sob, ki so bile znotraj.',
        10: 'Med sobami je bila širina dvajsetih komolcev naokoli hiše na vsaki strani.',
        11: 'Vrata stranskih sob so bila proti kraju, ki je preostal, ena vrata proti severu in druga vrata proti jugu. Širina prostora, ki je preostal, je bila pet komolcev naokoli.',
        12: 'Torej zgradba, ki je bila pred ločenim krajem na koncu proti zahodu, je bila sedemdeset komolcev široka; in zid zgradbe je bil naokoli debel pet komolcev in njegova dolžina devetdeset komolcev.',
        13: 'Tako je izmeril hišo, sto komolcev dolga; in ločen kraj in zgradbo, z njenimi zidovi, sto komolcev dolgo;',
        14: 'tudi širino pročelja hiše in ločenega kraja proti vzhodu: sto komolcev.',
        15: 'Izmeril je dolžino zgradbe nasproti ločenemu kraju, ki je bil za njo in njene galerije na eni strani in na drugi strani: sto komolcev, z notranjim templjem in preddverji dvora;',
        16: 'podboje vrat in ozka okna in galerije naokoli na svojih treh nadstropjih, nasproti vratom, naokrog obloženi z lesom in od tal gor do oken in okna so bila pokrita;',
        17: 'k tem nad vrati, celo do notranje hiše in zunaj in pri vsem zidu naokoli, znotraj in zunaj, po meri.',
        18: 'To je bilo narejeno s kerubi in palmovimi drevesi, tako da je bilo palmovo drevo med kerubom in kerubom; in vsak kerub je imel dva obraza;',
        19: 'tako da je bilo obličje človeka proti palmovemu drevesu na tej strani in obličje mladega leva proti palmovemu drevesu na oni strani. To je bilo narejeno po vsej hiši naokoli.',
        20: 'Od tal do nad vrati so bili narejeni kerubi in palmova drevesa in na zidu templja.',
        21: 'Podboji templja so bili pravokotni in pročelje svetišča; videz enega kakor videz drugega.',
        22: 'Oltar iz lesa je bil tri komolce visok in njegova dolžina dva komolca; in njegovi vogali in njegova dolžina in njegove stene so bile iz lesa. Rekel mi je: »To je miza, ki je pred Gospodom.«',
        23: 'Tempelj in svetišče sta imela dvoje vrat.',
        24: 'Vsaka vrata so imela dvoje kril, dvoje obračajočih se kril; dve krili za ena vrata in dve krili za druga vrata.',
        25: 'Na njih so bili narejeni, na vratih templja, kerubi in palmova drevesa, podobna, kakor so bila narejena na stenah; in tam so bile debele deske na pročelju zunaj preddverja.',
        26: 'In bila so ozka okna in palmova drevesa na eni strani in na drugi strani, na straneh preddverja in na stranskih sobah hiše na debelih deskah.',
    },
    42: {
        1: 'Potem me je odvedel naprej na skrajni dvor, ob poti proti severu in me privedel v sobo, ki je bila nasproti ločenemu kraju in ki je bila pred zgradbo proti severu.',
        2: 'Pred dolžino stotih komolcev so bila severna vrata in širina je bila petdeset komolcev.',
        3: 'Nasproti dvajsetim komolcem, ki so bili za notranji dvor in nasproti tlaku, ki je bil za skrajni dvor, je bila galerija nasproti galeriji, v treh nadstropjih.',
        4: 'Pred sobami je bil hodnik desetih komolcev širine znotraj, pot enega komolca; in njihova vrata proti severu.',
        5: 'Torej zgornje sobe so bile krajše, kajti galerije so bile višje kakor te, kakor spodnje in kakor tiste, ki so bile v sredini zgradbe.',
        6: 'Kajti bile so v treh nadstropjih, toda niso imele stebrov kakor stebri dvora, zato je bila zgradba ožja, bolj kakor nižje in srednje od tal.',
        7: 'Zid, ki je bil zunaj, nasproti sobam, proti skrajnemu dvoru, na sprednjem delu sob, njegova dolžina je bila petdeset komolcev.',
        8: 'Kajti dolžina sob, ki so bile na skrajnem dvoru, je bila petdeset komolcev, in glej, pred templjem je bilo sto komolcev.',
        9: 'Izpod teh sob je bil vhod na vzhodni strani, kakor gre nekdo vanje od skrajnega dvora.',
        10: 'Sobe so bile v debelini zidu dvora proti vzhodu, nasproti ločenemu kraju in nasproti zgradbi.',
        11: 'Pot pred njimi je bila podobna videzu sob, ki so bile proti severu, tako dolga kakor one in tako široka kakor one, in vsi njihovi izhodi so bili tako glede na njihove oblike kakor glede na njihova vrata.',
        12: 'Glede na vrata sob, ki so bila proti jugu, so bila vrata na začetku poti, celó na poti neposredno pred zidom proti vzhodu, kakor nekdo vstopa vanje.',
        13: 'Potem mi je rekel: »Severne sobe in južne sobe, ki so pred ločenim krajem, te so svete sobe, kjer bodo duhovniki, ki pristopajo h Gospodu, jedli najsvetejše stvari. Tam bodo polagali najsvetejše stvari in jedilno daritev in daritev za greh in daritev za prestopke; kajti kraj je svet.',
        14: 'Ko duhovniki vstopijo vanj, potem ne bodo šli ven iz svetega kraja na skrajni dvor, temveč bodo tam odložili oblačila, v katerih so služili, kajti ta so sveta in nadeli si bodo druga oblačila in pristopili bodo k tistim stvarem, ki so za ljudstvo.«',
        15: 'Torej ko je končal merjenje notranje hiše, me je privedel naprej proti velikim vratom, katerih pročelje je proti vzhodu in ga izmeril naokrog.',
        16: 'Izmeril je vzhodno stran z merilno trstiko, petsto trstik, z merilno trstiko naokrog.',
        17: 'Izmeril je severno stran, petsto trstik, z merilno trstiko naokrog.',
        18: 'Izmeril je južno stran, petsto trstik, z merilno trstiko.',
        19: 'Obrnil se je k zahodni strani in izmeril petsto trstik z merilno trstiko.',
        20: 'Izmeril jo je ob štirih straneh. Naokrog je imela obzidje, petsto trstik dolgo in petsto široko, da bi naredil oddvojitev med svetiščem in oskrunjenim krajem.',
    },
    43: {
        1: 'Zatem me je privedel k velikim vratom, celó velikim vratom, ki gledajo proti vzhodu.',
        2: 'In glej, slava Izraelovega Boga je prišla po poti od vzhoda, in njegov glas je bil podoben hrupu mnogih vodá, in zemlja je zasijala z njegovo slavo.',
        3: 'In to je bilo glede na videz videnja, ki sem ga videl, celó glede na videnje, ki sem ga videl, ko sem prišel, da uničim mesto; in videnja so bila podobna videnju, ki sem ga videl pri reki Kebár; in padel sem na svoj obraz.',
        4: 'Gospodova slava je prišla v hišo po poti velikih vrat, katerih pročelje je proti vzhodu.',
        5: 'Tako me je duh vzel gor in me privedel na notranji dvor; in, glej, Gospodova slava je napolnila hišo.',
        6: 'Slišal sem ga, kako mi govori iz hiše; in poleg mene je stal mož.',
        7: 'Rekel mi je: »Človeški sin, prostor mojega prestola in kraj za podplate mojih stopal, kjer bom na veke prebival v sredi Izraelovih otrok in mojega svetega imena Izraelova hiša ne bo več omadeževala, niti oni, niti njihovi kralji s svojim vlačugarstvom, niti s trupli svojih kraljev na svojih visokih krajih.',
        8: 'V njihovi postavitvi njihovega praga ob mojih pragovih in njihovega podboja ob mojih podbojih in zidom med menoj in njimi, so celo omadeževali moje sveto ime s svojimi ogabnostmi, ki so jih zagrešili. Zatorej sem jih použil v svoji jezi.',
        9: 'Torej naj odstranijo svoje vlačugarstvo in trupla svojih kraljev daleč od mene in jaz bom prebival v njihovi sredi na veke.',
        10: 'Ti, človeški sin, pokaži Izraelovi hiši, da jih bo lahko sram njihovih krivičnosti in naj izmerijo vzorec.',
        11: 'Če se bodo sramovali vsega, kar so storili, jim pokaži obliko hiše, njen slog, njene izhode, njene vhode, vse njene oblike, vse njene odredbe, vse njene oblike in vse njene postave, in zapiši jih v njihovem pogledu, da se bodo lahko držali njene celotne oblike in vseh njenih odredb in jih izpolnjevali.«',
        12: 'To je postava hiše: ›Na vrhu gore bo njena celotna meja naokrog najsvetejšega.‹ Glej, to je postava hiše.«',
        13: 'In to so mere oltarja po komolcih: ›Komolec je komolec in širina roke; celo dno bo komolec in širina komolca in njena meja ob njenem robu naokrog bo pedenj in to bo višji kraj oltarja.',
        14: 'Od dna na tleh, celó do spodnjega podzidka, bo dva komolca in širina en komolec; in od manjšega podzidka celó do večjega podzidka, bo štiri komolce in širina en komolec.',
        15: 'Tako bo oltar štiri komolce; in od oltarja in navzgor bodo štirje rogovi.',
        16: '§ Oltar bo dvanajst komolcev dolg, dvanajst širok, kvadraten v svojih štirih oglih.',
        17: 'Podzidek bo štirinajst komolcev dolg in štirinajst širok v svojih štirih oglih; in rob okoli njega bo pol komolca; in njegovo dno bo komolec naokrog; in njegove stopnice bodo gledale proti vzhodu.',
        18: 'Rekel mi je: »Človeški sin, tako govori Gospod Bog: ›To so odredbe oltarja na dan, ko ga bodo naredili, da bodo na njem darovali žgalne daritve in da bodo na njem škropili kri.',
        19: 'Duhovnikom Lévijevcem, ki bodo od Cadókovega semena, ki pristopajo k meni, da bi mi služili,‹ govori Gospod Bog, ›boš dal mladega bikca za daritev za greh.',
        20: 'Vzel boš od njegove krvi in jo nanesel na štiri njegove rogove in na štiri vogle podzidka in na rob naokoli. Tako ga boš očistil in prečistil.',
        21: 'Vzel boš tudi bikca daritve za greh in zažgal ga bo na določenem prostoru hiše, zunaj svetišča.',
        22: 'Na drugi dan boš daroval kozlička od koz, brez pomanjkljivosti, za daritev za greh; in očistili bodo oltar, kakor so ga očistili z bikcem.',
        23: 'Ko narediš konec njegovemu očiščevanju, boš daroval mladega bikca, brez pomanjkljivosti in ovna iz tropa, brez pomanjkljivosti.',
        24: 'Daroval ju boš pred Gospodom in duhovniki bodo nanje vrgli sol in darovali jih bodo za žgalno daritev Gospodu.',
        25: 'Sedem dni boš vsak dan pripravljal kozla za daritev za greh. Pripravljali bodo tudi mladega bikca in ovna iz tropa, brez pomanjkljivosti.',
        26: 'Sedem dni bodo očiščevali oltar in ga prečiščevali in se uméščali.',
        27: 'Ko se ti dnevi iztečejo, bo tako, da bodo na osmi dan in tako naprej, duhovniki pripravljali vaše žgalne daritve na oltarju in vaše mirovne daritve; in jaz vas bom sprejel,‹ govori Gospod Bog.«',
    },
    44: {
        1: 'Potem me je privedel nazaj po poti velikih vrat zunanjega svetišča, ki gledajo proti vzhodu; in ta so bila zaprta.',
        2: 'Potem mi je Gospod rekel: »Ta velika vrata bodo zaprta, ne bodo odprta in noben človek ne bo vstopil skoznje; ker je Gospod, Izraelov Bog, vstopil skoznje, zato bodo zaprta.',
        3: 'Ta so za princa; princ bo sedel v njih, da jé kruh pred Gospodom; vstopil bo po poti preddverja teh velikih vrat in ven bo šel po isti poti.«',
        4: 'Potem me je privedel po poti severnih velikih vrat pred hišo. Pogledal sem in glej, Gospodova slava je napolnila Gospodovo hišo in padel sem na svoj obraz.',
        5: 'Gospod mi je rekel: »Človeški sin, dobro zaznamuj in glej s svojimi očmi in poslušaj s svojimi ušesi vse, kar ti rečem glede vseh odredb Gospodove hiše in vse njegove postave; in dobro zaznamuj vhod hiše, z vsakim vstopanjem v svetišče.',
        6: 'Upornim boš rekel, celó Izraelovi hiši: ›Tako govori Gospod Bog: ›Oh vi, Izraelova hiša, naj vam bo dovolj vseh vaših ogabnosti',
        7: 'v tem, da ste v moje svetišče privedli tujce, neobrezane v srcu in neobrezane v mesu, da bi bili v mojem svetišču, da ga oskrunijo, celó mojo hišo, ko darujete moj kruh, tolščo in kri in zaradi vseh vaših ogabnosti so prelamljali mojo zavezo.',
        8: 'Vi niste skrbeli za moje svete stvari, temveč ste si zase postavili čuvaje moje zadolžitve v mojem svetišču.‹',
        9: 'Tako govori Gospod Bog: ›Noben tujec, neobrezan v srcu niti neobrezan v mesu, izmed kateregakoli tujca, ki je med Izraelovimi otroki, ne bo vstopil v moje svetišče.',
        10: 'Lévijevci, ki so šli daleč proč od mene, ko je Izrael zašel, ki so zašli proč od mene, za svojimi maliki; oni bodo torej nosili svojo krivdo.',
        11: 'Vendar bodo služabniki v mojem svetišču in imeli bodo zadolžitev pri velikih vratih hiše in služili bodo hiši. Klali bodo žgalno daritev in klavno daritev za ljudstvo in stali bodo pred njimi, da jim služijo.',
        12: 'Ker so jim služili pred njihovimi maliki in Izraelovi hiši povzročili, da pade v krivičnost; zatorej sem proti njim vzdignil svojo roko,‹ govori Gospod Bog ›in nosili bodo svojo krivičnost.',
        13: 'In ne bodo mi prišli blizu, da bi mi opravljali duhovniško službo niti da bi se približali katerikoli izmed mojih svetih stvari na najsvetejšem kraju, temveč bodo nosili svojo sramoto in svoje ogabnosti, ki so jih zagrešili.',
        14: 'Toda naredil jih bom čuvaje oskrbe hiše, za vso njeno službo in za vse, kar bo v njej storjeno.',
        15: 'Toda duhovniki Lévijevcev, Cadókovi sinovi, ki so skrbeli za moje svetišče, ko so Izraelovi otroci zašli od mene, mi bodo prišli blizu, da bi mi služili in stali bodo pred menoj, da mi darujejo tolščo in kri,‹ govori Gospod Bog:',
        16: '›Vstopali bodo v moje svetišče in se približali moji mizi, da bi mi služili in skrbeli za mojo zadolžitev.',
        17: 'In zgodilo se bo, ko vstopajo pri velikih vratih notranjega dvora, da bodo oblečeni s platnenimi oblačili; in nobena volna ne bo prišla nanje, medtem ko služijo pri velikih vratih notranjega dvora in znotraj.',
        18: 'Na svojih glavah bodo imeli platnene klobučke in na svojih ledjih bodo imeli kratke platnene hlače; ne bodo se opasovali s čimerkoli, kar povzroča znojenje.',
        19: 'Ko gredo naprej, na skrajni dvor, celó na skrajni dvor ljudstva, bodo odložili svoja oblačila, v katerih so služili in jih položili v svete sobe in nadeli si bodo druga oblačila in ljudstva ne bodo posvetili s svojimi oblačili.',
        20: 'Niti si ne bodo brili svojih glav niti ne bodo pustili pramenom, da zrastejo dolgi. Svoje glave si bodo zgolj strigli.',
        21: 'Niti ne bo katerikoli duhovnik pil vina, ko vstopa na notranji dvor.',
        22: 'Niti si za svoje žene ne bodo jemali vdove, niti tiste, ki je odslovljena, temveč si bodo jemali device od semena Izraelove hiše ali vdovo, ki je imela poprej duhovnika.',
        23: 'Moje ljudstvo bodo učili razliko med svetim in oskrunjenim in jim povzročili, da razpoznavajo med nečistim in čistim.',
        24: 'V polemiki bodo razsojali in sodili jo bodo glede na moje sodbe in držali se bodo mojih postav in mojih zakonov in vseh mojih pravil, v vseh mojih zborih; in posvečevali bodo moje šabate.',
        25: 'Ne bodo prišli k nobeni mrtvi osebi, da se omadežujejo, razen za očeta ali za mater ali za sina, ali za hčer, za brata ali za sestro, ki nima soproga, se lahko omadežujejo.',
        26: 'Potem ko je očiščen, mu bodo prišteli sedem dni.',
        27: 'Na dan, ko gre v svetišče, na notranji dvor, da služi v svetišču, bo daroval svojo daritev za greh,‹ govori Gospod Bog.',
        28: '›To jim bo za dediščino: jaz sem njihova dediščina. Ne boste jim dali posesti v Izraelu. Jaz sem njihova posest.',
        29: 'Jedli bodo jedilno daritev in daritev za greh in daritev za prestopek in vsaka posvečena stvar v Izraelu bo njihova.',
        30: 'Prvo izmed vseh prvih sadov od vseh stvari in vsaka daritev od vsega, od vsake vrste izmed vaših daritev, bo duhovnikova. Prav tako boste dali duhovniku prvo od svojega testa, da bo lahko povzročil, da v tvoji hiši počiva blagoslov.',
        31: 'Duhovniki ne bodo jedli od česarkoli, kar je umrlo samo od sebe ali je bilo raztrgano, naj bo to perjad ali žival.',
    },
    45: {
        1: 'Poleg tega, ko boste deželo z žrebom razdeljevali v dediščino, boste darovali daritev Gospodu, sveti delež dežele: dolžina bo petindvajset tisoč trstik in širina bo deset tisoč trstik. To bo sveto na vseh njihovih mejah naokoli.',
        2: 'Od tega bo tam za svetišče petsto v dolžino, s petsto v širino, kvadratno naokoli; in petdeset komolcev naokoli za njegova predmestja.',
        3: 'Od te mere boš izmeril dolžino petindvajset tisoč in širino deset tisoč, in na njem bo svetišče in najsvetejši prostor.',
        4: 'Sveti delež dežele bo za duhovnike, služabnike svetišča, ki se bodo približali, da bi služili Gospodu in to bo prostor za njihove hiše in sveti prostor za svetišče.',
        5: '§ Petindvajset tisoč dolžine in deset tisoč širine bodo prav tako imeli Lévijevci, služabniki hiše, zase, za posest, za dvajset sob.',
        6: 'Določili boste posest mesta, pet tisoč široko in petindvajset tisoč dolgo, nasproti daritve svetega deleža. Ta bo za celotno Izraelovo hišo.',
        7: 'Delež bo za princa na eni strani in na drugi strani daritve svetega deleža in od mestne posesti, pred daritvijo svetega deleža in pred mestno posestjo od zahodne strani proti zahodu in od vzhodne strani proti vzhodu, in dolžina bo nasproti enemu izmed deležev od zahodne meje do vzhodne meje.',
        8: 'V deželi bo njegova posest v Izraelu in moji princi ne bodo več zatirali mojega ljudstva in preostanek dežele bodo dali Izraelovi hiši, glede na njihove rodove.‹',
        9: 'Tako govori Gospod Bog: ›Naj vam to zadostuje, oh Izraelovi princi: odstranite nasilje in rop, izvršujte sodbo in pravico, odstranite svoje razlastitve od mojega ljudstva,‹ govori Gospod Bog.',
        10: '›Imeli boste pravične tehtnice in pravičen škaf in pravičen čeber.',
        11: 'Škaf in čeber bosta ene mere, da bo čeber lahko vseboval deseti del tovora in škaf deseti del tovora; njegova mera bo po tovoru.',
        12: 'Šekel bo dvajset ger. Dvajset šeklov, petindvajset šeklov, petnajst šeklov bo vaša mina.',
        13: 'To je daritev, ki jo boste darovali: šesti del škafa od tovora pšenice in dali boste šesti del škafa od tovora ječmena.',
        14: 'Glede odredbe olja, čeber olja; darovali boste deseti del čebra iz kadi, kar je tovor desetih čebrov, kajti deset čebrov je tovor.',
        15: 'Eno jagnje iz tropa, izmed dvesto, iz obilnih Izraelovih pašnikov; za jedilno daritev in za žgalno daritev in za mirovne daritve, da zanje opravijo pobotanje,‹ govori Gospod Bog.',
        16: '›Vse ljudstvo dežele bo dalo to daritev za princa v Izraelu.',
        17: 'To bo delež princa, da da žgalne daritve in jedilne daritve in pitne daritve ob praznikih, ob mlajih, ob šabatih, ob vseh slovesnostih Izraelove hiše. Pripravil bo daritev za greh, jedilno daritev, žgalno daritev in mirovne daritve, da opravi pobotanje za Izraelovo hišo.‹',
        18: 'Tako govori Gospod Bog: ›V prvem mesecu, na prvi dan meseca, boš vzel mladega bikca brez pomanjkljivosti in očistil svetišče.',
        19: 'Duhovnik bo vzel od krvi daritve za greh in jo pomazal na podboje hiše in na štiri vogale oltarnega podzidka in na podboje velikih vrat notranjega dvora.',
        20: 'Tako boš delal sedmi dan meseca, za vsakega, ki se moti in za tistega, ki je preprost. Tako boš pobotal hišo.',
        21: 'V prvem mesecu, na štirinajsti dan meseca, boste imeli pasho, sedemdnevni praznik; jedel se bo nekvašeni kruh.',
        22: 'Na tisti dan bo princ zase in za vse ljudstvo dežele pripravil bikca za daritev za greh.',
        23: 'Sedem dni praznika bo pripravljal žgalno daritev Gospodu, sedem bikcev in sedem ovnov brez pomanjkljivosti, vsak dan, sedem dni; in vsak dan kozlička od koz za daritev za greh.',
        24: 'Pripravil bo jedilno daritev: škaf za bikca, škaf za ovna in vrč olja za škaf.',
        25: 'V sedmem mesecu, na petnajsti dan meseca, bo podobno storil ob prazniku sedmih dni, glede na daritev za greh, glede na žgalno daritev in glede na jedilno daritev in glede na olje.‹',
    },
    46: {
        1: 'Tako govori Gospod Bog: ›Velika vrata notranjega dvora, ki gledajo proti vzhodu, bodo zaprta šest delovnih dni; toda na šabat bodo ta odprta in na mlaj bodo ta odprta.',
        2: 'Princ bo vstopil po poti preddverja teh velikih vrat od zunaj in stal bo pri podboju velikih vrat in duhovniki bodo pripravili njegovo žgalno daritev in njegove mirovne daritve in oboževal bo na pragu velikih vrat in potem bo šel naprej; toda velika vrata ne bodo zaprta do večera.',
        3: 'Podobno bo ljudstvo dežele oboževalo ob vratih teh velikih vrat pred Gospodom na šabate in na mlaje.',
        4: 'Žgalna daritev, ki jo bo princ daroval Gospodu na šabatni dan, bo šest jagnjet brez pomanjkljivosti in oven brez pomanjkljivosti.',
        5: 'Jedilna daritev bo škaf za ovna in jedilna daritev za jagnjeta, kakor bo ta zmožen dati in vrč olja k škafu.',
        6: 'Na dan mlaja bo mlad bikec brez pomanjkljivosti in šest jagnjet in oven; ti bodo brez pomanjkljivosti.',
        7: 'Pripravil bo jedilno daritev, škaf za bikca, škaf za ovna, za jagnjeta pa glede na to, kolikor bo njegova roka dosegla in vrč olja k škafu.',
        8: 'Ko bo princ vstopil, bo vstopil po poti preddverja tistih velikih vrat in naprej bo šel po tisti poti.',
        9: 'Toda ko bo ljudstvo dežele ob slovesnih praznikih prišlo pred Gospoda, bo tisti, ki vstopa po poti severnih velikih vrat, da bi oboževal, šel ven po poti južnih velikih vrat; in tisti, ki vstopa po poti južnih velikih vrat, bo šel naprej po poti severnih velikih vrat. Ne bo se vrnil po poti velikih vrat, pri katerih je vstopil, temveč bo šel naprej proti nasprotnim.',
        10: 'Princ v njihovi sredi bo vstopil, ko bodo oni vstopili; in ko bodo šli naprej, bo šel naprej.',
        11: 'Ob praznikih in ob slovesnostih bo jedilna daritev škaf k bikcu in škaf k ovnu, za jagnjeta pa kolikor je zmožen dati in vrč olja k škafu.',
        12: 'Torej ko bo princ pripravil prostovoljno žgalno daritev ali mirovne daritve prostovoljno Gospodu, mu bo takrat nekdo odprl velika vrata, ki gledajo proti vzhodu in pripravil bo svojo žgalno daritev in svoje mirovne daritve, kot je to storil na šabatni dan. Takrat bo šel naprej in potem ko bo šel naprej, bo nekdo zaprl vrata.',
        13: 'Dnevno boš pripravljal žgalno daritev Gospodu od jagnjeta prvega leta brez pomanjkljivosti. To boš pripravljal vsako jutro.',
        14: 'Zanj boš vsako jutro pripravil jedilno daritev, šesti del škafa in tretji del vrča olja, da to umešaš s fino moko; nenehna jedilna daritev po večni odredbi Gospodu.',
        15: 'Tako bodo pripravili jagnje in jedilno daritev in olje, vsako jutro za nenehno žgalno daritev.‹',
        16: 'Tako govori Gospod Bog: ›Če da princ darilo kateremukoli izmed svojih sinov, bo ta dediščina od njegovih sinov; to bo njihova posest po dediščini.',
        17: 'Toda če da darilo svoje dediščine enemu izmed svojih služabnikov, potem bo to njegovo do leta osvoboditve; po tem se bo vrnilo princu, toda njegova dediščina bo za njegove sinove.',
        18: 'Še več, princ ne bo vzel od dediščine ljudstva z zatiranjem, da bi jih sunil iz njihove posesti, temveč bo dal dediščino svojim sinovom od svoje lastne posesti, da moje ljudstvo ne bo razpršeno, vsak mož iz svoje posesti.‹«',
        19: 'Potem me je privedel skozi vhod, ki je bil ob strani velikih vrat, v svete sobe duhovnikov, ki so gledale proti severu, in glej, tam je bil kraj, na dveh straneh proti zahodu.',
        20: 'Potem mi je rekel: »To je kraj, kjer bodo duhovniki vreli daritev za prestopek in daritev za greh in kjer bodo pekli jedilno daritev; da jih ne bodo nosili ven na skrajni dvor, da bi posvetili ljudstvo.«',
        21: 'Potem me je privedel na skrajni dvor in mi storil, da grem mimo štirih vogalov dvora; in glej, na vsakem vogalu dvora je bil dvor.',
        22: 'Na štirih vogalih dvora so bili dvori združeni iz štiridesetih komolcev dolžine in tridesetih širine. Ti štirje vogali so bili ene mere.',
        23: 'Tam je bila okoli njih vrsta zgradb, okrog vseh štirih in narejena je bila s kraji za vretje pod vrstami naokrog.',
        24: 'Potem mi je rekel: »To so kraji tistih, ki vrejo, kjer bodo služabniki hiše vreli klavno daritev ljudstva.«',
    },
    47: {
        1: 'Potem me je ponovno privedel k vratom hiše; in glej, vode so izhajale ven izpod praga hiše proti vzhodu, kajti pročelje hiše je stalo proti vzhodu in vode so prihajale dol izpod desne strani hiše pri južni strani oltarja.',
        2: 'Potem me je privedel ven, po poti velikih vrat proti severu in me vodil naokrog po zunanji poti, k skrajnim velikim vratom, po poti, ki gleda proti vzhodu in glej, tam so vode iztekale na desni strani.',
        3: 'Ko je človek, ki je imel v svoji roki vrvico, šel proti vzhodu, je izmeril tisoč komolcev in me privedel skozi vode; vode so bile do gležnjev.',
        4: 'Ponovno je izmeril tisoč in me privedel skozi vode; vode so bile do kolen. Ponovno je izmeril tisoč in me privedel skozi; vode so bile do ledij.',
        5: 'Potem je izmeril tisoč; in to je bila reka, ki je nisem mogel prebresti, kajti vode so narasle, vode za plavanje v njih, reka, ki ne more biti prebredena.',
        6: 'Rekel mi je: »Človeški sin, ali si videl tole?« Potem me je privedel in mi storil, da se vrnem k bregu reke.',
        7: 'Torej, ko sem se vrnil, glej, na bregu reke je bilo zelo veliko dreves na tej strani in na drugi.',
        8: 'Potem mi je rekel: »Te vode iztekajo proti vzhodni deželi in gredo dol v puščavo in gredo v morje; katerega vode, ko bodo privedene v morje, bodo ozdravljene.',
        9: 'In zgodilo se bo, da vsaka stvar, ki živi, ki se giblje, kamor koli bodo prišle reke, bo živela, in tam bo zelo velika množica rib, ker bodo te vode prišle tja, kajti ozdravljene bodo; in vsaka stvar bo živela, kamor prihaja reka.',
        10: 'In zgodilo se bo, da bodo na njej stali ribiči, od En Gedija celo do En Eglájima; one bodo kraj za razširjanje mrež; njihovih rib bo glede na njihove vrste, kakor rib vélikega morja, izjemno veliko.',
        11: 'Toda njeni blatni kraji in njena močvirja ne bodo ozdravljena; izročena bodo soli.',
        12: 'Ob reki, na njenem bregu, na tej strani in na tisti strani, bodo rasla vsa drevesa za hrano, katerih listje ne bo ovenelo niti njihov sad ne bo použit. Rodila bodo nov sad, glede na njegove mesece, ker so njihove vode izvirale iz svetišča in njihov sad bo za hrano in njihovo listje bo za zdravilo.«',
        13: 'Tako govori Gospod Bog: »To bo meja, po kateri boste podedovali deželo glede na dvanajst Izraelovih rodov. Jožef bo imel dva deleža.',
        14: 'To boste podedovali, tako eden kakor drugi; glede katere sem dvignil svojo roko, da jo izročim vašim očetom, in ta dežela bo padla vam v dediščino.',
        15: 'To bo meja dežele proti severni strani, od vélikega morja, pot Hetlóna, kakor gredo ljudje v Cedád;',
        16: 'Hamát, Beróte, Sibrájim, ki je med mejo Damaska in mejo Hamáta; Hacár Atikon, ki je ob obali Havrána.',
        17: 'Meja od morja bo Hacár Enán, meja Damaska in severno proti severu in meja Hamáta. To je severna stran.',
        18: 'Vzhodno stran boš meril od Havrána in od Damaska in od Gileáda in od dežele Izrael ob Jordanu, od meje k vzhodnemu morju. To je vzhodna stran.',
        19: 'Južna stran proti jugu, od Tamára celó k vodam prepira v Kadešu, reka k vélikemu morju. To je južna stran proti jugu.',
        20: 'Tudi zahodna stran bo véliko morje od meje, dokler človek ne pride nasproti Hamátu. To je zahodna stran.',
        21: 'Tako si boste razdelili to deželo glede na Izraelove rodove.',
        22: 'Zgodilo se bo, da jo boste razdelili z žrebom v dediščino sebi in tujcem, ki začasno prebivajo med vami, ki bodo med vami zaplodili otroke in oni vam bodo kakor rojeni v deželi med Izraelovimi otroki; imeli bodo dediščino z vami med Izraelovimi rodovi.',
        23: 'In zgodilo se bo, da pri rodu, v katerem začasno prebiva tujec, tam mu boste dali njegovo dediščino,« govori Gospod Bog.',
    },
    48: {
        1: 'Torej to so imena rodov. Od severnega konca do obale, po poti v Hetlón, kot gre nekdo do Hamáta, Hacár Enána, meje Damaska proti severu, do obale Hamáta; kajti to so njegove strani vzhodno in zahodno; delež za Dan.',
        2: 'Ob meji Dana, od vzhodne strani do zahodne strani, delež za Aserja.',
        3: 'Ob meji Aserja, od vzhodne strani, celo do zahodne strani, delež za Neftálija.',
        4: 'Ob meji Neftálija, od vzhodne strani do zahodne strani, delež za Manáseja.',
        5: 'Ob meji Manáseja, od vzhodne strani do zahodne strani, delež za Efrájim.',
        6: 'Ob meji Efrájima, od vzhodne strani, celo do zahodne strani, delež za Rubena.',
        7: 'Ob meji Rubena, od vzhodne strani do zahodne strani, delež za Juda.',
        8: 'Ob meji Juda, od vzhodne strani do zahodne strani, bo daritev, ki jo boste darovali petindvajset tisoč trstik po širini in po dolžini kakor enega izmed drugih deležev, od vzhodne strani do zahodne strani, in svetišče bo v njegovi sredi.',
        9: '§ Daritev, ki jo boste darovali Gospodu, bo petindvajset tisoč po dolžini in deset tisoč po širini.',
        10: 'Zanje, celó za duhovnike, bo to sveta daritev; proti severu petindvajset tisoč po dolžini in proti zahodu deset tisoč po širini in proti vzhodu deset tisoč po širini in proti jugu petindvajset tisoč po dolžini; in Gospodovo svetišče bo v njegovi sredi.',
        11: 'To bo za duhovnike, ki so posvečeni izmed Cadókovih sinov; ki so se držali moje zadolžitve, ki niso zašli, ko so Izraelovi otroci zašli, kakor so zašli Lévijevci.',
        12: 'Ta daritev dežele, ki je darovana, jim bo najsvetejša stvar ob meji Lévijevcev.',
        13: 'Nasproti meji duhovnikov bodo Lévijevci imeli petindvajset tisoč po dolžini in deset tisoč po širini; vsa dolžina bo petindvajset tisoč in širina deset tisoč.',
        14: 'In od tega ne bodo prodali niti zamenjali niti odtujili prvih sadov dežele, kajti to je sveto Gospodu.',
        15: 'Pet tisoč, ki preostanejo po širini, nasproti petindvajset tisočem, bo oskrunjen kraj za mesto, za prebivanje in za predmestja; in mesto bo v njegovi sredi.',
        16: 'To bodo njegove mere: severna stran štiri tisoč petsto, južna stran štiri tisoč petsto, na vzhodni strani štiri tisoč petsto in zahodna stran štiri tisoč petsto.',
        17: 'Predmestja mesta bodo proti severu dvesto petdeset, proti jugu dvesto petdeset, proti vzhodu dvesto petdeset in proti zahodu dvesto petdeset.',
        18: 'Preostanek v dolžini nasproti daritve svetega deleža bo deset tisoč proti vzhodu in deset tisoč proti zahodu, in to bo nasproti daritve svetega deleža; njegov donos bo za hrano tistim, ki služijo mestu.',
        19: 'Tisti, ki služijo mestu, mu bodo služili izmed vseh Izraelovih rodov.',
        20: 'Vseh daritev bo petindvajset tisoč krat petindvajset tisoč. Darovali boste štirioglato sveto daritev z mestno posestjo.',
        21: 'Preostanek pa bo za princa na eni strani in na drugi od svete daritve in od mestne posesti nasproti petindvajset tisočim od daritve proti vzhodni meji in zahodno, nasproti petindvajset tisočim proti zahodni meji, nasproti deležem za princa. To bo sveta daritev in svetišče hiše bo v njegovi sredi.',
        22: 'Poleg tega bo za princa od posesti Lévijevcev in od mestne posesti, ki je v sredi tega, kar pripada princu, med Judovo mejo in Benjaminovo mejo.',
        23: 'Glede preostanka rodov od vzhodne strani do zahodne strani bo imel delež Benjamin.',
        24: 'Ob Benjaminovi meji, od vzhodne strani do zahodne strani, bo imel delež Simeon.',
        25: 'Ob Simeonovi meji, od vzhodne strani do zahodne strani, Isahárjev delež.',
        26: 'Ob Isahárjevi meji, od vzhodne strani do zahodne strani, Zábulonov delež.',
        27: 'Ob Zábulonovi meji, od vzhodne strani do zahodne strani, Gadov delež.',
        28: 'Ob Gadovi meji, pri južni strani proti jugu, bo meja celo od Tamára do vodá prepira v Kadešu in do reke proti vélikemu morju.',
        29: 'To je dežela, ki jo boste razdelili z žrebom Izraelovim rodovom za dediščino in to so njihovi deleži,« govori Gospod Bog.',
        30: 'To so izhodi iz mesta na severni strani, štiri tisoč petsto mer.',
        31: 'Velika vrata mesta bodo po imenih Izraelovih rodov; troje velikih vrat proti severu: ena Rubenova velika vrata, ena Judova velika vrata, ena Lévijeva velika vrata.',
        32: 'Pri vzhodni strani štiri tisoč petsto; in troje velikih vrat: in ena Jožefova velika vrata, ena Benjaminova velika vrata, ena Danova velika vrata.',
        33: 'Pri južni strani štiri tisoč petsto mer; in troje velikih vrat: ena Simeonova velika vrata, ena Isahárjeva velika vrata, ena Zábulonova velika vrata.',
        34: 'Pri zahodni strani štiri tisoč petsto, z njihovimi tremi velikimi vrati: ena Gadova velika vrata, ena Aserjeva velika vrata, ena Neftálijeva velika vrata.',
        35: 'Naokoli je bilo osemnajst tisoč mer. Ime mesta bo od tega dne: Gospod je tam.',
    },
}
